/* テキスト拡充・第4弾(担当:hseng 高校英語 23単元) */
(function (L) {
  function add(id, o) { var x = L[id]; if (!x) return; ['pat', 'more'].forEach(function (k) { if (o[k]) x[k] = (x[k] || []).concat(o[k]); }); }

  add('e_h1', {
    pat: [
      { name: 'SVC の C:形容詞か副詞か', freq: 'とてもよく出る', when: 'look・sound・taste・remain・stay・keep などの直後が空所で、選択肢に happy / happily のような形容詞と副詞が並んでいるときです。', how: ['空所の前の動詞が「〜に見える・〜のままだ・〜になる」の SVC 動詞かを確かめます。', '「S = 空所の語」が成り立つかを考えます。成り立てば C なので形容詞を選びます。', '日本語訳の「〜に」「〜く」につられて副詞を選ばないよう、最後に S の状態を説明しているかを確認します。'], ex: { q: '( ) に入る語を選ぼう。\nThe soup tastes (strange / strangely).', a: 'strange', exp: 'taste は「〜な味がする」という SVC の動詞です。「スープ = 変な(味)」と S の状態を説明しているので、C になれる形容詞 strange が入ります。副詞は C になれません。訳:そのスープは変な味がする。' } },
      { name: 'SVOO か SVOC か(O の後ろの名詞の判定)', freq: 'よく出る', when: 'make・call・find・leave などの後ろに名詞が2つ並んでいて、文型や訳を問われるときです。', how: ['動詞の後ろの2つの名詞(または名詞と形容詞)に線を引きます。', '1つ目 = 2つ目 の関係(主語と述語の関係)が成り立つかを考えます。', '成り立てば SVOC(O を C に・O が C だと)、成り立たなければ SVOO(O に O を)と決めて訳します。'], ex: { q: '文型を答えて和訳しよう。\nHer parents named the puppy Coco.', a: '第5文型(SVOC)。彼女の両親はその子犬をココと名づけた。', exp: 'the puppy = Coco(子犬はココだ)の関係が成り立つので O+C です。name O C で「O を C と名づける」。SVOO なら「子犬にココを与える」となり意味が通りません。' } },
      { name: '前置詞のいらない他動詞・いる自動詞', freq: 'とてもよく出る', when: 'discuss・enter・reach・marry・resemble・approach や、apologize・complain・graduate の後ろの前置詞の有無を問う正誤問題・空所補充です。', how: ['動詞が直接 O をとる他動詞か、前置詞が必要な自動詞かを思い出します。', '日本語「〜について話し合う」「〜に入る」につられて about・into を入れていないか確かめます。', 'よく出る組を対にして覚えます(discuss ↔ talk about、reach ↔ arrive at、enter ↔ go into)。'], ex: { q: '誤りを直そう。\nWe discussed about the school festival for an hour.', a: 'about を取る(We discussed the school festival …)。', exp: 'discuss は「〜について話し合う」という意味の他動詞で、後ろにすぐ O をとります。「について」という日本語に引っぱられて about を入れるのは典型的な誤りです。talk about なら前置詞が必要です。' } },
      { name: '長い主語をもつ文の V と文型', freq: '難関大で出る', when: '文頭に What 〜 や関係詞節つきの長い名詞があり、動詞が2つ以上出てくる文の文型や和訳を問われるときです。', how: ['動詞に印をつけ、接続詞・関係詞・疑問詞の数を数えます(動詞の数 = それらの数 + 1)。', 'What 節や関係詞節など、主語の中に入っている動詞をかっこでくくります。', '残った動詞が文の V です。その後ろの形から文型を決め、主語のかたまりから訳します。'], ex: { q: '文の V と文型を答えよう。\nWhat surprised me most about the trip was how kind the local people were.', a: 'V は was。第2文型(SVC)。', exp: 'What surprised me most about the trip が主語(名詞節)で、その中の surprised は文の V ではありません。was の後ろの how kind … were は名詞節で C です。訳:旅行で一番驚いたのは、地元の人々がどれほど親切かということだった。' } },
      { name: '形式目的語 it の SVOC', freq: 'よく出る', when: 'find・make・think・consider の直後に it があり、その後ろに形容詞と to 不定詞(または that 節)が続くときです。', how: ['動詞の直後の it が「前の何か」を指していないかを確かめます。', '指すものがなく、後ろに to 〜 や that 〜 があれば、it は形式目的語です。', '「(to 以下)を C だと思う・C にする」と、本当の O を it の位置に入れて訳します。'], ex: { q: '和訳しよう。\nThe new app makes it easy to share photos with friends.', a: 'その新しいアプリのおかげで、友だちと写真を共有するのが簡単になる。', exp: 'it は to share photos with friends を指す形式目的語で、easy が C です。make O C で「O を C にする」。無生物主語なので「アプリのおかげで〜」と訳すと自然な日本語になります。' } }
    ],
    more: [
      { lv: 1, q: '文型を答えよう。\nThe leaves turned yellow in October.', a: '第2文型(SVC)', exp: 'turn は「〜になる」という変化の SVC 動詞です。The leaves = yellow(葉が黄色い)が成り立つので yellow は C、in October は M です。' },
      { lv: 1, q: '( ) に入る最も適切なものを選ぼう。\nHe looked ( ) when he heard the news.', choices: ['happily', 'happy', 'happiness', 'to happy'], a: 'B(happy)', exp: 'look は「〜に見える」の SVC 動詞で、後ろは S の状態を表す C です。C になれるのは形容詞なので happy。副詞 happily は C になれません。' },
      { lv: 1, q: '前置詞を使って SVO の文に書きかえよう。\nMy aunt sent me a postcard from Paris.', a: 'My aunt sent a postcard to me from Paris.', exp: 'send は「相手に届く」ことが前提の動詞なので to を使います。SVOO の「人」を後ろに回すときは、動詞によって to か for かを決めます。' },
      { lv: 1, q: '文型を答えて和訳しよう。\nThe students elected her captain of the team.', a: '第5文型(SVOC)。生徒たちは彼女をチームのキャプテンに選んだ。', exp: 'her = captain(彼女がキャプテンだ)の関係が成り立つので O+C です。elect O C で「O を C に選ぶ」。役職名の C には a・the がつかないことが多いです。' },
      { lv: 1, q: '誤りを直そう。\nShe entered into the classroom quietly.', a: 'into を取る(She entered the classroom quietly.)', exp: 'enter は「〜に入る」という意味の他動詞で、後ろにすぐ O をとります。go into the classroom なら into が必要ですが、enter には不要です。' },
      { lv: 1, q: '第1文型(SV)の文を選ぼう。', choices: ['The baby slept soundly.', 'He is a doctor.', 'I like music.', 'They gave me a pen.'], a: 'A(The baby slept soundly.)', exp: 'slept は O も C もとらず、soundly(ぐっすり)は副詞で M です。B は SVC、C は SVO、D は SVOO です。' },
      { lv: 1, q: '文型を答えて和訳しよう。\nPlease keep the door open.', a: '第5文型(SVOC)。ドアを開けたままにしておいてください。', exp: 'the door = open(ドアが開いている)が成り立つので O+C です。keep O C で「O を C のままにしておく」。open はここでは形容詞です。' },
      { lv: 2, q: '( ) に to か for を入れよう。\n(1) Father bought a bike ( ) my sister.\n(2) I showed my notebook ( ) the teacher.', a: '(1) for (2) to', exp: 'buy は「相手のために」する動作で、相手がいなくても買えるので for。show は相手に見せることが前提の動作なので to です。' },
      { lv: 2, q: '( ) に入る最も適切なものを選ぼう。\nThe long wait made the passengers ( ).', choices: ['impatiently', 'impatient', 'impatience', 'to impatient'], a: 'B(impatient)', exp: 'make O C で「O を C にする」。passengers = impatient(乗客がいらいらしている)なので C は形容詞です。訳:長い待ち時間で乗客はいらいらした。' },
      { lv: 2, q: '2文の文型と意味のちがいを答えよう。\n(1) He got angry.\n(2) He got a letter.', a: '(1) SVC:彼は怒った。(2) SVO:彼は手紙を受け取った。', exp: '(1) は He = angry が成り立つので C で、get は「〜になる」。(2) は He ≠ a letter なので O で、get は「〜を得る」。後ろの語との関係で get の意味も決まります。' },
      { lv: 2, q: '誤りを直そう。\nThe girl resembles to her grandmother.', a: 'to を取る(The girl resembles her grandmother.)', exp: 'resemble は「〜に似ている」という意味の他動詞で、前置詞は不要です。また状態を表す動詞なので、進行形や受動態にもふつうしません。' },
      { lv: 2, q: '( ) に入る最も適切なものを選ぼう。\nCould you explain the rules ( )?', choices: ['me', 'to me', 'for me', 'with me'], a: 'B(to me)', exp: 'explain は SVOO をとれない動詞なので、explain me the rules とは言えません。「説明する相手」は to で表し、explain the rules to me とします。' },
      { lv: 2, q: '文型を答えよう。\nThere are three old temples near the station.', a: '第1文型(SV)', exp: 'There 構文では、be 動詞の後ろの three old temples が S、are が V です。There と near the station は M なので、SV の第1文型になります。' },
      { lv: 2, q: '並べかえて英文を作ろう。\n「私はその仕事を1日で終えるのは無理だとわかった。」\nI (it / to / impossible / found / finish) the work in a day.', a: 'I found it impossible to finish the work in a day.', exp: 'find it C to 〜 で「〜するのは C だとわかる」。it が形式目的語、to finish the work in a day が本当の O、impossible が C です。' },
      { lv: 2, q: 'SVOO の形(V+人+物)で使えない動詞を選ぼう。', choices: ['give', 'tell', 'suggest', 'show'], a: 'C(suggest)', exp: 'suggest は suggest me a plan とは言えず、suggest a plan to me とします。explain・introduce・describe も同じなかまで、入試の正誤でよくねらわれます。' },
      { lv: 3, q: '文型を答えて和訳しよう。\nThis medicine will make you feel better.', a: '第5文型(SVOC)。この薬を飲めば気分がよくなるでしょう。', exp: 'make O 原形 は「O に〜させる」の SVOC で、you が O、feel better が C です。無生物主語なので「この薬を飲めば」と条件のように訳すと自然です。' },
      { lv: 3, q: '2文の文型と意味のちがいを答えよう。\n(1) I found the book easily.\n(2) I found the book easy.', a: '(1) SVO:私はその本を簡単に見つけた。(2) SVOC:私はその本がやさしいとわかった。', exp: '(1) の easily は副詞で M、find は「見つける」。(2) の easy は形容詞で the book = easy の C なので、find は「わかる」。1語の品詞で文型も訳も変わります。' },
      { lv: 3, q: '文の V と文型を答え、和訳しよう。\nWhat made him change his mind remains a mystery.', a: 'V は remains。第2文型(SVC)。何が彼の考えを変えさせたのかは、なぞのままだ。', exp: 'What made him change his mind が主語の名詞節です。その中の made は文の V ではありません。remain は SVC の動詞で、a mystery が C です。' },
      { lv: 3, q: '誤りを1か所直そう。\nThey kept silently all through the long meeting.', a: 'silently → silent', exp: 'keep には「〜のままでいる」という SVC の用法があり、後ろは C です。C になれるのは形容詞なので silent にします。all through 〜 は「〜の間ずっと」の M です。' },
      { lv: 3, q: '文型を答え、it が何を指すかを説明しよう。\nI think it important that we keep our promises.', a: '第5文型(SVOC)。it は that we keep our promises を指す形式目的語。', exp: 'think O C で「O を C だと思う」。O に長い that 節を置くと文が重くなるので、it を仮に置き、that 節を後ろに回します。訳:約束を守ることは大切だと思う。' }
    ]
  });

  add('e_pastperf', {
    pat: [
      { name: '基準となる過去の時点を探す', freq: 'とてもよく出る', when: 'When I arrived, / By the time 〜 / before 〜 など過去の時点を表す語句があり、もう一方の動詞の形を問う空所補充です。', how: ['文の中から「過去のある時点(基準)」を表す節や語句を見つけます。', '問われている動作が、その基準より前に起きた(完了していた)のか、同時なのかを判断します。', '基準より前なら had + 過去分詞、同時や基準の後なら過去形を選びます。'], ex: { q: '( ) 内の動詞を正しい形にしよう。\nWhen we reached the stadium, the game ( already start ).', a: 'had already started', exp: '基準は we reached the stadium(過去)。試合が始まったのは到着より前で、その時点で「すでに始まっていた」という完了なので、過去完了 had already started を使います。' } },
      { name: '過去完了進行形:基準の時点まで続いていた動作', freq: 'よく出る', when: 'for + 期間 と when / before / by the time + 過去 がいっしょに出てきて、動作がその時点まで続いていたことを表すときです。', how: ['for 〜(期間)と、過去の基準(when 〜 など)の両方があるか確かめます。', '動詞が study・wait・rain のような動作動詞なら had been 〜ing、know・be のような状態動詞なら had + 過去分詞にします。', '基準の時点でその動作が終わったか、まだ続いていたかは文脈で読みます。'], ex: { q: '( ) 内の動詞を正しい形にしよう。\nShe ( practice ) the piano for three hours when her friend called.', a: 'had been practicing', exp: 'for three hours(期間)と when her friend called(過去の基準)があり、電話の時点まで練習が続いていました。practice は動作動詞なので過去完了進行形にします。' } },
      { name: '「〜しないうちに…した」had not 〜 before / when', freq: 'よく出る', when: '「〜しないうちに」「〜するかしないかのうちに」という和訳・英訳や、had not 〜 long / far before … の形が出てくるときです。', how: ['「先に起きた(まだ〜していなかった)こと」と「後に起きたこと」に分けます。', '先の側を had not + 過去分詞、後の側を過去形にします。', 'before で後の出来事をつなぎ、「…しないうちに〜した」と後ろから訳すと自然です。'], ex: { q: '和訳しよう。\nWe had not walked far before it began to rain.', a: '私たちがあまり歩かないうちに、雨が降り始めた。', exp: '「遠くまで歩いていない(had not walked far)うちに、雨が降り始めた(began)」という順序です。直訳の「雨が降り始める前に遠くまで歩いていなかった」を自然な日本語に直します。' } },
      { name: '過去完了を使わなくてよい場合', freq: '難関大で出る', when: 'after・before で前後関係がはっきりしている文や、起きた順に並べた文の正誤・書きかえ問題です。', how: ['after・before など、順序を表す語があるかを確かめます。', 'あれば前後関係が明らかなので、過去形だけでも正しいと判断します(過去完了も誤りではありません)。', '出来事を起きた順に and でつないでいるときは、どちらも過去形にします。'], ex: { q: 'どちらも正しい文か。理由も答えよう。\n(1) After he finished his homework, he went out.\n(2) After he had finished his homework, he went out.', a: 'どちらも正しい。', exp: 'after があるので、宿題が先で外出が後という順序は語の意味から明らかです。そのため過去形だけでも誤りではありません。(2) は「終えてしまってから」と完了をはっきり示した形です。' } },
      { name: 'ago と before:基準が今か過去か', freq: 'よく出る', when: '間接話法への書きかえや、He said that … のような過去の発言の中に「〜前に」が出てくるときです。', how: ['「〜前」の基準が「今」なのか「過去のある時点」なのかを確かめます。', '今が基準なら ago + 過去形、過去が基準なら before + 過去完了にします。', '間接話法では yesterday → the day before、ago → before のように、基準に合わせて語も直します。'], ex: { q: '間接話法に書きかえよう。\nShe said, “I moved to Osaka two years ago.”', a: 'She said (that) she had moved to Osaka two years before.', exp: '発言の時点(過去)が基準になり、引っこしはそれより前なので had moved にします。ago は今から見た「〜前」なので、過去が基準の before に変えます。' } }
    ],
    more: [
      { lv: 1, q: '( ) 内の動詞を正しい形にしよう。\nWhen I opened the box, the cookies ( disappear ).', a: 'had disappeared', exp: '基準は箱を開けた時点(過去)で、クッキーがなくなったのはそれより前です。「すでになくなっていた」という完了なので had + 過去分詞にします。' },
      { lv: 1, q: '( ) に入る最も適切なものを選ぼう。\nI ( ) that movie before, so I knew the ending.', choices: ['see', 'have seen', 'had seen', 'was seeing'], a: 'C(had seen)', exp: '結末を知っていた(knew)という過去の時点より前に見たことがあったので、経験の過去完了です。現在完了は過去の基準とは使えません。' },
      { lv: 1, q: '和訳しよう。\nThe concert had already begun when we got there.', a: '私たちがそこに着いたとき、コンサートはもう始まっていた。', exp: 'had already begun は、着いた時点(過去)ですでに始まっていたという完了を表します。already は「もう・すでに」です。' },
      { lv: 1, q: '( ) 内の動詞を正しい形にしよう。\nHe ( live ) in Kobe for five years before he moved to Tokyo.', a: 'had lived', exp: '東京に引っこした(過去)時点までの5年間の継続です。live は状態に近い動詞なので過去完了 had lived を使います。' },
      { lv: 1, q: '( ) に入る最も適切なものを選ぼう。\nShe lost the watch that her father ( ) her.', choices: ['gives', 'has given', 'had given', 'will give'], a: 'C(had given)', exp: '時計をなくした(lost)より前に父がくれていたので、大過去の had given を使います。時間の順に気をつけましょう。' },
      { lv: 1, q: '過去完了の形として正しいものを選ぼう。', choices: ['had wrote', 'had written', 'has wrote', 'had write'], a: 'B(had written)', exp: '過去完了は had + 過去分詞です。write の過去分詞は written で、wrote は過去形です。不規則動詞の活用を確かめましょう。' },
      { lv: 1, q: '和訳しよう。\nI had never eaten Thai food until last summer.', a: '私は去年の夏まで、タイ料理を一度も食べたことがなかった。', exp: 'until last summer が基準の過去の時点で、それまでの経験がなかったことを had never eaten で表しています。' },
      { lv: 2, q: '( ) 内の動詞を正しい形にしよう。\nHer eyes were red because she ( cry ) for a long time.', a: 'had been crying', exp: '目が赤かった(過去)のは、その直前まで長い間泣き続けていたからです。for a long time と動作動詞 cry なので過去完了進行形にします。' },
      { lv: 2, q: '( ) に入る最も適切なものを選ぼう。\nBy the time the doctor arrived, the patient ( ) better.', choices: ['gets', 'has got', 'had got', 'will get'], a: 'C(had got)', exp: 'By the time the doctor arrived が過去の基準です。その時点までに患者はよくなっていたので過去完了を使います。' },
      { lv: 2, q: '誤りを直そう。\nI have finished my homework when my mother came home.', a: 'have finished → had finished', exp: '基準は when my mother came home(過去)です。現在完了は「今」が基準なので、過去の時点とはいっしょに使えません。過去完了にします。' },
      { lv: 2, q: '2文の意味のちがいを説明しよう。\n(1) When I arrived, she left.\n(2) When I arrived, she had left.', a: '(1) 私が着いたとき(着くと)、彼女は出ていった。(2) 私が着いたとき、彼女はもう出ていた。', exp: '(1) は到着と出発がほぼ同時かすぐ後で、2人は会った可能性があります。(2) は到着より前に出発が完了していたので、会えていません。' },
      { lv: 2, q: '間接話法に書きかえよう。\nHe said to me, “I found your wallet yesterday.”', a: 'He told me (that) he had found my wallet the day before.', exp: '発言より前のことなので had found、yesterday は過去が基準の the day before、your は話し手から見た my に直します。said to は told にします。' },
      { lv: 2, q: '( ) に入る最も適切なものを選ぼう。\nIt was the first time I ( ) such a beautiful sunset.', choices: ['see', 'saw', 'had seen', 'have seen'], a: 'C(had seen)', exp: 'It was the first time (that) 〜 では、その時点までの経験を表すので過去完了を使います。It is the first time なら現在完了です。' },
      { lv: 2, q: '英訳しよう。\n「私が駅に着く前に、電車は出てしまっていた。」', a: 'The train had left before I got to the station.', exp: '電車の出発が先、私の到着が後です。先のほうを had left、後のほうを過去形 got にします。before があるので The train left before 〜 でも誤りではありません。' },
      { lv: 2, q: '( ) 内の動詞を正しい形にしよう。\nI ( know ) him for ten years when he finally told me his secret.', a: 'had known', exp: '秘密を打ち明けられた時点(過去)まで10年間知り合いだった、という継続です。know は状態動詞なので進行形にせず、had known にします。' },
      { lv: 3, q: '英訳しよう。\n「家を出るか出ないかのうちに、雨が激しく降り始めた。」', a: 'I had hardly left home when it began to rain heavily.\n(Hardly had I left home when it began to rain heavily. も可)', exp: '「〜するかしないかのうちに」は hardly 〜 when … で表し、先の動作を had hardly + 過去分詞、後の動作を過去形にします。Hardly を文頭に出すと倒置になります。' },
      { lv: 3, q: '下線部の時制の理由を説明しよう。\nShe 【had hoped】 to see the cherry blossoms, but they had all fallen by then.', a: '「見たいと思っていたが、実現しなかった」という気持ちを表すため。', exp: 'had hoped・had intended・had expected は「〜するつもりだった(が、できなかった)」の意味になります。後ろの but they had all fallen とも合っています。' },
      { lv: 3, q: '( ) に入る最も適切なものを選ぼう。\nHardly ( ) the room when the phone rang.', choices: ['I entered', 'I had entered', 'had I entered', 'did I enter'], a: 'C(had I entered)', exp: 'Hardly had S 過去分詞 when … で「S が〜するとすぐに…した」。否定の意味の Hardly が文頭に出たので、had I entered と倒置します。' },
      { lv: 3, q: '誤りを直し、理由を説明しよう。\nWhen I visited the town last year, it has changed a lot since my childhood.', a: 'has changed → had changed', exp: '基準は去年訪ねた時点(過去)で、子どものころからその時点までの変化を表すので過去完了です。現在完了は今が基準なので使えません。' },
      { lv: 3, q: '和訳しよう。\nNo one had told him about the change, so he was the only person who came to the old meeting room.', a: 'だれも彼にその変更のことを伝えていなかったので、古い会議室に来たのは彼だけだった。', exp: '伝えていなかった(had told)のは、彼が古い部屋に来た時点(過去)より前です。原因が先、結果が後という順序を過去完了で示しています。' }
    ]
  });

  add('e_futperf', {
    pat: [
      { name: 'by + 未来の時点 → will have + 過去分詞', freq: 'とてもよく出る', when: 'by tomorrow・by next week・by five o\'clock など「〜までに」を表す語句が未来の時点とセットで出てくるときです。', how: ['by + 時点を見つけ、それが未来かどうかを確かめます。', 'その時点までに動作が「終わっている」ことを表す文なら will have + 過去分詞を選びます。', 'until(〜までずっと)なら継続の意味になるので、動詞の形と前置詞をセットで確認します。'], ex: { q: '( ) 内の動詞を正しい形にしよう。\nThe workers ( repair ) the bridge by the end of next month.', a: 'will have repaired', exp: 'by the end of next month は未来の期限です。その時点までに修理が「終わっている」ことを表すので、未来完了 will have repaired を使います。' } },
      { name: 'by the time + 現在形 と主節の未来完了', freq: 'とてもよく出る', when: 'By the time S V, … や When S V, … の形で、主節が未来の話になっている文の時制を問うときです。', how: ['By the time 〜 は時を表す副詞節なので、中は未来のことでも現在形にします。', '主節は「その時点までに完了しているか」を考えます。', '完了していれば will have + 過去分詞、その時点で進行中なら will be 〜ing にします。'], ex: { q: '( ) 内の動詞を正しい形にしよう。\nBy the time you ( come ) back, we ( finish ) dinner.', a: 'come / will have finished', exp: 'By the time の節は時の副詞節なので、未来でも現在形 come です。主節は「戻ってくる時点までに夕食を食べ終えている」という完了なので will have finished です。' } },
      { name: '期間の計算:next 〜 で …年になる', freq: 'よく出る', when: '「来月で〜年になる」「来年の春で…年間続けていることになる」のように、未来のある時点までの期間を表すときです。', how: ['始まりの時点と、未来の基準の時点を確かめます。', 'その間の期間を計算して for + 期間 で表します。', '状態動詞なら will have + 過去分詞、動作動詞の継続なら will have been 〜ing にします。'], ex: { q: '英訳しよう。\n「今年の12月で、私たちは結婚して20年になる。」', a: 'We will have been married for twenty years this December.', exp: 'be married は「結婚している」状態なので進行形にせず、will have been married for 〜 とします。this December が未来の基準の時点です。' } },
      { name: 'by と until の使い分け', freq: 'とてもよく出る', when: '( ) に by か until を入れる問題や、「〜まで」の日本語を英訳するときです。', how: ['動詞が「1回で終わる動作(提出・到着・完了)」か「続く状態(待つ・いる・開いている)」かを見ます。', '期限までに1回すませるなら by、その時までずっと続くなら until を選びます。', '訳して「〜までに」なら by、「〜までずっと」なら until と確かめます。'], ex: { q: '( ) に by か until を入れよう。\n(1) I\'ll wait for you ( ) six.\n(2) I\'ll be back ( ) six.', a: '(1) until (2) by', exp: '(1) wait は6時まで続く状態なので until。(2) be back(戻る)は6時より前に1回すめばよい動作なので by です。「までずっと」と「までに」で区別します。' } },
      { name: '回数・経験の未来完了', freq: 'よく出る', when: '「もう一度〜すれば…回目になる」「来年行けば3回〜したことになる」という条件と回数がある文です。', how: ['If 〜 again(もう一度〜すれば)など、未来の条件を表す節を見つけます。', 'if 節は現在形のままにします。', '主節は、その時点までの回数・経験を will have + 過去分詞 + 回数で表します。'], ex: { q: '( ) 内の動詞を正しい形にしよう。\nIf I read this novel once more, I ( read ) it five times.', a: 'will have read', exp: 'もう一度読めば、その時点で5回読んだことになる、という経験の未来完了です。if 節は条件の副詞節なので read(現在形)のままで、主節を will have read にします。' } }
    ],
    more: [
      { lv: 1, q: '( ) 内の動詞を正しい形にしよう。\nI ( write ) all the New Year\'s cards by Sunday.', a: 'will have written', exp: 'by Sunday は未来の期限です。その時までに書き終わっているという完了なので will have + 過去分詞にします。write の過去分詞は written です。' },
      { lv: 1, q: '( ) に by か until を入れよう。\nThe museum is closed ( ) next Monday.', a: 'until', exp: '閉館している状態が来週の月曜日までずっと続くので until です。「までに」ではなく「までずっと」の意味になります。' },
      { lv: 1, q: '未来完了の形として正しいものを選ぼう。', choices: ['will has finished', 'will have finished', 'will finished', 'will have finish'], a: 'B(will have finished)', exp: '未来完了は will have + 過去分詞です。will の後ろは原形なので has にはなりません。主語が何であっても will have のままです。' },
      { lv: 1, q: '和訳しよう。\nThe snow will have melted by next week.', a: '来週までには雪はとけてしまっているだろう。', exp: 'will have melted は、来週という未来の時点までに「とけ終わっている」という完了を表します。' },
      { lv: 1, q: '( ) に by か until を入れよう。\nPlease return the book ( ) Friday.', a: 'by', exp: '本を返すのは1回ですむ動作で、金曜日までにすませればよいので by です。until にすると「金曜までずっと返し続ける」ことになってしまいます。' },
      { lv: 1, q: '( ) に入る最も適切なものを選ぼう。\nBy this time tomorrow, I ( ) Hokkaido.', choices: ['arrive', 'arrived', 'will have arrived in', 'have arrived'], a: 'C(will have arrived in)', exp: 'By this time tomorrow(明日の今ごろまでに)は未来の時点です。その時点で到着が完了しているので未来完了を使います。arrive の後ろには in が必要です。' },
      { lv: 1, q: '和訳しよう。\nShe will have left the office by seven.', a: '彼女は7時までには会社を出てしまっているだろう。', exp: 'by seven(7時までに)という未来の時点に、すでに出ているという完了です。「〜してしまっているだろう」と訳します。' },
      { lv: 2, q: '( ) 内の動詞を正しい形にしよう。\nBy the time the guests ( arrive ), we will have cleaned the house.', a: 'arrive', exp: 'By the time 〜 は時を表す副詞節なので、未来のことでも現在形を使います。will arrive にはしません。' },
      { lv: 2, q: '( ) 内の動詞を正しい形にしよう。\nNext April, my brother ( teach ) at this school for ten years.', a: 'will have been teaching(will have taught も可)', exp: '来年の4月という未来の時点までの10年間の継続です。teach は動作動詞なので、継続を強調するなら未来完了進行形が自然です。' },
      { lv: 2, q: '( ) に入る最も適切なものを選ぼう。\nDon\'t visit me at three tomorrow. I ( ) for an exam then.', choices: ['will have studied', 'will be studying', 'study', 'have studied'], a: 'B(will be studying)', exp: '明日の3時という一点で「勉強している最中」なので未来進行形です。完了ではなく進行中の様子を表している点に注意します。' },
      { lv: 2, q: '誤りを直そう。\nBy the time he will retire, he will have worked here for forty years.', a: 'will retire → retires', exp: 'By the time の節は時の副詞節なので、中の動詞は現在形にします。主節の未来完了はそのままで正しい形です。' },
      { lv: 2, q: '英訳しよう。\n「次の試合に出れば、彼は100試合に出たことになる。」', a: 'If he plays in the next game, he will have played in 100 games.', exp: 'if 節は条件の副詞節なので現在形 plays、主節は回数・経験の未来完了 will have played にします。' },
      { lv: 2, q: '2文の意味のちがいを説明しよう。\n(1) I will finish the work at five.\n(2) I will have finished the work by five.', a: '(1) 5時に仕事を終えるつもりだ。(2) 5時までには仕事を終えてしまっているだろう。', exp: '(1) は終える時刻がちょうど5時。(2) は5時より前のどこかで終わり、5時の時点ではすでに完了している、という意味です。' },
      { lv: 2, q: '( ) に入る最も適切なものを選ぼう。\nI\'m afraid the shop ( ) by the time we get there.', choices: ['closes', 'will close', 'will have closed', 'has closed'], a: 'C(will have closed)', exp: '着く時点(未来)までに、店はすでに閉まってしまっているだろう、という完了です。by the time の節の get は現在形のままで正しい形です。' },
      { lv: 2, q: '( ) に by か until を入れ、和訳しよう。\nYou can use my bike ( ) I come back.', a: 'until。私が戻るまで、私の自転車を使っていいよ。', exp: '自転車を使う状態が、戻ってくるときまで続くので until です。until は接続詞としても使え、中は現在形にします。' },
      { lv: 3, q: '( ) 内の動詞を正しい形にしよう。\nWe started the project in 2024. By 2030, we ( work ) on it for six years.', a: 'will have been working', exp: '2024年から2030年までは 2030 − 2024 = 6 年で、未来の時点までの動作の継続です。work は動作動詞なので未来完了進行形にします。' },
      { lv: 3, q: '和訳し、will have の意味を説明しよう。\nThey will have reached the summit by now.', a: '彼らは今ごろはもう山頂に着いているだろう。will have は「今ごろ〜しただろう」という現在の完了への推量。', exp: 'by now(今ごろまでに)があるので、未来ではなく「今の時点ですでに〜しただろう」という推量です。will の推量の用法が完了形と結びついています。' },
      { lv: 3, q: '誤りを2か所直そう。\nWhen you will read this letter, I have left this town.', a: 'will read → read、have left → will have left', exp: 'When の節は時の副詞節なので現在形にします。主節は「読む時点(未来)までに出発してしまっている」という完了なので未来完了にします。' },
      { lv: 3, q: '誤りを直し、理由を説明しよう。\nBy the end of last year, they will have built the new tower.', a: 'will have built → had built', exp: 'by the end of last year は過去の時点です。過去の基準までの完了は過去完了で表します。未来完了は未来の基準のときだけ使います。' },
      { lv: 3, q: '( ) に入る最も適切なものを選ぼう。\nI hope the rain ( ) by the time the festival starts.', choices: ['stops', 'will stop', 'will have stopped', 'has stopped'], a: 'C(will have stopped)', exp: '祭りが始まる時点までに雨がやみ終わっていてほしい、という未来の完了です。hope の後ろの that 節は名詞節なので will が使えます。' }
    ]
  });

  add('e_tense', {
    pat: [
      { name: 'if・when 節:副詞節か名詞節か', freq: 'とてもよく出る', when: 'if・when の節の中が未来のことで、( ) に現在形か will かを選ぶ問題です。主節の動詞が know・ask・wonder・tell かどうかがヒントになります。', how: ['if・when の節を取りのぞいても文が成り立つかを考えます。', '成り立つなら「〜なら・〜とき」の副詞節なので、未来でも現在形にします。', 'know・ask・wonder の O になっていれば「〜かどうか・いつ〜か」の名詞節なので、未来は will を使います。'], ex: { q: '( ) 内の動詞を正しい形にしよう。\n(1) I don\'t know if he ( come ) tomorrow.\n(2) If he ( come ) tomorrow, I\'ll be glad.', a: '(1) will come (2) comes', exp: '(1) の if 節は know の O で「来るかどうか」の名詞節なので will come。(2) は「もし来るなら」の副詞節(条件)なので、未来のことでも現在形 comes です。' } },
      { name: '形容詞節の when:先行詞があれば will', freq: 'よく出る', when: 'the day・the time・the moment など時を表す名詞の直後に when 節が続き、中が未来のことのときです。', how: ['when の直前に、時を表す名詞(先行詞)があるかを確かめます。', '先行詞があれば when 節はその名詞を説明する形容詞節(関係副詞)です。', '形容詞節は時・条件の副詞節ではないので、未来なら will を使います。'], ex: { q: '( ) 内の動詞を正しい形にしよう。\nNobody knows the day when the new station ( open ).', a: 'will open', exp: 'when 節は the day を説明する形容詞節です。時・条件の副詞節ではないので、未来のことは will で表します。訳:新しい駅が開業する日はだれも知らない。' } },
      { name: '副詞節の中の現在完了(完了の強調)', freq: 'よく出る', when: 'after・until・when・as soon as の節の中で、「〜し終えたら」と完了をはっきりさせる必要があるときです。', how: ['副詞節の中の動作が、主節の動作より先に「終わる」ことが大事かを読みます。', '完了をはっきりさせたいときは、will have 〜 ではなく現在完了 have + 過去分詞にします。', '単に時を示すだけなら現在形でもかまいません。'], ex: { q: '( ) 内の動詞を、完了の意味がはっきりする形にしよう。\nYou can go out to play when you ( clean ) your room.', a: 'have cleaned', exp: '「部屋をそうじし終えたら」と完了を強調するので、副詞節の中では現在完了を使います。will have cleaned は副詞節の中では使いません。' } },
      { name: 'unless・in case・once・by the time などの接続詞', freq: 'よく出る', when: 'if・when 以外の接続詞が使われていて、中の時制や意味を問われるときです。', how: ['unless(〜しない限り)、in case(〜するといけないから)、once(いったん〜すると)、by the time(〜するまでに)の意味を確認します。', 'これらも時・条件の副詞節なので、未来のことでも現在形にします。', 'unless は中に not を入れないこと(二重否定になる)にも注意します。'], ex: { q: '誤りを直そう。\nI won\'t go unless you won\'t come with me.', a: 'won\'t come → come', exp: 'unless は「〜しない限り」と、すでに否定の意味をふくむ条件の接続詞です。中は現在形にし、not も入れません。訳:あなたがいっしょに来ない限り、私は行かない。' } },
      { name: '1つの文に複数の節がある時制', freq: '難関大で出る', when: 'I\'m sure that … when … のように、名詞節の中にさらに副詞節が入っている文の時制を問うときです。', how: ['文を節ごとに区切り、それぞれの節が名詞節・形容詞節・副詞節のどれかを決めます。', '時・条件の副詞節だけを現在形にし、名詞節・形容詞節の未来は will のままにします。', '最後に、全体の時間の流れ(どちらが先か)が自然かを確かめます。'], ex: { q: '( ) 内の動詞を正しい形にしよう。\nI\'m sure he ( help ) us if we ( ask ) him.', a: 'will help / ask', exp: 'he … は I\'m sure の後ろの that 節(名詞節)なので未来は will help。その中の if 節は条件の副詞節なので現在形 ask です。節ごとに判断します。' } }
    ],
    more: [
      { lv: 1, q: '( ) 内の動詞を正しい形にしよう。\nI\'ll call you when I ( get ) home.', a: 'get', exp: 'when 節は「〜するとき」の時の副詞節です。未来のことでも現在形を使うので get です。will get にはしません。' },
      { lv: 1, q: '( ) 内の動詞を正しい形にしよう。\nIf it ( be ) fine next Sunday, we\'ll go hiking.', a: 'is', exp: 'If 節は条件の副詞節なので、next Sunday という未来のことでも現在形 is を使います。主節は will を使って未来を表します。' },
      { lv: 1, q: '( ) に入る最も適切なものを選ぼう。\nPlease wait here until the doctor ( ).', choices: ['comes', 'will come', 'came', 'coming'], a: 'A(comes)', exp: 'until 節は時の副詞節なので、未来のことでも現在形です。主語が3人称単数なので comes になります。' },
      { lv: 1, q: '誤りを直そう。\nI\'ll lend you the DVD after I will watch it.', a: 'will watch → watch(have watched も可)', exp: 'after 節は時の副詞節なので、未来のことでも will を使いません。見終えたことを強調するなら have watched にします。' },
      { lv: 1, q: '( ) に入る最も適切なものを選ぼう。\nI\'ll be happy if you ( ) to my party.', choices: ['come', 'will come', 'came', 'coming'], a: 'A(come)', exp: 'if 節は「もし〜なら」の条件の副詞節です。未来の内容でも現在形 come にします。' },
      { lv: 1, q: '和訳しよう。\nAs soon as the rain stops, let\'s start.', a: '雨がやんだらすぐに出発しよう。', exp: 'as soon as 〜 は「〜するとすぐに」の時の副詞節で、未来のことでも現在形 stops です。' },
      { lv: 1, q: '( ) 内の動詞を正しい形にしよう。\nBefore you ( leave ), please turn off the lights.', a: 'leave', exp: 'before 節は時の副詞節なので、これから出かけるという未来のことでも現在形 leave を使います。' },
      { lv: 2, q: '( ) に入る最も適切なものを選ぼう。\nTell me when you ( ) back to Japan.', choices: ['come', 'will come', 'came', 'have come'], a: 'B(will come)', exp: 'when 節は Tell me の O で「いつ帰ってくるか」の名詞節です。名詞節なので未来は will を使います。「帰ってきたら教えて」なら come です。' },
      { lv: 2, q: '( ) 内の動詞を正しい形にしよう。\nI wonder whether she ( pass ) the exam next month.', a: 'will pass', exp: 'whether 節は wonder の O になる「〜かどうか」の名詞節なので、未来のことは will で表します。' },
      { lv: 2, q: '( ) に入る最も適切なものを選ぼう。\nTake a map in case you ( ) lost.', choices: ['get', 'will get', 'got', 'are getting'], a: 'A(get)', exp: 'in case 〜 は「〜するといけないから」の副詞節で、中は現在形です。get lost は「道に迷う」です。' },
      { lv: 2, q: '( ) 内の動詞を正しい形にしよう。\nPlease tell me the date when you ( leave ) for London.', a: 'will leave', exp: 'when 節は the date を説明する形容詞節です。時の副詞節ではないので、未来のことは will を使います。' },
      { lv: 2, q: '和訳しよう。\nOnce you learn to ride a bike, you will never forget how.', a: 'いったん自転車の乗り方を覚えれば、決してその方法を忘れないだろう。', exp: 'once はここでは接続詞で「いったん〜すると」の意味です。条件の副詞節なので learn は現在形です。how の後ろには to ride a bike が省略されています。' },
      { lv: 2, q: '( ) 内の動詞を正しい形にしよう。\nThe next time I ( visit ) Okinawa, I\'ll try diving.', a: 'visit', exp: 'the next time は「今度〜するときは」という接続詞のはたらきをし、時の副詞節を作ります。未来のことでも現在形 visit です。' },
      { lv: 2, q: '( ) に入る最も適切なものを選ぼう。\nIt will not be long before spring ( ).', choices: ['comes', 'will come', 'came', 'has come'], a: 'A(comes)', exp: 'It will not be long before 〜 は「まもなく〜するだろう」。before 節は時の副詞節なので、現在形 comes にします。' },
      { lv: 2, q: '英訳しよう。\n「宿題が終わったら、テレビを見てもいいよ。」', a: 'You can watch TV when you have finished your homework.(after you finish … も可)', exp: '「終わったら」と完了をはっきりさせるので、副詞節の中は現在完了 have finished にします。will have finished にはしません。' },
      { lv: 3, q: '2文の意味のちがいを説明しよう。\n(1) I\'ll tell you if I hear the news.\n(2) I\'ll tell you if I will hear the news.', a: '(1) その知らせを聞いたら教えるよ。(2) その知らせを聞くことになるかどうかを教えるよ。', exp: '(1) の if 節は条件の副詞節で「もし聞いたら」。(2) は tell you の後ろの名詞節で「聞くかどうか」です。時制の形で節の種類が分かります。' },
      { lv: 3, q: '( ) 内の動詞を正しい形にしよう。\nI\'m not sure if the store ( be ) open when we ( get ) there.', a: 'will be / get', exp: 'if 節は I\'m not sure の後ろの「〜かどうか」の名詞節なので will be。その中の when 節は時の副詞節なので、現在形 get です。' },
      { lv: 3, q: '誤りを2か所直そう。\nWhen I will graduate, I will tell you whether I go abroad.', a: 'will graduate → graduate、go → will go', exp: 'When 節は時の副詞節なので現在形 graduate。whether 節は tell の O になる名詞節なので、未来のことは will go にします。' },
      { lv: 3, q: '( ) に入る最も適切なものを選ぼう。\nThe question is whether the plan ( ) in time.', choices: ['is finished', 'will be finished', 'finished', 'finishes'], a: 'B(will be finished)', exp: 'whether 節は is の補語になる名詞節です。名詞節の中の未来は will を使うので、受動態の未来 will be finished です。' },
      { lv: 3, q: '英訳しよう。\n「その仕事を終えるまでは家に帰らないつもりだ、と彼は言っている。」', a: 'He says (that) he won\'t go home until he has finished the work.(until he finishes … も可)', exp: 'that 節(名詞節)の中の未来は won\'t、その中の until 節は時の副詞節なので現在完了(または現在形)です。節の入れ子を順に判断します。' }
    ]
  });

  add('e_aux', {
    pat: [
      { name: '文脈から推量の強さを決める(must / may / can\'t)', freq: 'とてもよく出る', when: '空所に must・may・can\'t などが並び、前後に「根拠」になる情報(明かりがついている・会ったばかり など)が書かれているときです。', how: ['空所の文が「今の推量」か「過去への推量」かを、後ろの動詞の形で確かめます。', '根拠となる文を探し、その根拠からどのくらい確実に言えるかを考えます。', 'ほぼ確実なら must(〜にちがいない)、ありえないなら can\'t(〜のはずがない)、五分五分なら may・might を選びます。'], ex: { q: '( ) に入る最も適切なものを選ぼう。\nHe ( ) be at home. I saw him at the library just a minute ago.', a: 'can\'t', exp: '「たった今図書館で見かけた」という根拠から、家にいることはありえないと強く言えます。強い否定の推量 can\'t(〜のはずがない)を選びます。mustn\'t は「〜してはいけない」の禁止なので不可です。' } },
      { name: '助動詞 + have + 過去分詞:過去への推量', freq: 'とてもよく出る', when: '文の内容が過去のことで、「〜したにちがいない」「〜したはずがない」「〜したかもしれない」と訳す問題や空所補充です。', how: ['推量している対象が過去の出来事かを、yesterday・last night や過去形の文から確かめます。', '助動詞の強さ(must > may > can\'t の否定)を根拠から選びます。', '後ろを have + 過去分詞にして、「過去のこと」を「今」推量している形にします。'], ex: { q: '英訳しよう。\n「道がぬれている。昨夜雨が降ったにちがいない。」', a: 'The road is wet. It must have rained last night.', exp: '推量しているのは今ですが、雨が降ったのは昨夜(過去)なので must have + 過去分詞を使います。must rained や must had rained とは言いません。' } },
      { name: 'should have / needn\'t have:後悔・非難・不要', freq: 'よく出る', when: '「〜すべきだったのに(しなかった)」「〜する必要はなかったのに(してしまった)」という気持ちが文脈にあるときです。', how: ['実際に何があったのか(したのか、しなかったのか)を前後の文から読み取ります。', 'しなかったことを悔やむなら should have + 過去分詞、したことを悔やむなら shouldn\'t have + 過去分詞です。', '「したけれど必要なかった」なら needn\'t have + 過去分詞、「する必要がなかったのでしなかった」なら didn\'t need to を使います。'], ex: { q: '( ) に入る最も適切なものを選ぼう。\nYou ( ) brought an umbrella. It didn\'t rain at all.\n① should have ② needn\'t have ③ must have ④ can\'t have', a: '②(needn\'t have)', exp: 'かさを持ってきた(実際にした)けれど、雨は降らなかったので不要だった、という意味です。「〜する必要はなかったのに」は needn\'t have + 過去分詞で表します。' } },
      { name: '助動詞の慣用表現', freq: 'よく出る', when: 'may well・may as well・cannot help 〜ing・would rather・had better などの決まった形が空所や和訳で問われるときです。', how: ['空所の前後に well・as well・rather・than・help などの目印があるかを見ます。', '形(後ろが原形か ing か、than とセットか)を確認します。', '意味を正確に訳し分けます(may well = 〜するのももっともだ/たぶん〜だろう、may as well = 〜したほうがよい)。'], ex: { q: '和訳しよう。\nShe may well be angry with you. You broke your promise.', a: '彼女があなたに腹を立てるのももっともだ。あなたは約束を破ったのだから。', exp: 'may well 〜 は「〜するのももっともだ」「たぶん〜だろう」の意味です。後ろに約束を破ったという理由があるので「もっともだ」と訳します。' } },
      { name: 'SVOO・SVOC・使役・知覚動詞の受動態', freq: 'とてもよく出る', when: '能動態 ⇔ 受動態の書きかえで、動詞が give・call・make・see・hear のときです。', how: ['能動態の文型を決め、どれを主語にするかを決めます(SVOC なら O だけが主語になれます)。', 'be + 過去分詞にし、残った O や C はそのまま後ろに残します。', 'make・see・hear の後ろの原形は、受動態では to 不定詞になる点に注意します(be made to do, be seen to do)。'], ex: { q: '受動態に書きかえよう。\nThey made the boy wait outside.', a: 'The boy was made to wait outside.', exp: '使役動詞 make の能動態では原形 wait ですが、受動態にすると to が復活して was made to wait になります。知覚動詞 see・hear も同じです。' } }
    ],
    more: [
      { lv: 1, q: '( ) に入る最も適切なものを選ぼう。\nThe lights are on in her room. She ( ) be at home.', choices: ['must', 'can\'t', 'need not', 'had better'], a: 'A(must)', exp: '部屋の明かりがついているという根拠から、家にいるとほぼ確信できます。強い肯定の推量 must(〜にちがいない)を選びます。' },
      { lv: 1, q: '和訳しよう。\nThis story can\'t be true.', a: 'この話は本当であるはずがない。', exp: 'can\'t は「〜のはずがない」という強い否定の推量です。must(〜にちがいない)の反対の意味になります。' },
      { lv: 1, q: '受動態に書きかえよう。\nMany people visit this temple every year.', a: 'This temple is visited by many people every year.', exp: 'O の this temple を主語にし、be + 過去分詞にします。現在の習慣なので is visited、もとの主語は by の後ろに置きます。' },
      { lv: 1, q: '( ) に入る最も適切なものを選ぼう。\nYou ( ) see a doctor. You look very pale.', choices: ['had better', 'had better to', 'would rather to', 'may as'], a: 'A(had better)', exp: 'had better は「〜したほうがよい(さもないと困る)」で、後ろは原形です。had better to とは言いません。' },
      { lv: 1, q: '和訳しよう。\nYou must have been tired after the long trip.', a: '長い旅行のあとで、あなたは疲れていたにちがいない。', exp: 'must have + 過去分詞は「〜したにちがいない・〜だったにちがいない」という過去への推量です。' },
      { lv: 1, q: '受動態に書きかえよう。\nMy grandmother gave me this ring.', a: 'I was given this ring by my grandmother.(This ring was given (to) me by my grandmother. も可)', exp: 'SVOO は、人(me)と物(this ring)のどちらも主語にできます。物を主語にするときは to me のように to を入れることが多いです。' },
      { lv: 1, q: '( ) に入る最も適切なものを選ぼう。\nI couldn\'t help ( ) at his joke.', choices: ['laugh', 'to laugh', 'laughing', 'laughed'], a: 'C(laughing)', exp: 'cannot help 〜ing は「〜せずにはいられない」。help の後ろは動名詞にします。訳:彼の冗談に笑わずにはいられなかった。' },
      { lv: 2, q: '( ) に入る最も適切なものを選ぼう。\nI can\'t find my key. I ( ) left it on the train.', choices: ['must', 'may have', 'should', 'can\'t have'], a: 'B(may have)', exp: 'かぎが見つからないので、電車に置き忘れたかもしれない、という過去への推量です。確信はないので may have + 過去分詞が合います。' },
      { lv: 2, q: '英訳しよう。\n「もっと早く出発するべきだったのに。」', a: 'We should have left earlier.(I should have left earlier. も可)', exp: '実際には早く出発しなかったことを悔やむので、should have + 過去分詞を使います。「〜すべきだったのに(しなかった)」の意味です。' },
      { lv: 2, q: '受動態に書きかえよう。\nWe call this flower sakura.', a: 'This flower is called sakura.', exp: 'SVOC では O(this flower)を主語にし、C(sakura)は後ろにそのまま残します。一般の人が主語なので by us は省きます。' },
      { lv: 2, q: '受動態に書きかえよう。\nI saw her enter the building.', a: 'She was seen to enter the building.', exp: '知覚動詞 see の後ろの原形は、受動態にすると to 不定詞になります。was seen enter とはしません。' },
      { lv: 2, q: '( ) に入る最も適切なものを選ぼう。\nI would rather stay home ( ) go out in this rain.', choices: ['to', 'than', 'but', 'for'], a: 'B(than)', exp: 'would rather A than B で「B するよりむしろ A したい」。A・B どちらも原形です。訳:この雨の中を出かけるより、家にいたい。' },
      { lv: 2, q: '2文の意味のちがいを説明しよう。\n(1) You needn\'t have cooked dinner.\n(2) You didn\'t need to cook dinner.', a: '(1) 夕食を作る必要はなかったのに(実際には作った)。(2) 夕食を作る必要はなかった(作ったかどうかは不明、ふつうは作っていない)。', exp: 'needn\'t have + 過去分詞は、実際にしたことが不要だったという意味です。didn\'t need to は必要がなかったことだけを述べます。' },
      { lv: 2, q: '( ) に入る最も適切なものを選ぼう。\nThe bus is late. It ( ) have been caught in a traffic jam.', choices: ['must not', 'might', 'should not', 'had better'], a: 'B(might)', exp: 'バスが遅れている理由を「渋滞につかまったのかもしれない」と推量しています。might have + 過去分詞は確信の弱い過去への推量です。' },
      { lv: 2, q: '受動態に書きかえよう。\nYou must finish this report by Friday.', a: 'This report must be finished by Friday.', exp: '助動詞をふくむ受動態は、助動詞 + be + 過去分詞です。by Friday は「金曜日までに」で、動作主の by ではありません。' },
      { lv: 3, q: '( ) に入る最も適切なものを選ぼう。\nShe passed the exam easily. She ( ) studied very hard.', choices: ['can\'t have', 'needn\'t have', 'must have', 'should have'], a: 'C(must have)', exp: '簡単に合格したという結果から、とても熱心に勉強したにちがいない、と過去を強く推量しています。should have だと「勉強すべきだったのに」になります。' },
      { lv: 3, q: '誤りがあれば直そう(なければ「正しい」と答えよう)。\nHe can\'t have seen me yesterday, because I was in Osaka. He must have seen someone else.', a: '正しい', exp: '前半は「大阪にいたので、昨日私を見たはずがない」(can\'t have)、後半は「だれか別の人を見たにちがいない」(must have)で、根拠と推量の強さが合っています。' },
      { lv: 3, q: '和訳しよう。\nYou may as well go to bed now as stay up worrying about it.', a: 'そのことを心配して起きているくらいなら、もう寝たほうがいい。', exp: 'may as well A as B で「B するくらいなら A したほうがよい」。B をするのは意味がない、という気持ちをふくみます。' },
      { lv: 3, q: '受動態に書きかえよう。\nThey say that the castle was built in the 16th century.', a: 'The castle is said to have been built in the 16th century.(It is said that the castle was built … も可)', exp: 'say(現在)より築城(過去)が前なので、to have + 過去分詞を使います。受動の意味もあるので to have been built です。' },
      { lv: 3, q: '英訳しよう。\n「彼がそんなことを言ったはずがない。とても親切な人だから。」', a: 'He can\'t have said such a thing. He is a very kind person.', exp: '過去の発言を「はずがない」と強く否定するので can\'t have + 過去分詞です。親切な人だという根拠が、強い否定の推量を支えています。' }
    ]
  });

  add('e_inf', {
    pat: [
      { name: '目的語は to 不定詞か動名詞か', freq: 'とてもよく出る', when: 'want・decide・enjoy・finish・avoid などの動詞の直後が空所で、to do と doing の選択肢が並んでいるときです。', how: ['空所の前の動詞を見ます。', '「これから〜する(未来・希望・決心)」を表す動詞(want・hope・decide・plan・promise)は to 不定詞をとります。', '「現にしている・したこと・やめる・さける」を表す動詞(enjoy・finish・avoid・mind・give up)は動名詞をとります。'], ex: { q: '( ) 内の語を正しい形にしよう。\n(1) We decided ( leave ) early.\n(2) Would you mind ( open ) the window?', a: '(1) to leave (2) opening', exp: '(1) decide は「これからすることを決める」動詞なので to 不定詞。(2) mind は「〜するのをいやがる」で動名詞をとります。Would you mind 〜ing? は「〜していただけますか」です。' } },
      { name: 'to と ing で意味が変わる動詞', freq: 'とてもよく出る', when: 'remember・forget・stop・try・regret の後ろの形を選ぶ問題や、2文の意味のちがいを問う問題です。', how: ['文の内容が「これからすること」か「すでにしたこと」かを読み取ります。', 'remember / forget / regret は、to なら「これから〜すること」、ing なら「(過去に)〜したこと」です。', 'stop to do は「〜するために立ち止まる」、stop doing は「〜するのをやめる」、try to do は「〜しようとする」、try doing は「ためしに〜してみる」と区別します。'], ex: { q: '( ) 内の語を正しい形にしよう。\nDon\'t forget ( lock ) the door when you go out.', a: 'to lock', exp: '出かけるときに、これから鍵をかけることを忘れないで、という意味なので to 不定詞です。forget locking なら「鍵をかけたことを忘れる」になってしまいます。' } },
      { name: '名詞を修飾する分詞:現在分詞か過去分詞か', freq: 'とてもよく出る', when: '名詞の前後に空所があり、running / run、broken / breaking のような分詞の選択肢が並んでいるときです。', how: ['修飾される名詞を見つけます。', 'その名詞が「〜している」側(能動)なら現在分詞、「〜される・された」側(受動)なら過去分詞を選びます。', '分詞が1語なら名詞の前、ほかの語をともなうなら名詞の後ろに置くことも確認します。'], ex: { q: '( ) に入る語を選ぼう。\nLook at the ( fallen / falling ) leaves on the ground.', a: 'fallen', exp: '地面の上にある葉は、すでに「落ちてしまった」葉です。fall は自動詞なので、過去分詞 fallen は受動ではなく「〜してしまった(完了)」の意味になります。falling だと「落ちている最中の」です。' } },
      { name: '不定詞の意味上の主語 for / of', freq: 'よく出る', when: 'It is 形容詞 ( ) 人 to 〜 の空所に for か of を入れる問題です。', how: ['空所の前の形容詞を見ます。', 'kind・nice・careless・foolish など「人の性質・人柄」を表す形容詞なら of を使います。', 'easy・difficult・necessary・important など「行為の性質」を表す形容詞なら for を使います。迷ったら「人 is 形容詞」が言えるかで確かめます。'], ex: { q: '( ) に for か of を入れよう。\nIt was careless ( ) you to leave your bag on the train.', a: 'of', exp: 'careless(不注意な)は人の性質を表す形容詞で、You were careless. と言えるので of を使います。It is difficult for you 〜 のような行為の性質を表す形容詞なら for です。' } },
      { name: 'be to 不定詞を文脈で訳し分ける', freq: '難関大で出る', when: 'be 動詞の直後に to 不定詞があり、「予定・義務・可能・運命・意図」のどれかを文脈で判断する和訳問題です。', how: ['be to の後ろの内容と前後の文脈を確かめます。', '日時がある → 予定、命令・規則 → 義務、否定文で受動態 → 可能、過去の話で「〜することになった」 → 運命、if 節の中 → 意図と考えます。', 'それぞれ「〜することになっている」「〜すべきだ」「〜できる」「〜する運命だった」「〜するつもりなら」と訳します。'], ex: { q: '和訳しよう。\nNot a star was to be seen in the sky.', a: '空には星ひとつ見えなかった。', exp: '否定文で、to の後ろが受動態(to be seen)なので「可能」の be to です。「〜できる・〜されうる」と訳します。Not a star は「星ひとつも〜ない」という強い否定です。' } }
    ],
    more: [
      { lv: 1, q: '( ) 内の語を正しい形にしよう。\nI hope ( see ) you again soon.', a: 'to see', exp: 'hope は「これから〜することを望む」動詞なので、後ろは to 不定詞です。hope seeing とは言いません。' },
      { lv: 1, q: '( ) 内の語を正しい形にしよう。\nHe finished ( read ) the novel last night.', a: 'reading', exp: 'finish は「(している最中のことを)終える」動詞なので、後ろは動名詞です。finish to read とは言いません。' },
      { lv: 1, q: '下線部の不定詞の用法を答えよう。\nI have a lot of homework 【to do】 today.', a: '形容詞的用法(〜すべき・〜するための)', exp: 'to do は直前の名詞 homework を説明しています。「やるべき宿題」と訳せるので、名詞を修飾する形容詞的用法です。' },
      { lv: 1, q: '( ) に入る最も適切なものを選ぼう。\nThe boy ( ) under the tree is my brother.', choices: ['sleep', 'sleeps', 'sleeping', 'slept'], a: 'C(sleeping)', exp: '少年が「眠っている」側なので現在分詞です。sleeping under the tree が後ろから The boy を説明し、文の V は is です。' },
      { lv: 1, q: '( ) 内の語を正しい形にしよう。\nShe went to the store ( buy ) some milk.', a: 'to buy', exp: '「牛乳を買うために」店に行った、という目的を表す副詞的用法の不定詞です。in order to buy としても同じ意味になります。' },
      { lv: 1, q: '( ) に入る最も適切なものを選ぼう。\nThis is a picture ( ) by my sister.', choices: ['paint', 'painting', 'painted', 'to painting'], a: 'C(painted)', exp: '絵は姉によって「描かれた」側なので過去分詞です。by my sister という語句があるのも受動の目印です。' },
      { lv: 1, q: '( ) 内の語を正しい形にしよう。\nI enjoyed ( talk ) with my old friends.', a: 'talking', exp: 'enjoy は後ろに動名詞をとる動詞です。enjoy to talk とは言いません。' },
      { lv: 2, q: '2文の意味のちがいを説明しよう。\n(1) He stopped to smoke.\n(2) He stopped smoking.', a: '(1) 彼はたばこを吸うために立ち止まった(手を止めた)。(2) 彼はたばこを吸うのをやめた。', exp: 'stop to do の to 不定詞は stop の目的語ではなく「〜するために」の副詞的用法です。stop doing は「〜するのをやめる」です。' },
      { lv: 2, q: '( ) に for か of を入れよう。\nIt is necessary ( ) us to protect the environment.', a: 'for', exp: 'necessary は行為の性質を表す形容詞です。We are necessary とは言えないので for を使います。' },
      { lv: 2, q: '( ) 内の語を正しい形にしよう。\nI remember ( visit ) this park when I was a child.', a: 'visiting', exp: '子どものころ(過去)に訪れたことを覚えている、という意味なので動名詞です。remember to visit は「忘れずに訪れる」です。' },
      { lv: 2, q: '( ) に入る最も適切なものを選ぼう。\nI heard my name ( ) in the crowd.', choices: ['call', 'calling', 'called', 'to call'], a: 'C(called)', exp: 'my name は「呼ばれる」側なので過去分詞です。hear O C の C に過去分詞が来て、「O が〜されるのを聞く」の意味になります。' },
      { lv: 2, q: '不定詞の否定形にして、文を完成させよう。\n「遅れないように、早く出発した。」\nI left early ( ) be late.', a: 'so as not to(in order not to も可)', exp: '不定詞の否定は to の直前に not を置きます。目的の「〜しないように」は so as not to / in order not to で表すのが自然です。' },
      { lv: 2, q: '( ) に入る最も適切なものを選ぼう。\nShe is proud of ( ) a doctor.', choices: ['her father being', 'her father be', 'her father to be', 'her father is'], a: 'A(her father being)', exp: '前置詞 of の後ろは動名詞です。being の意味上の主語は her father で、「父親が医者であることを誇りに思う」の意味です。' },
      { lv: 2, q: '( ) 内の語を正しい形にしよう。\nI\'m looking forward to ( hear ) from you.', a: 'hearing', exp: 'look forward to の to は前置詞なので、後ろは動名詞です。不定詞の to とまちがえやすい代表例です。' },
      { lv: 2, q: '( ) に入る最も適切なものを選ぼう。\nThis book is too difficult for me ( ).', choices: ['to read it', 'to read', 'reading', 'read'], a: 'B(to read)', exp: 'too 〜 to do の文では、主語(This book)が read の目的語にあたるので、文末に it を置きません。so 〜 that の文なら it が必要です。' },
      { lv: 3, q: '和訳しよう。\nIf you are to succeed, you must work harder.', a: '成功するつもりなら、もっと努力しなければならない。', exp: 'if 節の中の be to は「意図(〜するつもりなら)」を表します。主節の must と合わせて、目標と条件の関係を訳します。' },
      { lv: 3, q: '誤りを直そう。\nShe seems to be sick last week.', a: 'to be → to have been', exp: 'seems(現在)より前の last week のことなので、完了不定詞 to have + 過去分詞にします。It seems that she was sick last week. と同じ意味です。' },
      { lv: 3, q: '( ) に入る最も適切なものを選ぼう。\nHe needs someone to talk ( ).', choices: ['to', 'them', 'it', 'for him'], a: 'A(to)', exp: 'talk to someone(だれかに話す)の someone が前に出た形なので、前置詞 to が後ろに残ります。「話し相手」の意味です。' },
      { lv: 3, q: '和訳しよう。\nThey were never to see each other again.', a: '彼らは二度と会うことはなかった(会えない運命だった)。', exp: '過去の話の中の be to は「運命」を表し、「〜することになった」と訳します。never と合わせて、その後二度と会えなかったことを表します。' },
      { lv: 3, q: '( ) 内の語を正しい形にしよう。\nI regret ( tell ) you that your application was not accepted.', a: 'to tell', exp: 'regret to do は「残念ながら〜する」で、これから伝えることへの遺憾を表します。regret telling は「話したことを後悔する」です。' }
    ]
  });

  add('e_h4', {
    pat: [
      { name: '関係副詞か関係代名詞か(後ろが完全か不完全か)', freq: 'とてもよく出る', when: '先行詞が place・house・day などで、空所に where / which、when / which のどちらを入れるかを問う問題です。', how: ['先行詞の意味(場所・時)だけで決めず、空所の後ろの文を見ます。', '後ろに S や O が欠けている(不完全な文)なら関係代名詞 which・that を選びます。', '後ろが S・V・O そろった完全な文なら関係副詞 where・when を選びます。'], ex: { q: '( ) に where か which を入れよう。\n(1) This is the town ( ) I visited last year.\n(2) This is the town ( ) I was born.', a: '(1) which (2) where', exp: '(1) は visited の O が欠けているので関係代名詞 which。(2) は I was born で文が完成しているので関係副詞 where です。どちらも先行詞は場所の town です。' } },
      { name: 'what か that / which か(先行詞の有無)', freq: 'とてもよく出る', when: '空所に what と that(which)が並んでいて、空所の前に名詞があるかどうかが手がかりになる問題です。', how: ['空所の直前に先行詞となる名詞があるかを確かめます。', '先行詞がなく、空所以下が文の S・O・C になっていれば what(〜すること・もの)を選びます。', '先行詞があれば that・which を選びます。what は先行詞をふくむので、名詞の後ろには置けません。'], ex: { q: '( ) に what か that を入れよう。\n( ) she said made everyone laugh.', a: 'What', exp: '空所の前に先行詞がなく、( ) she said が文の主語になっています。said の O も欠けているので、「彼女が言ったこと」を表す what が入ります。' } },
      { name: '非制限用法の which:前の文全体を指す', freq: 'よく出る', when: 'コンマの後ろに which があり、その前が名詞1つではなく、文の内容全体を受けている和訳・空所補充です。', how: ['コンマの後ろの which が何を指すかを、直前の名詞と前の文全体の両方で考えます。', 'which の後ろの動詞が単数(was・made)で、内容が前の出来事全体に合えば「そのこと」と訳します。', '非制限用法では that は使えないことも確認します。'], ex: { q: '和訳しよう。\nHe passed the difficult exam, which surprised his teachers.', a: '彼はその難しい試験に合格したが、そのことは先生たちを驚かせた。', exp: 'which は exam ではなく「彼が難しい試験に合格した」という前の文全体を指しています。試験が先生を驚かせたのではなく、合格したことが驚かせたのです。' } },
      { name: '複合関係詞:whoever・whatever・however', freq: 'よく出る', when: '文頭や文中に 〜ever があり、「〜する人はだれでも」と「だれが〜しても」のどちらかを判断するときです。', how: ['〜ever の節が文の S・O になっているか(名詞節)、文から取りのぞけるか(副詞節)を見ます。', '名詞節なら「〜する人はだれでも・〜するものは何でも」と訳します。', '副詞節なら「だれが(何を)〜しても」と譲歩で訳します。however は後ろに形容詞・副詞を置き「どんなに〜でも」です。'], ex: { q: '和訳しよう。\nHowever tired you are, you should brush your teeth before bed.', a: 'どんなに疲れていても、寝る前には歯をみがくべきだ。', exp: 'However + 形容詞 + S V で「どんなに〜でも」という譲歩の副詞節です。No matter how tired you are と書きかえられます。' } },
      { name: '前置詞 + 関係代名詞・数量語 + of whom / which', freq: '難関大で出る', when: '空所の前に前置詞や some of・most of・all of があり、関係詞を選ぶ問題です。', how: ['前置詞の後ろには that は置けず、人なら whom、物なら which を使います。', '数量語 + of の後ろも同じく whom・which です(them・it では文がつながりません)。', '関係詞節を2文に戻して、前置詞がどの動詞・名詞とつながっているかを確かめます。'], ex: { q: '( ) に入る語を選ぼう。\nShe has three brothers, all of ( ) live in Tokyo.\n① them ② who ③ whom ④ that', a: '③(whom)', exp: '前置詞 of の後ろなので目的格 whom です。them にすると、コンマで2つの文をつなぐことになり、接続詞がないため誤りです。訳:彼女には兄弟が3人いて、全員が東京に住んでいる。' } }
    ],
    more: [
      { lv: 1, q: '( ) に入る最も適切なものを選ぼう。\nThis is the house ( ) my grandfather lives.', choices: ['which', 'where', 'what', 'who'], a: 'B(where)', exp: 'my grandfather lives で文が完成しているので、関係副詞 where を選びます。which にするなら in which や lives in が必要です。' },
      { lv: 1, q: '( ) に入る最も適切なものを選ぼう。\nI\'ll never forget the day ( ) we first met.', choices: ['when', 'which', 'where', 'what'], a: 'A(when)', exp: '先行詞 the day は時を表し、we first met で文が完成しているので関係副詞 when です。' },
      { lv: 1, q: '( ) に what か that を入れよう。\nThis is ( ) I wanted.', a: 'what', exp: '空所の前に先行詞がなく、( ) I wanted が is の補語になっています。「私がほしかったもの」の what です。' },
      { lv: 1, q: '和訳しよう。\nThat is why I was late for school.', a: 'そういうわけで、私は学校に遅刻した。', exp: 'That is why 〜 は「そういうわけで〜」。why は関係副詞で、the reason が省略された形です。' },
      { lv: 1, q: '( ) に入る最も適切なものを選ぼう。\nI have a friend, ( ) lives in Canada.', choices: ['that', 'who', 'which', 'whom'], a: 'B(who)', exp: 'コンマのある非制限用法なので that は使えません。先行詞は人で、空所は lives の主語なので主格 who です。' },
      { lv: 1, q: '和訳しよう。\nWhoever comes first will get a prize.', a: '最初に来た人はだれでも賞品をもらえる。', exp: 'Whoever comes first は文の主語になる名詞節で、「〜する人はだれでも」と訳します。Anyone who comes first と同じ意味です。' },
      { lv: 1, q: '和訳として最も適切なものを選ぼう。\nThis is how I solved the problem.', choices: ['これが私が問題を解いた方法だ。', 'これがなぜ私が問題を解いたかだ。', 'これは私がどんな問題を解いたかだ。', 'これは私が問題を解いた場所だ。'], a: 'A(これが私が問題を解いた方法だ。)', exp: '関係副詞 how は「〜する方法」を表します。the way how とは言わず、the way か how のどちらか一方を使います。' },
      { lv: 2, q: '( ) に入る最も適切なものを選ぼう。\nKyoto is a city ( ) many tourists visit every year.', choices: ['where', 'when', 'which', 'in which'], a: 'C(which)', exp: 'visit の O が欠けた不完全な文なので関係代名詞 which です。先行詞が場所の city でも、where は使えません。' },
      { lv: 2, q: '2文を関係詞を使って1文にしよう。\nThis is the room. My sister studies in it.', a: 'This is the room where my sister studies.(This is the room in which my sister studies. も可)', exp: 'in it を関係副詞 where 1語にまとめるか、前置詞を前に出して in which にします。in that とは言えません。' },
      { lv: 2, q: '( ) に入る最も適切なものを選ぼう。\nHe said nothing, ( ) made her angry.', choices: ['that', 'what', 'which', 'who'], a: 'C(which)', exp: 'コンマの後ろで「何も言わなかったこと」という前の文全体を受けるのは非制限用法の which です。that・what は使えません。' },
      { lv: 2, q: '( ) に入る最も適切なものを選ぼう。\n( ) you do, don\'t give up.', choices: ['Whatever', 'However', 'Whoever', 'Whenever'], a: 'A(Whatever)', exp: 'do の O が欠けているので、物を表す Whatever(何をしても)が入ります。However なら後ろに形容詞・副詞が必要です。' },
      { lv: 2, q: '( ) に入る最も適切なものを選ぼう。\nThis is the reason ( ) he gave for his absence.', choices: ['why', 'which', 'where', 'how'], a: 'B(which)', exp: 'gave の O が欠けているので関係代名詞 which です。先行詞が reason でも、後ろが不完全なら why は使えません。' },
      { lv: 2, q: '和訳しよう。\nWhat is important is not what you have but what you do.', a: '大切なのは、何を持っているかではなく、何をするかだ。', exp: 'What is important が主語、not A but B が補語です。3つの what はどれも「〜こと・もの」を表す名詞節を作ります。' },
      { lv: 2, q: '( ) に入る最も適切なものを選ぼう。\nThe man ( ) car was stolen called the police.', choices: ['who', 'whose', 'whom', 'which'], a: 'B(whose)', exp: '空所の後ろに car という名詞があり、「その男性の車」という所有の関係なので whose を使います。' },
      { lv: 2, q: '英訳しよう。\n「ここが私たちが初めて会った公園だ。」', a: 'This is the park where we first met.', exp: 'we first met で文が完成しているので、関係副詞 where を使います。the park which we first met は誤りです(at which なら可)。' },
      { lv: 3, q: '( ) に入る最も適切なものを選ぼう。\nI bought ten eggs, two of ( ) were broken.', choices: ['them', 'which', 'that', 'what'], a: 'B(which)', exp: 'two of + 関係代名詞 で前の名詞を受けます。them にすると、接続詞なしで2つの文をつなぐことになり誤りです。' },
      { lv: 3, q: '( ) に入る最も適切なものを選ぼう。\nThe pen ( ) I wrote the letter was a gift from my aunt.', choices: ['which', 'with which', 'where', 'by that'], a: 'B(with which)', exp: 'wrote the letter with the pen(そのペンで書いた)の with を前に出した形です。後ろの I wrote the letter は完全な文なので which だけでは不可です。' },
      { lv: 3, q: '誤りを直そう。\nThe village which I grew up has changed a lot.', a: 'which → where(in which、または grew up in も可)', exp: 'grew up は自動詞で O をとらないので、後ろは完全な文です。関係副詞 where にするか、前置詞 in を補います。' },
      { lv: 3, q: '和訳しよう。\nShe is no longer the shy girl that she was ten years ago.', a: '彼女はもう10年前の内気な少女ではない。', exp: 'that she was 〜 の that は補語(C)の働きをする関係代名詞で、「10年前の彼女(のような)」という意味になります。性格や様子を表すときは who より that がよく使われます。' },
      { lv: 3, q: '( ) に入る最も適切なものを選ぼう。\nI\'ll give this book to ( ) wants it.', choices: ['whomever', 'whoever', 'who', 'whom'], a: 'B(whoever)', exp: '前置詞 to の後ろでも、関係詞節の中で wants の主語なので主格の whoever を使います。格は節の中の働きで決まります。' }
    ]
  });

  add('e_h3', {
    pat: [
      { name: '分詞構文の意味を文脈で決める', freq: 'とてもよく出る', when: '文頭や文末に 〜ing・過去分詞のかたまりがあり、コンマで主節とつながっている和訳・書きかえ問題です。', how: ['分詞のかたまりと主節の内容を別々に読みます。', '2つの関係が「時(〜とき)・理由(〜ので)・条件(〜なら)・譲歩(〜だが)・付帯状況(〜しながら)」のどれかを考えます。', '迷ったら「〜して、…」と軽くつなぎ、意味の通る接続詞を選んで書きかえて確かめます。'], ex: { q: '接続詞を使って書きかえよう。\nFeeling sick, she stayed home all day.', a: 'Because(As) she felt sick, she stayed home all day.', exp: '気分が悪いことと、1日中家にいたことは「原因と結果」の関係です。理由を表す because・as で書きかえます。主語が同じなので分詞構文にできます。' } },
      { name: '受動の分詞構文(Seen from 〜)', freq: 'よく出る', when: '文頭の分詞が過去分詞で、主節の主語が「〜される」側になっているときです。being が省略されていることに注意します。', how: ['主節の主語を確かめます。', '主語が分詞の動作を「する」側なら現在分詞、「される」側なら過去分詞を選びます。', '過去分詞で始まる分詞構文は、前に being が省略されていると考えて訳します。'], ex: { q: '( ) に入る語を選ぼう。\n( Seeing / Seen ) from the top of the hill, the town looks beautiful.', a: 'Seen', exp: '主節の主語 the town は、丘の上から「見られる」側です。(Being) Seen from 〜 で「〜から見ると」の意味になります。Seeing にすると町が何かを見ていることになります。' } },
      { name: '完了の分詞構文 Having + 過去分詞', freq: 'よく出る', when: '分詞のかたまりの内容が、主節より前に起きたこと(時間のずれ)をはっきり示したいときです。', how: ['分詞のかたまりと主節の出来事の順番を確かめます。', '分詞の内容が主節より前なら Having + 過去分詞にします。', '否定の場合は Not having + 過去分詞のように、not を分詞の前に置きます。'], ex: { q: '分詞構文に書きかえよう。\nAs I had read the book before, I knew the ending.', a: 'Having read the book before, I knew the ending.', exp: '本を読んだのは結末を知っていた時点より前なので、完了の分詞構文 Having + 過去分詞を使います。主語が同じなので I を消します。' } },
      { name: '独立分詞構文と慣用表現', freq: 'よく出る', when: '分詞の前に主節と別の主語(the weather・There など)がある文や、Generally speaking・Judging from のような決まった表現です。', how: ['分詞の意味上の主語が、主節の主語と同じかどうかを確かめます。', 'ちがうなら、分詞の前にその主語を残します(独立分詞構文)。', 'Generally speaking(一般的に言えば)、Judging from 〜(〜から判断すると)、Considering 〜(〜を考えると)は主語がなくても使える慣用表現として覚えます。'], ex: { q: '分詞構文に書きかえよう。\nIf the weather permits, we will have a barbecue.', a: 'Weather permitting, we will have a barbecue.', exp: 'if 節の主語 the weather は主節の we とちがうので、分詞の前に残す独立分詞構文にします。Weather permitting は「天気がよければ」という決まった言い方で、the はよく省かれます。' } },
      { name: '付帯状況の with O C', freq: 'とてもよく出る', when: 'with の後ろに名詞があり、さらに分詞・形容詞・前置詞句が続く「〜して・〜したまま」の文です。', how: ['with の後ろの名詞(O)と、その後ろの語(C)の関係を見ます。', 'O が「〜している」側なら現在分詞、「〜される」側なら過去分詞にします。', '「O が C の状態で」と訳します。with his eyes closed(目を閉じて)、with the TV on(テレビをつけたまま)などがよく出ます。'], ex: { q: '( ) に入る語を選ぼう。\nShe listened to the music with her eyes ( closing / closed ).', a: 'closed', exp: '目は「閉じられた」状態なので過去分詞 closed です。with O C で「O が C の状態で」。訳:彼女は目を閉じて音楽を聞いた。' } }
    ],
    more: [
      { lv: 1, q: '分詞構文に書きかえよう。\nWhen I walked along the street, I met an old friend.', a: 'Walking along the street, I met an old friend.', exp: '接続詞 When と、主節と同じ主語 I を消し、動詞を ing 形にします。時を表す分詞構文です。' },
      { lv: 1, q: '和訳しよう。\nHaving no money, I couldn\'t buy the ticket.', a: 'お金がなかったので、私はそのチケットを買えなかった。', exp: 'お金がないことと、チケットを買えなかったことは原因と結果の関係なので、理由で訳します。' },
      { lv: 1, q: '( ) に入る最も適切なものを選ぼう。\n( ) in easy English, this book is good for beginners.', choices: ['Writing', 'Written', 'To write', 'Wrote'], a: 'B(Written)', exp: '主語の this book は易しい英語で「書かれている」側なので、過去分詞の分詞構文です。being が省略されています。' },
      { lv: 1, q: '和訳しよう。\nHe sat on the bench, reading a newspaper.', a: '彼は新聞を読みながらベンチに座っていた。', exp: '文末の reading 〜 は付帯状況の分詞構文で、「〜しながら」と訳します。座ることと読むことが同時に起きています。' },
      { lv: 1, q: '( ) に入る最も適切なものを選ぼう。\nHe was standing with his arms ( ).', choices: ['fold', 'folding', 'folded', 'to fold'], a: 'C(folded)', exp: '腕は「組まれた」状態なので過去分詞です。with O C で「腕を組んで」立っていた、という意味になります。' },
      { lv: 1, q: '和訳しよう。\nGenerally speaking, Japanese people are punctual.', a: '一般的に言えば、日本人は時間に正確だ。', exp: 'Generally speaking は「一般的に言えば」という慣用的な分詞構文で、主節と主語がちがっても使えます。' },
      { lv: 1, q: '分詞構文に書きかえよう。\nBecause he was tired, he went to bed early.', a: '(Being) tired, he went to bed early.', exp: '理由の接続詞と主語を消し、was を Being にします。Being は省略されることが多く、Tired, he went 〜 となります。' },
      { lv: 2, q: '( ) に入る最も適切なものを選ぼう。\n( ) what to say, she kept silent.', choices: ['Not knowing', 'Knowing not', 'Not known', 'Don\'t knowing'], a: 'A(Not knowing)', exp: '分詞構文の否定は、分詞の直前に not を置きます。訳:何と言えばいいか分からなかったので、彼女は黙っていた。' },
      { lv: 2, q: '分詞構文に書きかえよう。\nAfter she had finished her work, she went home.', a: 'Having finished her work, she went home.', exp: '仕事を終えたのは帰宅より前なので、完了の分詞構文 Having + 過去分詞にします。' },
      { lv: 2, q: '誤りを直そう。\nWalking down the street, a strange noise was heard.', a: 'Walking down the street, I heard a strange noise.(などのように、主語を歩く人にする)', exp: '分詞構文の意味上の主語は主節の主語と同じです。このままだと「音」が歩いていることになるので、主節の主語を歩く人にします。' },
      { lv: 2, q: '分詞構文に書きかえよう。\nAs it was rainy, the game was canceled.', a: 'It being rainy, the game was canceled.', exp: '天候の it は主節の the game とちがう主語なので、分詞の前に残す独立分詞構文にします。' },
      { lv: 2, q: '( ) に入る最も適切なものを選ぼう。\n( ) from his accent, he must be from Osaka.', choices: ['Judge', 'Judging', 'Judged', 'To judging'], a: 'B(Judging)', exp: 'Judging from 〜 は「〜から判断すると」という慣用表現です。主節の主語とずれていても使えます。' },
      { lv: 2, q: '和訳しよう。\nDon\'t speak with your mouth full.', a: '口に食べ物を入れたまま話してはいけない。', exp: 'with O C の C には形容詞も来ます。your mouth = full(口がいっぱいの状態)で、「口をいっぱいにしたまま」の意味です。' },
      { lv: 2, q: '和訳しよう。\nTurning to the left, you will find the post office.', a: '左に曲がると、郵便局が見つかります。', exp: '主節が未来の内容で、分詞のかたまりが条件になっています。If you turn to the left と書きかえられます。' },
      { lv: 2, q: '( ) に入る最も適切なものを選ぼう。\nThere ( ) no bus service, we had to walk.', choices: ['is', 'was', 'being', 'been'], a: 'C(being)', exp: 'As there was no bus service を分詞構文にすると、There を残して There being 〜 となります。訳:バスが運行していなかったので、歩かなければならなかった。' },
      { lv: 3, q: '分詞構文に書きかえよう。\nAs I had never seen snow before, I was very excited.', a: 'Never having seen snow before, I was very excited.(Not having seen … も可)', exp: '興奮したより前の経験なので完了の分詞構文、否定は分詞の前に never・not を置きます。' },
      { lv: 3, q: '和訳しよう。\nAll things considered, the plan was a success.', a: 'すべてを考えあわせると、その計画は成功だった。', exp: 'all things が「考えられる」側なので過去分詞 considered の独立分詞構文です。慣用的に「すべてを考慮すると」と訳します。' },
      { lv: 3, q: '( ) に入る最も適切なものを選ぼう。\n( ) in a hurry, the letter has many mistakes.', choices: ['Writing', 'Having written', 'Written', 'To write'], a: 'C(Written)', exp: '主語の the letter は急いで「書かれた」側なので過去分詞です。手紙が書いたわけではないので Writing・Having written は不可です。' },
      { lv: 3, q: '誤りを直そう。\nHaving been invited to the party, I didn\'t go because I was sick.', a: '誤りはない(正しい)', exp: '招待されたのは行かなかったことより前なので、完了の受動形 Having been invited で正しい形です。訳:パーティーに招待されていたが、具合が悪くて行かなかった。' },
      { lv: 3, q: '英訳しよう。分詞構文を使うこと。\n「仕事が終わったので、彼らは家に帰った。」', a: 'The work (having been) finished, they went home.', exp: '仕事(the work)は主節の they とちがう主語なので、独立分詞構文にします。仕事は「終えられた」側なので過去分詞で、having been は省略できます。' }
    ]
  });

  add('e_comp', {
    pat: [
      { name: '倍数表現:X times as 〜 as / X times the 名詞 of', freq: 'とてもよく出る', when: '「〜の2倍・3倍・半分」という日本語の英訳や、twice・three times・half の位置を問う並べかえ問題です。', how: ['倍数の語(twice・three times・half)を見つけます。', '倍数の語は as 〜 as の前に置きます(three times as large as)。', 'size・number・length などの名詞を使うときは、X times the size of 〜 の形にします。'], ex: { q: '並べかえよう。\n「この公園はあの公園の3倍の広さだ。」\nThis park is (as / three / large / times / as) that one.', a: 'This park is three times as large as that one.', exp: '倍数の three times は as 〜 as の前に置きます。three times the size of that one とも言えます。2倍は twice、半分は half を同じ位置に置きます。' } },
      { name: 'the 比較級, the 比較級', freq: 'とてもよく出る', when: '「〜すればするほど、ますます…」という日本語や、The more 〜, the … の形の並べかえ・語形変化の問題です。', how: ['もとの2つの文(You practice much. / You become good.)を考えます。', 'それぞれの比較級(more・better)に the をつけて節の先頭に出します。', 'much と名詞・形容詞がいっしょに動くか(the more books)を確認し、残りの S V をふつうの語順で続けます。'], ex: { q: '英訳しよう。\n「練習すればするほど、上手になる。」', a: 'The more you practice, the better you become.', exp: 'You practice much. と You become good. の比較級 more・better に the をつけて前に出します。the more you practice の後ろはふつうの語順です。' } },
      { name: '最上級の意味を原級・比較級で表す', freq: 'とてもよく出る', when: '最上級の文の書きかえ問題で、No other 〜・any other 〜・nothing is as 〜 as などが出てくるときです。', how: ['もとの最上級の文で、何が「一番」かを確かめます。', 'No other + 単数名詞 + as 〜 as / 比較級 than の形と、比較級 + than any other + 単数名詞 の形を使い分けます。', 'any other の後ろは単数名詞、「時間・ものごと」なら Nothing is more 〜 than … も使えることを確認します。'], ex: { q: '比較級を使って同じ意味にしよう。\nMt. Fuji is the highest mountain in Japan.', a: 'Mt. Fuji is higher than any other mountain in Japan.(No other mountain in Japan is higher than Mt. Fuji. も可)', exp: '比較級 than any other のあとは単数名詞 mountain です。other を落とすと富士山自身もふくまれてしまい、論理的におかしくなります。' } },
      { name: 'no more than / no less than / not more than', freq: 'よく出る', when: 'no more than・no less than・not more than・not less than の和訳や、only・as many as・at most・at least への言いかえを問う問題です。', how: ['no は「差がゼロ」で、気持ち(多い・少ない)をふくむと考えます。no more than = only(〜しか)、no less than = as many(much) as(〜も)です。', 'not は単に「〜を超えない・下回らない」で、not more than = at most(多くても)、not less than = at least(少なくとも)です。', '数字の前のどの表現かを見て、気持ちをふくむかどうかで訳し分けます。'], ex: { q: '和訳しよう。\nHe paid no less than 50,000 yen for the shoes.', a: '彼はそのくつに5万円も払った。', exp: 'no less than 〜 は as much as 〜 と同じで、「〜も」と金額の多さへの驚きをふくみます。not less than なら「少なくとも5万円」です。' } },
      { name: '比べるものをそろえる that of / those of', freq: 'よく出る', when: '比較の文で than の後ろに that・those を入れる空所補充や、比べるものがずれている文の正誤問題です。', how: ['than の前で、何と何を比べているか(人口と人口、気候と気候)を確かめます。', 'than の後ろも同じ種類のものにするため、くり返しの名詞を that(単数)・those(複数)で置きかえます。', '単数か複数かを、前の名詞に合わせて選びます。'], ex: { q: '( ) に that か those を入れよう。\nThe climate of Tokyo is milder than ( ) of Sapporo.', a: 'that', exp: '比べているのは「東京の気候」と「札幌の気候」です。くり返しの the climate(単数)を that で受けます。Sapporo とだけ書くと気候と町を比べることになってしまいます。' } }
    ],
    more: [
      { lv: 1, q: '( ) に入る最も適切なものを選ぼう。\nMy room is ( ) as large as yours.', choices: ['two', 'twice', 'two times than', 'double than'], a: 'B(twice)', exp: '「2倍」は twice を as 〜 as の前に置きます。3倍以上は three times のように times を使います。' },
      { lv: 1, q: '( ) 内の語を正しい形にしよう。\nThe ( hard ) you work, the more you will learn.', a: 'harder', exp: 'the 比較級, the 比較級 の形なので、hard を比較級 harder にします。「一生けんめい働けば働くほど、多くを学ぶ」の意味です。' },
      { lv: 1, q: '( ) に入る最も適切なものを選ぼう。\nThis bag is ( ) more expensive than that one.', choices: ['very', 'much', 'many', 'so'], a: 'B(much)', exp: '比較級を強めるのは much・far・even・a lot などです。very は比較級を強められません。' },
      { lv: 1, q: '同じ意味にしよう。\nTom is the tallest boy in his class.\nTom is taller than ( ) ( ) ( ) in his class.', a: 'any other boy', exp: '比較級 + than any other + 単数名詞 で最上級の意味を表します。boys と複数にしないことに注意します。' },
      { lv: 1, q: '和訳しよう。\nI have no more than 100 yen.', a: '私は100円しか持っていない。', exp: 'no more than 〜 は only と同じで、「〜しか」と少なさを強調します。' },
      { lv: 1, q: '( ) に入る最も適切なものを選ぼう。\nThis river is half ( ) long as that one.', choices: ['so', 'as', 'than', 'more'], a: 'B(as)', exp: '「半分の長さ」は half as long as 〜 です。倍数表現の half も as 〜 as の前に置きます。' },
      { lv: 1, q: '英訳しよう。\n「早ければ早いほどいい。」', a: 'The sooner, the better.', exp: 'the 比較級, the 比較級 の、主語と動詞を省いた決まった言い方です。The earlier, the better. とも言います。' },
      { lv: 2, q: '( ) に that か those を入れよう。\nThe ears of a rabbit are longer than ( ) of a cat.', a: 'those', exp: '比べているのは「ウサギの耳」と「ネコの耳」です。くり返しの the ears は複数なので those で受けます。' },
      { lv: 2, q: '同じ意味にしよう。\nNothing is as precious as time.\nTime is the ( ) ( ) of all.', a: 'most precious', exp: 'Nothing is as 〜 as A は「A ほど〜なものはない」で、A が最上級であることを表します。Time is the most precious thing of all. とも言えます。' },
      { lv: 2, q: '( ) に入る最も適切なものを選ぼう。\nThere were ( ) than ten people at the meeting, so we needed a bigger room.', choices: ['no more', 'not more', 'no less', 'at most'], a: 'C(no less)', exp: 'より大きな部屋が必要になったので、人数が「10人も」いたという多さを表す no less than が合います。no more than だと「10人しか」です。' },
      { lv: 2, q: '並べかえよう。\n「彼は兄の2倍の数の本を持っている。」\nHe has (as / twice / books / many / as) his brother.', a: 'He has twice as many books as his brother.', exp: '数の多さを比べるので as many books as になり、倍数 twice をその前に置きます。many と books を離さないことがポイントです。' },
      { lv: 2, q: '和訳しよう。\nHe is no longer a child.', a: '彼はもう子どもではない。', exp: 'no longer 〜 は「もはや〜ない」。not 〜 any longer と同じ意味です。' },
      { lv: 2, q: '( ) に入る最も適切なものを選ぼう。\nShe is the ( ) of the two sisters.', choices: ['taller', 'tallest', 'more tall', 'most tall'], a: 'A(taller)', exp: '2人のうちで比べるときは the + 比較級 + of the two を使います。2人なので最上級にはしません。' },
      { lv: 2, q: '( ) に入る最も適切なものを選ぼう。\nThe population of India is larger than ( ) of Japan.', choices: ['it', 'this', 'that', 'those'], a: 'C(that)', exp: '「インドの人口」と「日本の人口」を比べています。単数の the population をくり返す代わりに that を使います。' },
      { lv: 2, q: '誤りを直そう。\nShe is more kinder than her sister.', a: 'more kinder → kinder', exp: 'kind の比較級は kinder で、more をつけると比較級が二重になります。強めるなら much kinder にします。' },
      { lv: 3, q: '和訳しよう。\nA whale is no more a fish than a horse is.', a: 'クジラが魚でないのは、馬が魚でないのと同じだ。', exp: 'A is no more B than C is D は「A が B でないのは C が D でないのと同じ」。than の後ろにも否定の意味が入るので、両方を否定で訳します。' },
      { lv: 3, q: '( ) に入る最も適切なものを選ぼう。\nI like him all the ( ) for his faults.', choices: ['more', 'most', 'much', 'less'], a: 'A(more)', exp: 'all the 比較級 for 〜 で「〜のためにかえっていっそう…」。訳:彼に欠点があるからこそ、なおさら彼が好きだ。' },
      { lv: 3, q: '和訳しよう。\nThe higher we climbed, the colder it became.', a: '高く登れば登るほど、ますます寒くなった。', exp: 'the 比較級, the 比較級 は過去形の文でも使えます。we climbed high と it became cold の比較級を前に出した形です。' },
      { lv: 3, q: '誤りを直そう。\nThis computer is superior than that one.', a: 'than → to', exp: 'superior・inferior・senior・junior など -or で終わるラテン語由来の形容詞は、比べる相手を than ではなく to で表します。' },
      { lv: 3, q: '( ) に入る最も適切なものを選ぼう。\nHe is none the ( ) for his failure.', choices: ['worse', 'worst', 'bad', 'badly'], a: 'A(worse)', exp: 'none the 比較級 for 〜 は「〜だからといって少しも…ない」。訳:彼は失敗したからといって少しも落ちこんでいない(状態が悪くなっていない)。' }
    ]
  });

  add('e_h2', {
    pat: [
      { name: '仮定法か直説法か(現実の可能性で選ぶ)', freq: 'とてもよく出る', when: 'if 節の動詞の形(現在形・過去形・had + 過去分詞)と主節の would の有無が問われる空所補充です。', how: ['文の内容が「ありうる話」か「現実とちがう想像」かを読み取ります。', 'ありうる話なら直説法(if + 現在形, will)、今の事実に反するなら仮定法過去(if + 過去形, would + 原形)です。', '過去の事実に反するなら仮定法過去完了(if + had + 過去分詞, would have + 過去分詞)にします。'], ex: { q: '( ) 内の語を正しい形にしよう。\nI\'m not a bird. If I ( be ) a bird, I would fly to you.', a: 'were', exp: '鳥であることは今の事実に反するので仮定法過去です。be 動詞は主語にかかわらず were がふつうです(口語では was も使われます)。' } },
      { name: '混合型:過去の仮定と今の結果', freq: 'よく出る', when: 'if 節に過去の時(last night・then)があり、主節に now・today がある文です。', how: ['if 節と主節の「時」を別々に確かめます。', 'if 節が過去の事実に反するなら had + 過去分詞にします。', '主節が今の事実に反する結果なら would + 原形にします(would have にしない)。'], ex: { q: '( ) 内の語を正しい形にしよう。\nIf I had taken the medicine last night, I ( feel ) better now.', a: 'would feel', exp: 'if 節は昨夜(過去)の事実に反するので had taken、主節は now があり今の結果なので would + 原形 feel です。過去の仮定と今の結果を組み合わせた混合型です。' } },
      { name: 'if のない仮定法(Without・But for・otherwise・主語)', freq: 'とてもよく出る', when: 'if がないのに主節に would・could があり、仮定の意味をふくむ文を見ぬく問題です。', how: ['主節に would・could・might + 原形(または have + 過去分詞)があるかを見ます。', 'Without 〜・But for 〜・With 〜・otherwise・to 不定詞・主語などが、if 節の代わりになっていないか探します。', 'それを if 節に戻して時制を決めます(Without = If it were not for / If it had not been for)。'], ex: { q: 'if を使って書きかえよう。\nWithout your help, I couldn\'t have finished the work.', a: 'If it had not been for your help, I couldn\'t have finished the work.', exp: '主節が couldn\'t have finished(過去の事実に反する)なので、Without は仮定法過去完了の If it had not been for 〜 に戻します。If you had not helped me としてもかまいません。' } },
      { name: 'if の省略と倒置(Were・Had・Should)', freq: 'よく出る', when: '文頭が Were I・Had he・Should you で始まり、疑問文ではない文です。', how: ['文頭の Were・Had・Should の後ろに主語があり、文末に ? がないかを確かめます。', 'if を補って語順をもとに戻します(Had I known → If I had known)。', 'should は「万一〜なら」、were to は「仮に〜なら」の意味をふくむことを確認して訳します。'], ex: { q: 'if を使って書きかえよう。\nHad I known the truth, I would have told you.', a: 'If I had known the truth, I would have told you.', exp: '文頭の Had I known は if が省略されて倒置した形です。if を補うと仮定法過去完了で、「本当のことを知っていたら、あなたに話していただろう」の意味です。' } },
      { name: 'I wish・as if・It is time の時制', freq: 'とてもよく出る', when: 'I wish・as if(as though)・It is (high) time の後ろの動詞の形を問う問題です。', how: ['願いや想像の内容が「今」か「過去」かを確かめます。', '今のことなら過去形、過去のことなら had + 過去分詞にします。', 'It is time の後ろは「もう〜してもよいころだ(まだしていない)」なので過去形にします。'], ex: { q: '( ) 内の語を正しい形にしよう。\nIt\'s time you ( go ) to bed.', a: 'went', exp: 'It is time S + 過去形 で「もう〜してもよいころだ」。まだ寝ていないという現実とのずれを過去形で表します。It\'s time for you to go to bed. とも言えます。' } }
    ],
    more: [
      { lv: 1, q: '( ) 内の語を正しい形にしよう。\nIf I ( have ) more time, I would read more books.', a: 'had', exp: '今は時間がないという事実に反する想像なので、仮定法過去です。if 節は過去形、主節は would + 原形にします。' },
      { lv: 1, q: '( ) に入る最も適切なものを選ぼう。\nIf it had not rained, we ( ) the game.', choices: ['will play', 'would play', 'would have played', 'had played'], a: 'C(would have played)', exp: 'if 節が had + 過去分詞なので、過去の事実に反する仮定法過去完了です。主節は would have + 過去分詞にします。' },
      { lv: 1, q: '和訳しよう。\nI wish I could speak French.', a: 'フランス語が話せたらいいのに。', exp: 'I wish + 過去形(could)は、今の事実に反する願望です。実際には今フランス語を話せません。' },
      { lv: 1, q: '( ) 内の語を正しい形にしよう。\nHe talks as if he ( know ) everything.', a: 'knew', exp: 'as if の後ろの内容は事実ではなく、話している時と同じ「今」のことなので仮定法過去 knew にします。' },
      { lv: 1, q: '( ) に入る最も適切なものを選ぼう。\nIf I ( ) you, I would accept the offer.', choices: ['am', 'were', 'had been', 'will be'], a: 'B(were)', exp: '「私があなたなら」は今の事実に反する想像なので仮定法過去で、be 動詞は were を使います。' },
      { lv: 1, q: '和訳しよう。\nIf I had studied harder, I would have passed the exam.', a: 'もっと一生けんめい勉強していたら、試験に合格していただろう。', exp: '仮定法過去完了で、実際には勉強が足りず、合格しなかったという過去の事実が裏にあります。' },
      { lv: 1, q: '( ) 内の語を正しい形にしよう。\nI wish I ( be ) taller.', a: 'were', exp: 'I wish の後ろの今の願望は仮定法過去にします。be 動詞はふつう were を使います。' },
      { lv: 2, q: '( ) 内の語を正しい形にしよう。\nI wish I ( buy ) that jacket when it was on sale.', a: 'had bought', exp: 'セールのとき(過去)に買わなかったことを悔やんでいるので、過去の事実に反する願望の I wish + had + 過去分詞にします。' },
      { lv: 2, q: 'If を使って書きかえよう。\nBut for the internet, our lives would be very different.', a: 'If it were not for the internet, our lives would be very different.', exp: '主節が would + 原形(今の想像)なので、But for は仮定法過去の If it were not for 〜 に戻します。' },
      { lv: 2, q: '( ) に入る最も適切なものを選ぼう。\n( ) I rich, I would travel around the world.', choices: ['Was', 'Were', 'Had', 'Should'], a: 'B(Were)', exp: 'If I were rich の if を省略して倒置した形です。仮定法過去なので Were を文頭に出します。' },
      { lv: 2, q: '和訳しよう。\nI took a taxi; otherwise I would have missed the train.', a: '私はタクシーに乗った。そうしなかったら、電車に乗りおくれていただろう。', exp: 'otherwise は「もしそうでなかったら」で、if I had not taken a taxi の代わりになっています。主節は仮定法過去完了です。' },
      { lv: 2, q: '( ) 内の語を正しい形にしよう。\nIf she had left home earlier, she ( be ) here now.', a: 'would be', exp: 'if 節は過去の事実に反し、主節は now の今の結果なので混合型です。主節は would + 原形にします。' },
      { lv: 2, q: '( ) に入る最も適切なものを選ぼう。\nShould you have any questions, please ( ) me.', choices: ['contact', 'contacted', 'would contact', 'had contacted'], a: 'A(contact)', exp: 'Should you 〜 は If you should 〜(万一〜なら)の倒置です。主節は命令文なので原形 contact を使います。' },
      { lv: 2, q: '( ) 内の語を正しい形にしよう。\nShe looked as if she ( see ) a ghost.', a: 'had seen', exp: '幽霊を見たのは、そう見えた時点より前のことなので as if + had + 過去分詞にします。as if 節の時制は主節の時を基準にします。' },
      { lv: 2, q: '英訳しよう。\n「もし今100万円あったら、何をしますか。」', a: 'What would you do if you had one million yen now?', exp: '今の事実に反する想像なので仮定法過去です。疑問文では What would you do を先に置き、if 節を後ろに続けます。' },
      { lv: 3, q: '和訳しよう。\nA true friend would not say such a thing.', a: '本当の友だちなら、そんなことは言わないだろう。', exp: 'if がなく主節に would があるので、主語 A true friend に「もし〜なら」の仮定がふくまれています。' },
      { lv: 3, q: '( ) に入る最も適切なものを選ぼう。\nIf the sun ( ) to rise in the west, I would not change my mind.', choices: ['is', 'will', 'were', 'had'], a: 'C(were)', exp: 'If S were to 〜 は「仮に〜するとしたら」と、ありえない・可能性の低い未来を仮定します。太陽が西から昇るというありえない例に合います。' },
      { lv: 3, q: 'if を使って書きかえよう。\nTo hear him speak English, you would take him for an American.', a: 'If you heard him speak English, you would take him for an American.', exp: 'to 不定詞が条件の働きをしています。主節が would + 原形なので仮定法過去の If you heard 〜 に戻します。take A for B は「A を B だと思う」です。' },
      { lv: 3, q: '誤りを直そう。\nIf I would have known your address, I would have written to you.', a: 'would have known → had known', exp: 'if 節には would を使わず、過去の事実に反する仮定は had + 過去分詞で表します。主節の would have written は正しい形です。' },
      { lv: 3, q: '( ) に入る最も適切なものを選ぼう。\nIt is high time the government ( ) action.', choices: ['takes', 'took', 'will take', 'has taken'], a: 'B(took)', exp: 'It is high time S + 過去形 で「とっくに〜してよいころだ」。政府がまだ行動していないことへの不満を表します。' }
    ]
  });

  add('e_emph', {
    pat: [
      { name: '強調構文か形式主語か', freq: 'とてもよく出る', when: 'It is 〜 that … の文の和訳や、( ) に that・who を入れる問題で、It is と that を取りのぞいて文が成り立つかを判断するときです。', how: ['It is(was) と that を取りのぞきます。', '残りが完全な文として成り立てば強調構文で、It is と that の間の語句を「…なのは〜だ」と強調して訳します。', '成り立たず、It is の後ろが形容詞などで that 以下が主語なら形式主語構文です。'], ex: { q: '強調構文か形式主語構文かを答え、和訳しよう。\nIt was in this room that the meeting was held.', a: '強調構文。会議が開かれたのはこの部屋だった。', exp: 'It was と that を取りのぞくと、The meeting was held in this room. と完全な文になるので強調構文です。強調されているのは in this room(場所)です。' } },
      { name: '否定語が文頭に来たときの倒置', freq: 'とてもよく出る', when: 'Never・Little・Rarely・Not only・Only + 副詞句 などが文頭にあり、その後ろの語順を問う問題です。', how: ['文頭に否定・制限の語句があるかを確かめます。', 'その後ろは疑問文と同じ語順(助動詞・be 動詞 + S)にします。', '一般動詞の文なら do・does・did を補い、完了形なら have・had を前に出します。'], ex: { q: '並べかえよう。\n「こんなに美しい景色は見たことがない。」\nNever (I / have / such / seen) a beautiful view.', a: 'Never have I seen such a beautiful view.', exp: '否定語 Never が文頭に出たので、後ろは疑問文の語順 have I seen になります。I have never seen such a beautiful view. を強調した形です。' } },
      { name: 'Not until 〜 と It is not until 〜 that …', freq: 'よく出る', when: '「〜して初めて…した」という日本語や、Not until・It was not until の書きかえ問題です。', how: ['「〜まで…しなかった」=「〜して初めて…した」と意味を確かめます。', 'It was not until 〜 that S V(ふつうの語順)の強調構文にします。', 'Not until 〜 を文頭に出すときは、主節を倒置(did S 原形)にします。'], ex: { q: 'It was not until … を使って書きかえよう。\nI didn\'t know the truth until I read his letter.', a: 'It was not until I read his letter that I knew the truth.', exp: 'not until 〜 を強調構文で前に出し、that の後ろはふつうの語順の肯定文にします。訳:彼の手紙を読んで初めて、私は真実を知った。' } },
      { name: 'So do I / Neither do I と So I do', freq: 'よく出る', when: '会話文で「私も(そうだ)」「私も(〜ない)」と答える空所補充や、So + S + V と So + V + S の区別を問う問題です。', how: ['前の文が肯定か否定かを確かめます。', '肯定なら So + 助動詞 + S、否定なら Neither(Nor)+ 助動詞 + S にします。', '助動詞は前の文に合わせます(一般動詞の過去なら did、完了なら have)。So I do(S + V の語順)は「本当にそうだ」の同意で、意味がちがいます。'], ex: { q: '( ) に入る語を入れよう。\nA: I haven\'t finished my homework yet.\nB: ( ) ( ) I.', a: 'Neither have(Nor have)', exp: 'A の文は否定の現在完了なので、「私も(終わって)いない」は Neither + have + I です。So have I は肯定の文に答えるときに使います。' } },
      { name: '話法の転換(伝達動詞・代名詞・時を表す語)', freq: 'よく出る', when: '直接話法 ⇔ 間接話法の書きかえで、said to・told・asked・told 人 to などを選ぶ問題です。', how: ['引用文が平叙文・疑問文・命令文のどれかを見て、伝達動詞(told / asked / told 人 to)を決めます。', '代名詞を話し手から見た形に、時制を伝達動詞に合わせて一つ前に直します。', 'now → then、today → that day、tomorrow → the next day など、時や場所を表す語も直します。'], ex: { q: '間接話法に書きかえよう。\nShe said to me, “Where do you live?”', a: 'She asked me where I lived.', exp: '疑問文なので伝達動詞は asked、疑問詞の後ろはふつうの語順 I lived にします。you は me から見た I、時制は asked に合わせて過去形にします。' } }
    ],
    more: [
      { lv: 1, q: '強調構文を使って、下線部を強調しよう。\n【Ken】 broke the window.', a: 'It was Ken that(who) broke the window.', exp: '強調したい語を It was と that の間に置きます。人を強調するときは who も使えます。訳:窓を割ったのはケンだった。' },
      { lv: 1, q: '( ) に入る最も適切なものを選ぼう。\nA: I like summer.\nB: So ( ) I.', choices: ['am', 'do', 'like', 'have'], a: 'B(do)', exp: 'A の文の動詞は一般動詞の現在形 like なので、So do I(私も)になります。' },
      { lv: 1, q: '並べかえよう。\n「彼がこんなに怒るのを見たことがない。」\nNever (seen / I / have / him) so angry.', a: 'Never have I seen him so angry.', exp: '否定語 Never が文頭に出ると、後ろは疑問文の語順になります。完了形なので have を I の前に出します。' },
      { lv: 1, q: '間接話法に書きかえよう。\nHe said, “I am tired.”', a: 'He said (that) he was tired.', exp: 'I を he に、時制を said に合わせて am から was にします。平叙文なので伝達動詞は said のままです。' },
      { lv: 1, q: '( ) に入る最も適切なものを選ぼう。\nA: I can\'t swim.\nB: ( ) can I.', choices: ['So', 'Neither', 'Too', 'Either'], a: 'B(Neither)', exp: '否定の文に「私も〜ない」と答えるので Neither + 助動詞 + S です。can\'t に合わせて can を使います。' },
      { lv: 1, q: '和訳しよう。\nIt is you that are wrong.', a: 'まちがっているのはあなただ。', exp: 'It is と that を取りのぞくと You are wrong. になる強調構文です。that の後ろの動詞は強調される you に合わせて are になります。' },
      { lv: 1, q: '( ) に入る語を補って、省略された語を答えよう。\nWhen ( ) young, he lived in London.', a: 'he was(When he was young)', exp: '時の接続詞の後ろで、主節と同じ主語 + be 動詞は省略できます。When young は When he was young の省略です。' },
      { lv: 2, q: '( ) に入る最も適切なものを選ぼう。\nLittle ( ) that he was being watched.', choices: ['he knew', 'did he know', 'he did know', 'knew he'], a: 'B(did he know)', exp: '否定の意味の Little が文頭に出たので倒置します。一般動詞の過去なので did he know です。訳:彼は見張られているとは夢にも思わなかった。' },
      { lv: 2, q: '間接話法に書きかえよう。\nMy mother said to me, “Clean your room.”', a: 'My mother told me to clean my room.', exp: '命令文は tell + 人 + to 不定詞で表します。your は話し手から見た my に直します。' },
      { lv: 2, q: 'Not until を文頭に置いて書きかえよう。\nShe didn\'t notice her mistake until the teacher pointed it out.', a: 'Not until the teacher pointed it out did she notice her mistake.', exp: 'Not until 〜 が文頭に出ると、主節は倒置して did she notice になります。until 節の中は倒置しません。' },
      { lv: 2, q: '( ) に入る最も適切なものを選ぼう。\nIt was not until he was forty ( ) he started to paint.', choices: ['when', 'that', 'which', 'then'], a: 'B(that)', exp: 'It was not until 〜 that … の強調構文です。when にはしません。訳:彼は40歳になって初めて絵を描き始めた。' },
      { lv: 2, q: '和訳しよう。\nNot only did he win the race, but he also broke the record.', a: '彼はレースに勝っただけでなく、記録も破った。', exp: 'Not only が文頭に出たので、前半は did he win と倒置しています。but also 以下はふつうの語順です。' },
      { lv: 2, q: '( ) に入る最も適切なものを選ぼう。\nWhat on earth ( ) you doing here?', choices: ['do', 'are', 'have', 'did'], a: 'B(are)', exp: 'on earth は疑問詞を強めて「いったい」の意味を加えます。文の形は What are you doing here? のままです。' },
      { lv: 2, q: '間接話法に書きかえよう。\nHe said to me, “Are you free tomorrow?”', a: 'He asked me if(whether) I was free the next day.', exp: 'Yes / No で答える疑問文は if・whether でつなぎます。you → I、are → was、tomorrow → the next day に直します。' },
      { lv: 2, q: '( ) に入る語を入れよう。\nHe is, ( ) I know, an honest man.', a: 'as far as', exp: 'as far as I know は「私の知る限りでは」という挿入句です。コンマではさまれた部分を取りのぞいても文が成り立ちます。' },
      { lv: 3, q: '下線部を強調する強調構文に書きかえよう。\nWhat made you so angry?(What を強調)', a: 'What was it that made you so angry?', exp: '疑問詞を強調するときは、疑問詞 + was it that 〜 の形にします。訳:いったい何があなたをそんなに怒らせたのか。' },
      { lv: 3, q: '倒置をもとの語順に戻して和訳しよう。\nOnly after the accident did they realize how dangerous the road was.', a: 'They realized how dangerous the road was only after the accident.\n事故が起きて初めて、彼らはその道がどれほど危険かに気づいた。', exp: 'Only + 副詞句が文頭に出て、did they realize と倒置しています。only after 〜 は「〜して初めて」と訳すと自然です。' },
      { lv: 3, q: '( ) に入る最も適切なものを選ぼう。\nOn the hill ( ) an old castle.', choices: ['stands', 'standing', 'it stands', 'does stand'], a: 'A(stands)', exp: '場所を表す語句が文頭に出ると、V + S の語順になることがあります。主語は an old castle(単数)なので stands です。' },
      { lv: 3, q: '和訳しよう。\nSo tired was she that she fell asleep at once.', a: '彼女はとても疲れていたので、すぐに眠ってしまった。', exp: 'She was so tired that 〜 の so tired を文頭に出して倒置した形です。強調のために語順が変わっていますが、意味は so 〜 that の構文と同じです。' },
      { lv: 3, q: '誤りを直そう。\nNo sooner I had arrived than it started to snow.', a: 'I had → had I', exp: 'No sooner が文頭に出ると、後ろは倒置して had I arrived にします。No sooner had S 過去分詞 than … で「〜するとすぐに…」です。' }
    ]
  });

  add('ex_eng', {
    pat: [
      { name: '時制の目印から形を決める', freq: 'とてもよく出る', when: '動詞の形だけが選択肢で並び、文中に since・for・by the time・ago・yesterday などの時を表す語句があるときです。', how: ['まず文中の時の目印(since・for・ago・by the time・until now など)に印をつけます。', '目印から「基準の時点(今・過去・未来)」と「完了・継続・進行」のどれかを決めます。', '最後に、時・条件の副詞節の中かどうか(will を使わない)を確かめます。'], ex: { q: '( ) に入る最も適切なものを選ぼう。\nShe ( ) in this company since she graduated.\n① works ② worked ③ has worked ④ will work', a: '③(has worked)', exp: 'since she graduated(卒業して以来)は、過去から今までの継続を表す目印です。基準が今なので現在完了 has worked を選びます。' } },
      { name: '提案・要求の that 節:原形(should)', freq: 'とてもよく出る', when: 'suggest・propose・insist・demand・recommend や It is necessary / important that の後ろの動詞の形を問うときです。', how: ['that 節の前の動詞・形容詞が「提案・要求・必要」を表すかを確かめます。', '表していれば、that 節の中は主語や時制にかかわらず原形(または should + 原形)にします。', 'suggest が「〜を示す・ほのめかす」の意味のときは、ふつうの時制になることにも注意します。'], ex: { q: '( ) 内の語を正しい形にしよう。\nThe doctor suggested that he ( stop ) smoking.', a: '(should) stop', exp: 'suggest(提案する)の後ろの that 節なので、主語が he で過去の文でも、原形 stop(または should stop)にします。stopped や stops にはしません。' } },
      { name: '主語と動詞の一致', freq: 'よく出る', when: '主語の後ろに長い修飾語(of 〜・関係詞節・分詞)がついていて、is / are や has / have を選ぶ問題です。', how: ['主語の中心となる名詞を見つけます(The number of 〜 なら number、A number of 〜 なら後ろの名詞)。', '修飾語をかっこでくくり、中心の名詞と動詞を直接つないで数を決めます。', 'either A or B・neither A nor B は B(動詞に近いほう)に合わせ、each・every は単数で受けます。'], ex: { q: '( ) に入る最も適切なものを選ぼう。\nThe number of students in the class ( ) increasing.\n① is ② are ③ have ④ be', a: '①(is)', exp: 'The number of 〜(〜の数)の中心の名詞は number(単数)なので is です。A number of students(たくさんの生徒)なら複数扱いで are になります。' } },
      { name: '数えられない名詞と数量の語', freq: 'よく出る', when: 'information・advice・furniture・homework・news などの名詞が出てきて、many / much や a / an、複数形の有無を問う問題です。', how: ['名詞が数えられるかどうかを確かめます。', '数えられない名詞には a / an をつけず、複数形にもせず、much・little・a lot of で量を表します。', '数えるときは a piece of advice のように単位の語を使います。'], ex: { q: '誤りを直そう。\nHe gave me many useful advices.', a: 'many useful advices → a lot of useful advice(much useful advice)', exp: 'advice は数えられない名詞なので、複数形にせず、many も使えません。a lot of・much で量を表すか、a piece of advice のように数えます。' } },
      { name: '動詞の語法:動詞 + O + to 不定詞 / 原形', freq: 'とてもよく出る', when: 'allow・let・make・help・ask・want などの後ろに O があり、その後ろの形(to do・do・doing)を問う問題です。', how: ['動詞が使役(make・let・have)・知覚(see・hear)か、それ以外かを見ます。', '使役・知覚動詞なら O の後ろは原形(状況により分詞)、allow・ask・want・tell・encourage なら to 不定詞です。', 'help は原形と to 不定詞のどちらも使えることを覚えておきます。'], ex: { q: '( ) に入る最も適切なものを選ぼう。\nMy parents won\'t let me ( ) out late.\n① go ② to go ③ going ④ went', a: '①(go)', exp: 'let は使役動詞で、let O 原形 で「O に(望みどおり)〜させてやる」。to go にはしません。allow なら allow me to go out です。' } }
    ],
    more: [
      { lv: 1, q: '( ) に入る最も適切なものを選ぼう。\nI ( ) to Kyoto three times.', choices: ['go', 'went', 'have been', 'am going'], a: 'C(have been)', exp: 'three times(3回)は経験の目印です。今までの経験を表すので現在完了 have been を選びます。' },
      { lv: 1, q: '( ) に入る最も適切なものを選ぼう。\nThere ( ) a lot of water in the bottle.', choices: ['is', 'are', 'were', 'have'], a: 'A(is)', exp: 'water は数えられない名詞なので単数扱いです。a lot of がついていても is を使います。' },
      { lv: 1, q: '( ) に入る最も適切なものを選ぼう。\nShe made her son ( ) his room.', choices: ['clean', 'to clean', 'cleaning', 'cleaned'], a: 'A(clean)', exp: 'make は使役動詞で、make O 原形 で「O に〜させる」です。to はつけません。' },
      { lv: 1, q: '( ) 内の語を正しい形にしよう。\nEach of the students ( have ) a computer.', a: 'has', exp: 'Each of 〜 は「〜のそれぞれ」で単数扱いです。students につられて have にしないよう注意します。' },
      { lv: 1, q: '( ) に入る最も適切なものを選ぼう。\nI saw him ( ) the road.', choices: ['cross', 'to cross', 'crossed', 'crosses'], a: 'A(cross)', exp: 'see は知覚動詞で、see O 原形 で「O が〜するのを見る」。to はつけません(進行中なら crossing も可)。' },
      { lv: 1, q: '( ) に入る最も適切なものを選ぼう。\nWe don\'t have ( ) homework today.', choices: ['many', 'much', 'a few', 'a'], a: 'B(much)', exp: 'homework は数えられない名詞なので、many や a few は使えません。量を表す much を使います。' },
      { lv: 1, q: '( ) 内の語を正しい形にしよう。\nI\'ll wait until he ( come ) back.', a: 'comes', exp: 'until 節は時の副詞節なので、未来のことでも現在形です。主語が he なので comes になります。' },
      { lv: 2, q: '( ) に入る最も適切なものを選ぼう。\nIt is important that everyone ( ) the rules.', choices: ['follows', 'follow', 'followed', 'will follow'], a: 'B(follow)', exp: 'It is important that 〜 の that 節は、必要・要求を表すので原形(または should + 原形)にします。' },
      { lv: 2, q: '( ) に入る最も適切なものを選ぼう。\nEither you or he ( ) to go.', choices: ['have', 'has', 'are', 'were'], a: 'B(has)', exp: 'either A or B は動詞に近い B(he)に合わせます。he なので has を使います。' },
      { lv: 2, q: '( ) に入る最も適切なものを選ぼう。\nThe teacher allowed us ( ) the dictionary.', choices: ['use', 'to use', 'using', 'used'], a: 'B(to use)', exp: 'allow O to do で「O が〜するのを許す」。let と意味は近いですが、allow は to 不定詞をとります。' },
      { lv: 2, q: '誤りを直そう。\nWe bought many furnitures for the new house.', a: 'many furnitures → a lot of furniture(much furniture)', exp: 'furniture は家具をまとめて表す数えられない名詞です。複数形にせず、量を表す語を使います。数えるときは a piece of furniture です。' },
      { lv: 2, q: '( ) に入る最も適切なものを選ぼう。\nI ( ) him since we were in junior high school.', choices: ['know', 'knew', 'have known', 'had known'], a: 'C(have known)', exp: 'since 〜(〜以来)は今までの継続を表す目印です。know は状態動詞なので、現在完了 have known を使います。' },
      { lv: 2, q: '( ) に入る最も適切なものを選ぼう。\nA number of people ( ) waiting outside.', choices: ['was', 'were', 'is', 'has'], a: 'B(were)', exp: 'A number of 〜 は「たくさんの〜」で、後ろの people に合わせて複数扱いです。The number of 〜 との区別がよく問われます。' },
      { lv: 2, q: '( ) に入る最も適切なものを選ぼう。\nI\'d like ( ) information about the tour.', choices: ['an', 'some', 'many', 'a few'], a: 'B(some)', exp: 'information は数えられない名詞なので、an・many・a few は使えません。some なら数えられない名詞にも使えます。' },
      { lv: 2, q: '( ) 内の語を正しい形にしよう。\nHe insisted that the meeting ( be ) postponed.', a: '(should) be', exp: 'insist(要求する)の後ろの that 節なので、過去の文でも原形 be(または should be)にします。' },
      { lv: 3, q: '( ) に入る最も適切なものを選ぼう。\nHis pale face suggested that he ( ) ill.', choices: ['be', 'should be', 'was', 'will be'], a: 'C(was)', exp: 'この suggest は「提案する」ではなく「示す・ほのめかす」の意味です。提案ではないので原形にせず、ふつうに時制を合わせて was にします。' },
      { lv: 3, q: '( ) に入る最も適切なものを選ぼう。\nNeither the students nor the teacher ( ) the answer.', choices: ['know', 'knows', 'are knowing', 'have known'], a: 'B(knows)', exp: 'neither A nor B は動詞に近い B(the teacher)に合わせるので、単数の knows を使います。' },
      { lv: 3, q: '誤りを1か所直そう。\nThe news that the team had won the game were broadcast all over the country.', a: 'were → was', exp: '主語の中心は news で、数えられない名詞なので単数扱いです。that 〜 game は news の内容を説明する同格の節なので、くくって考えます。' },
      { lv: 3, q: '( ) に入る最も適切なものを選ぼう。\nI\'ll lend you the book when I ( ) it.', choices: ['will finish', 'have finished', 'will have finished', 'finished'], a: 'B(have finished)', exp: 'when 節は時の副詞節なので will を使いません。「読み終えたら」と完了をはっきりさせるので現在完了を選びます。' },
      { lv: 3, q: '( ) に入る最も適切なものを選ぼう。\nThe teacher had the students ( ) the essay again.', choices: ['write', 'to write', 'written', 'writes'], a: 'A(write)', exp: 'have O 原形 は「O に〜させる・してもらう」。O(the students)が書く側なので原形です。the essay を O にするなら had the essay written です。' }
    ]
  });

  add('hd_eng', {
    pat: [
      { name: '並べかえ:動詞を決めて文型から組み立てる', freq: 'とてもよく出る', when: '語群の中に動詞が複数あり、どれを文の V にするか、どの語を準動詞・関係詞にするかを決める必要がある並べかえ問題です。', how: ['語群の動詞・準動詞(to・ing・過去分詞)に印をつけ、日本語の述語にあたる動詞を文の V に決めます。', 'V の語法(SVO・SVOC・O to do など)から、後ろに来る形を決めます。', '残った語で主語や修飾語のかたまり(名詞 + 関係詞節・前置詞句)を作り、最後に語数と意味を確かめます。'], ex: { q: '並べかえよう。\n「その知らせを聞いて、彼女はとても喜んだ。」\nThe news (her / very / made / happy).', a: 'The news made her very happy.', exp: '日本語は「彼女は喜んだ」ですが、主語が The news なので V は made です。make O C(O を C にする)の形で、her を O、very happy を C にします。無生物主語の典型的な並べかえです。' } },
      { name: '同格の that か関係代名詞の that か', freq: 'よく出る', when: 'fact・news・idea・belief・possibility などの名詞の直後に that 節があり、和訳や that の働きを問われるときです。', how: ['that 節の中が完全な文(S・O などが欠けていない)かを確かめます。', '完全なら同格の that で、「〜という(名詞)」と訳します。', '不完全(O などが欠けている)なら関係代名詞の that で、「〜する(名詞)」と前の名詞を説明して訳します。'], ex: { q: '下線部の that の働きを答え、和訳しよう。\nThe news 【that】 he told us was surprising.', a: '関係代名詞。彼が私たちに伝えた知らせは驚くべきものだった。', exp: 'that の後ろの he told us には、told の2つ目の O(何を伝えたか)が欠けています。不完全な文なので関係代名詞です。The news that he had won … なら完全な文なので同格です。' } },
      { name: '無生物主語の和訳', freq: 'とてもよく出る', when: '主語が物や出来事(The rain・This road・His advice)で、動詞が make・take・allow・enable・prevent・remind などの英文和訳です。', how: ['主語を「原因・手段・条件」と考え、「〜のために・〜によって・〜すれば」と訳します。', 'O になっている人を日本語の主語にします。', '動詞の意味を人を主語にした言い方に変えて(enable O to do → O は〜できる)、自然な日本語に整えます。'], ex: { q: '和訳しよう。\nThe heavy rain prevented us from going out.', a: '激しい雨のせいで、私たちは外出できなかった。', exp: '直訳は「激しい雨が私たちが外出するのをさまたげた」です。主語の The heavy rain を原因として「〜のせいで」と訳し、us を主語にして「私たちは外出できなかった」と整えます。' } },
      { name: '部分否定と全体否定', freq: 'とてもよく出る', when: 'not の後ろに all・every・always・necessarily・both・completely などがある英文の和訳や内容一致問題です。', how: ['not と「全部・いつも・必ず」を表す語がいっしょにあるかを確かめます。', 'あれば部分否定で、「すべてが〜とは限らない・いつも〜とは限らない」と訳します。', 'none・never・neither・no などは全体否定で「どれも〜ない」と訳し分けます。'], ex: { q: '和訳しよう。\nThe rich are not always happy.', a: 'お金持ちがいつも幸せだとは限らない。', exp: 'not always は部分否定で「いつも〜とは限らない」です。「お金持ちはいつも幸せではない(=いつも不幸)」と全体否定に訳さないよう注意します。the rich は「お金持ちの人々」です。' } },
      { name: '名詞構文を文に戻して訳す', freq: '難関大で出る', when: '主語や目的語に「動詞・形容詞から作られた名詞 + of 〜」(the arrival of 〜・his refusal to 〜・the importance of 〜)が入っている英文和訳です。', how: ['動詞・形容詞から作られた名詞(arrival・refusal・importance など)を見つけます。', 'その名詞をもとの動詞・形容詞に戻し、of 〜 や所有格を主語・目的語として「〜が…すること」と文の形にします。', '文全体の動詞とつなげて、自然な日本語に整えます。'], ex: { q: '和訳しよう。\nHis sudden departure surprised everyone.', a: '彼が突然出発したので、みんなが驚いた。', exp: 'departure を動詞 depart に、sudden を副詞 suddenly に戻すと He departed suddenly. になります。無生物主語でもあるので、「彼が突然出発したので」と原因として訳すと自然です。' } }
    ],
    more: [
      { lv: 1, q: '並べかえよう。\n「この道を行けば駅に着きます。」\nThis road (you / take / to / will) the station.', a: 'This road will take you to the station.', exp: '無生物主語 This road を主語に、take O to 〜(O を〜に連れていく)の形を作ります。「この道を行けば」と条件のように訳されます。' },
      { lv: 1, q: '和訳しよう。\nI don\'t know all of them.', a: '私は彼ら全員を知っているわけではない。', exp: 'not と all がいっしょにあるので部分否定です。「全員を知らない」ではなく「全員を知っているわけではない(知っている人もいる)」と訳します。' },
      { lv: 1, q: '下線部の that の働きを答えよう。\nI heard the news 【that】 our team had won.', a: '同格の that(「〜という知らせ」)', exp: 'that の後ろの our team had won は完全な文なので、news の内容を説明する同格の that です。訳:私たちのチームが勝ったという知らせを聞いた。' },
      { lv: 1, q: '和訳しよう。\nA short walk will bring you to the lake.', a: '少し歩けば、湖に着くでしょう。', exp: '無生物主語の A short walk を「少し歩けば」と条件で訳し、you を主語にします。bring O to 〜 は「O を〜に連れてくる」です。' },
      { lv: 1, q: '並べかえよう。\n「彼は何も言わずに部屋を出ていった。」\nHe left the room (saying / without / anything).', a: 'He left the room without saying anything.', exp: 'without + 動名詞で「〜せずに」。前置詞の後ろなので動名詞 saying を使い、anything を O にします。' },
      { lv: 1, q: '和訳しよう。\nNot every student likes math.', a: 'すべての生徒が数学を好きなわけではない。', exp: 'Not every 〜 は部分否定で「すべての〜が…わけではない」です。every のあとは単数名詞・単数の動詞(likes)になります。' },
      { lv: 1, q: '和訳しよう。\nWhat made you think so?', a: 'どうしてそう思ったのですか。', exp: '直訳は「何があなたにそう思わせたのか」です。What made you 〜? は Why did you 〜? と同じく、理由をたずねる言い方として訳します。' },
      { lv: 2, q: '並べかえよう。\n「その写真を見ると、いつも子どものころを思い出す。」\nThe picture always (of / reminds / my / me) childhood.', a: 'The picture always reminds me of my childhood.', exp: 'remind O of 〜 で「O に〜を思い出させる」。無生物主語の文で、日本語の「思い出す」の主語は me になっています。' },
      { lv: 2, q: '和訳しよう。\nThe discovery of the new medicine saved many lives.', a: 'その新しい薬が発見されたことで、多くの命が救われた。', exp: 'discovery を動詞に戻すと「新しい薬が発見された」。名詞構文の主語を原因として訳し、saved many lives を「多くの命が救われた」と人や命を主語にすると自然です。' },
      { lv: 2, q: '和訳しよう。\nThere is no possibility that he will come.', a: '彼が来る可能性はまったくない。', exp: 'that he will come は完全な文なので、possibility の内容を表す同格の that 節です。「〜という可能性」と訳します。' },
      { lv: 2, q: '並べかえよう。\n「お金がたくさんあるからといって、幸せになれるとは限らない。」\nHaving a lot of money (necessarily / does / make / not) you happy.', a: 'Having a lot of money does not necessarily make you happy.', exp: 'not necessarily は「必ずしも〜とは限らない」という部分否定です。動名詞の主語のあとに does not necessarily make O C と続けます。' },
      { lv: 2, q: '和訳しよう。\nHis refusal to help us was unexpected.', a: '彼が私たちを手伝うのを断ったことは、思いがけないことだった。', exp: 'refusal to do は refuse to do(〜するのを断る)の名詞構文です。「彼が〜を断ったこと」と文に戻して訳します。' },
      { lv: 2, q: '和訳しよう。\nNeither of the answers is correct.', a: 'どちらの答えも正しくない。', exp: 'neither は「(2つの)どちらも〜ない」という全体否定です。「どちらかが正しくない」という部分否定とまちがえないようにします。' },
      { lv: 2, q: '並べかえよう。\n「この機械のおかげで、私たちは時間を節約できる。」\nThis machine (to / us / enables / save) time.', a: 'This machine enables us to save time.', exp: 'enable O to do で「O が〜できるようにする」。無生物主語の文で、日本語では「〜のおかげで O は…できる」と訳されます。' },
      { lv: 2, q: '和訳しよう。\nIt is not too much to say that the internet changed the world.', a: 'インターネットが世界を変えたと言っても言いすぎではない。', exp: 'It is not too much to say that 〜 は「〜と言っても言いすぎではない」という決まった表現です。It は to say 以下を指す形式主語です。' },
      { lv: 3, q: '和訳しよう。\nThe importance of sleep cannot be overemphasized.', a: '睡眠の大切さは、いくら強調してもしすぎることはない。', exp: 'cannot be overemphasized は「強調しすぎることはできない」=「いくら強調してもしすぎることはない」。cannot 〜 too … と同じ発想の表現です。' },
      { lv: 3, q: '並べかえよう。\n「彼女が何を言おうとしているのか、私にはさっぱり分からなかった。」\nI had (idea / what / no / she) was trying to say.', a: 'I had no idea what she was trying to say.', exp: 'have no idea + 疑問詞節で「〜がまったく分からない」。what の後ろはふつうの語順 she was trying to say になります。' },
      { lv: 3, q: '和訳しよう。\nA moment\'s hesitation cost him the chance.', a: '一瞬ためらったせいで、彼はその機会を失った。', exp: 'cost O O は「O に O を失わせる」。名詞構文 A moment\'s hesitation を「一瞬ためらったこと」と文に戻し、原因として訳します。' },
      { lv: 3, q: '和訳しよう。\nYou cannot be too careful when you drive a car.', a: '車を運転するときは、いくら注意してもしすぎることはない。', exp: 'cannot 〜 too … は「いくら…しても〜しすぎることはない」。「注意しすぎることはできない」と直訳しないようにします。' },
      { lv: 3, q: '下線部の that の働きを答え、和訳しよう。\nThe idea 【that】 she suggested at the meeting was accepted.', a: '関係代名詞。彼女が会議で提案した考えは受け入れられた。', exp: 'that の後ろの she suggested at the meeting には suggested の O が欠けているので関係代名詞です。名詞 idea の後ろでも、同格とは限りません。' }
    ]
  });

  add('e_h5', {
    pat: [
      { name: '接頭辞・語根から意味を推測する', freq: 'よく出る', when: '長文の中に知らない単語があり、その意味や言いかえを選ぶ問題で、語の前半・中心部分に見覚えのある形があるときです。', how: ['語を接頭辞・語根・接尾辞に分けます(un + predict + able)。', '接頭辞(un- 否定、re- 再び、pre- 前に、inter- 間に)と語根(port 運ぶ、spect 見る、dict 言う)の意味をつなげます。', '推測した意味が文脈に合うかを必ず確かめます(語源だけで決めない)。'], ex: { q: '語の成り立ちから意味を推測しよう。\nThe weather in the mountains is often unpredictable.', a: 'unpredictable = 予測できない', exp: 'un(否定)+ pre(前に)+ dict(言う)+ able(〜できる)と分けると、「前もって言うことができない」=「予測できない」となります。山の天気は変わりやすい、という文脈にも合います。' } },
      { name: '接尾辞で品詞を見分ける(空所の品詞問題)', freq: 'とてもよく出る', when: '同じ語の仲間(decide / decision / decisive / decisively)が選択肢に並び、空所に入る品詞を問う問題です。', how: ['空所の前後を見て、入るべき品詞を決めます(冠詞の後ろ → 名詞、be 動詞の後ろ → 形容詞、動詞を修飾 → 副詞)。', '接尾辞で品詞を見分けます(-tion・-ment・-ness → 名詞、-ive・-ful・-ous・-able → 形容詞、-ly → 副詞、-ize・-en・-fy → 動詞)。', '選んだ語を入れて文の意味が通るかを確かめます。'], ex: { q: '( ) に入る最も適切なものを選ぼう。\nShe made an important ( ) about her future.\n① decide ② decision ③ decisive ④ decisively', a: '②(decision)', exp: '冠詞 an と形容詞 important の後ろなので、名詞が入ります。-sion は名詞を作る接尾辞なので decision(決定)です。make a decision で「決定する」です。' } },
      { name: '多義語の意味を文脈で決める', freq: 'とてもよく出る', when: 'run・fine・last・address・cover など、よく知っている単語が見なれない使われ方をしている文の意味を問う問題です。', how: ['その単語のいちばん中心的な意味(イメージ)を思い出します。', '文の中での働き(品詞・後ろに O があるか)を確かめます。', '中心の意味から広げて、文脈に合う訳を選びます(run a shop → 店を「動かす」→ 経営する)。'], ex: { q: '下線部の意味を答えよう。\nHis family 【runs】 a small hotel by the sea.', a: '経営する', exp: 'run の中心は「(とぎれなく)動く・動かす」です。後ろに O(a small hotel)があるので「ホテルを動かす」=「経営する」の意味になります。「走る」ではありません。' } },
      { name: '文脈での語の言いかえ(同意語選択)', freq: 'よく出る', when: '長文中の下線部の語に最も意味が近いものを選ぶ問題です。辞書的に近い語が複数あることが多いです。', how: ['下線部の語を空所にして、前後の文から入るべき意味を予想します。', '選択肢をそれぞれ空所に入れて、文脈に合うかを確かめます。', '辞書の1番目の意味ではなく、その文での意味に合うものを選びます。'], ex: { q: '下線部に最も意味が近いものを選ぼう。\nThe new rule will 【affect】 all students.\n① influence ② protect ③ invite ④ ignore', a: '①(influence)', exp: 'affect は「〜に影響を与える」という動詞で、influence が最も近い意味です。名詞の effect(影響)とまちがえやすいので、つづりと品詞を区別して覚えましょう。' } },
      { name: 'コロケーション(語と語の相性)', freq: 'よく出る', when: 'make / do / take / have などの動詞と名詞の組み合わせや、heavy rain・strong coffee のような形容詞と名詞の相性を問う問題です。', how: ['空所の後ろの名詞を見ます。', 'その名詞と決まって組む動詞・形容詞を思い出します(make a mistake、do one\'s homework、take a break)。', '日本語の直訳(「宿題を作る」)で選ばないよう、まとまりで覚えた表現で判断します。'], ex: { q: '( ) に入る最も適切なものを選ぼう。\nYou look tired. Why don\'t you ( ) a break?\n① make ② do ③ take ④ get', a: '③(take)', exp: '「休けいする」は take a break と言います。take は「(時間・機会を)とる」というイメージで、take a rest・take a nap も同じなかまです。' } }
    ],
    more: [
      { lv: 1, q: '( ) に入る最も適切なものを選ぼう。\nThe ( ) of the experiment surprised everyone.', choices: ['succeed', 'success', 'successful', 'successfully'], a: 'B(success)', exp: '冠詞 The の後ろで、of 〜 が続くので名詞が入ります。success(成功)が名詞、successful は形容詞、successfully は副詞です。' },
      { lv: 1, q: '接頭辞から意味を答えよう。\n(1) rebuild (2) disagree', a: '(1) 建て直す (2) 意見が合わない(反対する)', exp: 're- は「再び」、dis- は「反対・否定」を表す接頭辞です。build・agree の意味と組み合わせて考えます。' },
      { lv: 1, q: '( ) に入る最も適切なものを選ぼう。\nPlease drive ( ).', choices: ['careful', 'care', 'carefully', 'carefulness'], a: 'C(carefully)', exp: '動詞 drive を修飾するので副詞が入ります。-ly は形容詞を副詞にする接尾辞で、carefully は「注意深く」です。' },
      { lv: 1, q: '( ) に入る最も適切なものを選ぼう。\nI ( ) a mistake on the test.', choices: ['did', 'made', 'took', 'had'], a: 'B(made)', exp: '「まちがえる」は make a mistake と言います。do や take とは組みません。' },
      { lv: 1, q: '下線部の意味を答えよう。\nHe had to pay a 【fine】 for parking there.', a: '罰金', exp: 'fine は形容詞の「元気な・すばらしい」がよく知られていますが、pay a fine のように名詞で使うと「罰金」の意味になります。' },
      { lv: 1, q: '次の語の品詞を答えよう。\n(1) happiness (2) dangerous (3) widen', a: '(1) 名詞 (2) 形容詞 (3) 動詞', exp: '-ness は名詞、-ous は形容詞、-en は「〜にする」という動詞を作る接尾辞です。wide(広い)→ widen(広げる)です。' },
      { lv: 1, q: '( ) に入る最も適切なものを選ぼう。\nThere was ( ) rain last night.', choices: ['strong', 'heavy', 'big', 'many'], a: 'B(heavy)', exp: '「激しい雨」は heavy rain と言います。強い風は strong wind で、名詞によって組む形容詞が決まっています。' },
      { lv: 2, q: '語の成り立ちから意味を推測しよう。\nThe two countries have an important trade relationship, and they import and export many goods.', a: 'import = 輸入する、export = 輸出する', exp: 'port は「運ぶ」、im- は「中へ」、ex- は「外へ」です。「国の中へ運ぶ」= 輸入、「外へ運ぶ」= 輸出となります。' },
      { lv: 2, q: '下線部の意味を答えよう。\nThe meeting 【lasted】 for three hours.', a: '続いた', exp: 'last は形容詞「最後の」のほか、動詞で「続く・もつ」の意味があります。後ろに for three hours(期間)があるので「続いた」です。' },
      { lv: 2, q: '( ) に入る最も適切なものを選ぼう。\nThe government must ( ) the problem of the aging society.', choices: ['address', 'adopt', 'admire', 'adjust'], a: 'A(address)', exp: 'address は「住所・演説」のほか、動詞で「(問題に)取り組む」の意味があります。the problem を O にとるので、この意味が合います。' },
      { lv: 2, q: '( ) に入る最も適切なものを選ぼう。\nThe new law will have a great ( ) on our lives.', choices: ['affect', 'effect', 'effective', 'effectively'], a: 'B(effect)', exp: '冠詞 a と形容詞 great の後ろなので名詞が入ります。have an effect on 〜 で「〜に影響を与える」。affect は動詞です。' },
      { lv: 2, q: '下線部に最も意味が近いものを選ぼう。\nIt is hard to 【put up with】 the noise.', choices: ['tolerate', 'reduce', 'create', 'measure'], a: 'A(tolerate)', exp: 'put up with 〜 は「〜をがまんする」で、tolerate・stand・bear と同じ意味です。' },
      { lv: 2, q: '( ) 内の語を、文に合う形に変えよう。\nWe need to ( modern ) the old system.', a: 'modernize', exp: 'need to の後ろなので動詞が必要です。-ize は「〜化する」という動詞を作る接尾辞で、modernize は「近代化する」です。' },
      { lv: 2, q: '下線部の意味を答えよう。\nThe book 【covers】 the history of Japan from ancient times to the present.', a: '扱う(取り上げる)', exp: 'cover の中心は「おおう」です。本が歴史を「おおう」=「範囲として扱う」の意味になります。ニュースが事件を cover するときは「報道する」です。' },
      { lv: 2, q: '( ) に入る最も適切なものを選ぼう。\nShe gave a very ( ) answer to the question.', choices: ['think', 'thought', 'thoughtful', 'thoughtfully'], a: 'C(thoughtful)', exp: '冠詞と名詞 answer の間で、名詞を修飾するので形容詞が入ります。-ful は形容詞の接尾辞で、thoughtful は「よく考えられた」です。' },
      { lv: 3, q: '下線部の意味を文脈から答えよう。\nThe company decided to 【postpone】 the event until next spring because of the storm.', a: '延期する', exp: 'post(後に)+ pone(置く)で「後に置く」=「延期する」。until next spring(来年の春まで)という語句も「延期」の意味を支えています。' },
      { lv: 3, q: '下線部の意味を答えよう。\nThe two words are 【interchangeable】 in this sentence.', a: '交換可能な(入れかえても同じ意味になる)', exp: 'inter(間で)+ change(交換する)+ able(〜できる)です。2つの語を入れかえられる、つまりこの文ではどちらを使ってもよいという意味です。' },
      { lv: 3, q: '下線部の意味として最も適切なものを選ぼう。\nThe store 【carries】 a wide range of organic foods.', choices: ['運ぶ', '(商品として)置いている', '持ち歩く', '支える'], a: 'B((商品として)置いている)', exp: 'carry の中心は「持って運ぶ」ですが、店が主語で商品が O のときは「(店に)置いている・取り扱っている」の意味になります。' },
      { lv: 3, q: '( ) に入る最も適切なものを選ぼう。\nThe scientist ( ) an important role in the project.', choices: ['did', 'played', 'made', 'took'], a: 'B(played)', exp: '「役割を果たす」は play a role(part)in 〜 と組みます。take a role とは言わないのがふつうで、コロケーションとしてまとめて覚えます。' },
      { lv: 3, q: '下線部の意味として文脈に合うものを答えよう。\nThe speaker made a 【point】 that education should start at home.', a: '主張(論点・言いたいこと)', exp: 'point は「点・先」のほか、make a point で「主張する・要点を述べる」の意味になります。後ろの that 節がその主張の内容です。' }
    ]
  });

  add('e_idiom', {
    pat: [
      { name: '熟語を1語の動詞で言いかえる', freq: 'とてもよく出る', when: '下線部の熟語に最も近い意味の1語を選ぶ問題や、熟語と1語の動詞の書きかえ問題です。', how: ['熟語の動詞と副詞・前置詞のイメージから、だいたいの意味をつかみます(put off = 後ろに置く)。', '代表的な対応(put off = postpone、look into = investigate、give up = abandon、make up = invent・compose)を思い出します。', '選択肢を下線部に入れて、文全体の意味が変わらないかを確かめます。'], ex: { q: '下線部に最も意味が近いものを選ぼう。\nThe police are 【looking into】 the accident.\n① ignoring ② investigating ③ preventing ④ causing', a: '②(investigating)', exp: 'look into は「中をのぞきこむ」から「調べる・調査する」の意味になります。1語にすると investigate です。look for(さがす)・look after(世話をする)と区別しましょう。' } },
      { name: 'to の後ろに 〜ing がくる熟語', freq: 'とてもよく出る', when: 'look forward to・be used to・object to・when it comes to などの後ろの形を問う問題です。', how: ['to の前の語句が、決まった熟語かどうかを確かめます。', '熟語の to が前置詞なら、後ろは名詞か動名詞(〜ing)にします。', 'used to do(以前は〜した)と be used to 〜ing(〜に慣れている)のように、形の似た表現を区別します。'], ex: { q: '( ) 内の語を正しい形にしよう。\nShe is used to ( get ) up early.', a: 'getting', exp: 'be used to 〜 は「〜に慣れている」で、この to は前置詞なので後ろは動名詞です。She used to get up early.(以前は早起きしていた)とは意味がちがいます。' } },
      { name: '動詞 + 副詞の熟語と代名詞の位置', freq: 'よく出る', when: 'turn on・put off・pick up・give up などの目的語が it・them などの代名詞のときの語順を問う問題です。', how: ['熟語が「動詞 + 副詞」か「動詞 + 前置詞」かを確かめます。', '動詞 + 副詞なら、名詞の O は副詞の前後どちらにも置けますが、代名詞の O は必ず動詞と副詞の間に置きます(turn it on)。', '動詞 + 前置詞(look at・look for)なら、代名詞も前置詞の後ろに置きます(look at it)。'], ex: { q: '正しい語順のものを選ぼう。\n① Please turn on it.\n② Please turn it on.', a: '②(Please turn it on.)', exp: 'turn on の on は副詞なので、代名詞 it は turn と on の間に置きます。名詞なら turn on the light・turn the light on のどちらでもかまいません。' } },
      { name: '熟語の受動態(前置詞を残す)', freq: 'よく出る', when: 'laugh at・speak to・take care of・look up to など、前置詞をふくむ熟語を受動態に書きかえる問題です。', how: ['熟語全体を1つの他動詞と考えます。', '熟語の O を主語にし、be + 過去分詞 にして熟語の残りの部分(前置詞など)をそのまま残します。', '前置詞の後ろにすぐ by 〜 が続く形(laughed at by)になることを確認します。'], ex: { q: '受動態に書きかえよう。\nEveryone looks up to the doctor.', a: 'The doctor is looked up to by everyone.', exp: 'look up to(〜を尊敬する)を1つの動詞と考え、is looked up to にします。前置詞 to を落とさず、そのあとに by everyone を続けます。' } },
      { name: '前置詞1つで意味が変わる熟語', freq: '難関大で出る', when: 'result in / result from、consist of / consist in、look for / look after のように、前置詞だけがちがう熟語の意味を問う問題です。', how: ['前置詞の中心イメージを思い出します(in = 中・結果として入る、from = 起点・出どころ、of = 構成要素)。', '主語と O のどちらが「原因」でどちらが「結果」かなど、関係の向きを確かめます。', 'A result in B(A の結果 B)⇔ B result from A(B は A から生じる)のように、向きを入れかえて確認します。'], ex: { q: '( ) に in か from を入れよう。\n(1) The accident resulted ( ) his carelessness.\n(2) His carelessness resulted ( ) the accident.', a: '(1) from (2) in', exp: '(1) は事故が不注意「から生じた」ので from。(2) は不注意が事故という「結果になった」ので in です。原因と結果の向きが逆になります。' } }
    ],
    more: [
      { lv: 1, q: '下線部に最も意味が近いものを選ぼう。\nThe game was 【put off】 because of rain.', choices: ['started', 'postponed', 'won', 'watched'], a: 'B(postponed)', exp: 'put off は「延期する」で、postpone と同じ意味です。雨のために試合が延期された、という文になります。' },
      { lv: 1, q: '( ) 内の語を正しい形にしよう。\nI\'m looking forward to ( see ) you.', a: 'seeing', exp: 'look forward to の to は前置詞なので、後ろは動名詞です。「あなたに会えるのを楽しみにしています」の意味です。' },
      { lv: 1, q: '( ) に入る最も適切なものを選ぼう。\nPlease take care ( ) yourself.', choices: ['for', 'of', 'with', 'to'], a: 'B(of)', exp: 'take care of 〜 は「〜の世話をする・〜を大事にする」。Take care of yourself. は「体に気をつけてね」の決まった表現です。' },
      { lv: 1, q: '( ) に入る最も適切なものを選ぼう。\nI can\'t find my glasses. Can you help me look ( ) them?', choices: ['at', 'for', 'after', 'into'], a: 'B(for)', exp: 'look for 〜 は「〜をさがす」です。眼鏡が見つからないので、さがすのを手伝ってほしいという文脈に合います。' },
      { lv: 1, q: '下線部に最も意味が近いものを選ぼう。\nShe 【gave up】 smoking last year.', choices: ['started', 'stopped', 'enjoyed', 'tried'], a: 'B(stopped)', exp: 'give up 〜ing は「〜するのをやめる・あきらめる」です。後ろは動名詞になります。' },
      { lv: 1, q: '( ) に入る最も適切なものを選ぼう。\nHe is good ( ) playing the guitar.', choices: ['in', 'at', 'on', 'for'], a: 'B(at)', exp: 'be good at 〜 は「〜が得意だ」。at は前置詞なので、後ろは動名詞 playing になります。' },
      { lv: 1, q: '正しい語順のものを選ぼう。', choices: ['Please pick up them.', 'Please pick them up.', 'Please up pick them.', 'Please pick them.'], a: 'B(Please pick them up.)', exp: 'pick up の up は副詞なので、代名詞 them は pick と up の間に置きます。' },
      { lv: 2, q: '受動態に書きかえよう。\nThe children laughed at the clown.', a: 'The clown was laughed at by the children.', exp: 'laugh at を1つの他動詞と考え、was laughed at にします。前置詞 at を残したまま by the children を続けます。' },
      { lv: 2, q: '( ) に入る最も適切なものを選ぼう。\nWhen it comes to ( ), nobody is better than Mika.', choices: ['cook', 'cooking', 'cooked', 'to cook'], a: 'B(cooking)', exp: 'when it comes to 〜 は「〜のことになると」で、to は前置詞です。後ろは名詞か動名詞なので cooking になります。' },
      { lv: 2, q: '下線部に最も意味が近いものを選ぼう。\nThe story was 【made up】 by a little boy.', choices: ['invented', 'destroyed', 'repeated', 'forgotten'], a: 'A(invented)', exp: 'make up には「(話などを)でっちあげる・作り出す」の意味があります。1語にすると invent です。' },
      { lv: 2, q: '( ) に入る最も適切なものを選ぼう。\nThis team consists ( ) eleven players.', choices: ['in', 'of', 'with', 'from'], a: 'B(of)', exp: 'consist of 〜 は「〜から成り立っている」。be made up of 〜 とも書きかえられます。consist in 〜 は「〜にある」です。' },
      { lv: 2, q: '受動態に書きかえよう。\nMy grandmother took care of the dog.', a: 'The dog was taken care of by my grandmother.', exp: 'take care of を1つの動詞と考えて、was taken care of とします。of を落とさないことがポイントです。' },
      { lv: 2, q: '( ) に入る最も適切なものを選ぼう。\nI object ( ) being treated like a child.', choices: ['to', 'for', 'against', 'with'], a: 'A(to)', exp: 'object to 〜 は「〜に反対する」で、to は前置詞です。後ろが動名詞 being treated になっていることも手がかりです。' },
      { lv: 2, q: '( ) に入る最も適切なものを選ぼう。\nI ran ( ) an old friend at the station yesterday.', choices: ['into', 'over', 'out', 'after'], a: 'A(into)', exp: 'run into 〜 は「〜に偶然会う」。come across 〜 とほぼ同じ意味です。run out of 〜(〜を使い果たす)と区別します。' },
      { lv: 2, q: '( ) に入る最も適切なものを選ぼう。\nWe have run out ( ) milk.', choices: ['of', 'from', 'with', 'off'], a: 'A(of)', exp: 'run out of 〜 は「〜を使い果たす・切らす」。訳:牛乳を切らしてしまった。' },
      { lv: 3, q: '( ) に in か from を入れよう。\nThe heavy rain resulted ( ) a flood.', a: 'in', exp: '大雨が原因で、洪水という結果になったので result in です。A flood resulted from the heavy rain. と向きを入れかえることもできます。' },
      { lv: 3, q: '( ) に入る最も適切なものを選ぼう。\nHappiness consists ( ) being satisfied with what you have.', choices: ['of', 'in', 'with', 'on'], a: 'B(in)', exp: 'consist in 〜 は「〜にある(〜が本質だ)」。訳:幸福は持っているもので満足することにある。consist of(〜から成る)との区別が問われます。' },
      { lv: 3, q: '下線部に最も意味が近いものを選ぼう。\nI can\'t 【make out】 what he is saying.', choices: ['understand', 'forget', 'repeat', 'believe'], a: 'A(understand)', exp: 'make out には「理解する・聞き取る・見分ける」の意味があります。can\'t make out で「(何を言っているのか)分からない」です。' },
      { lv: 3, q: '受動態に書きかえよう。\nA truck ran over the cat.', a: 'The cat was run over by a truck.', exp: 'run over(車が〜をひく)を1つの他動詞と考え、was run over にします。run の過去分詞は run です。' },
      { lv: 3, q: '2文の意味のちがいを説明しよう。\n(1) He used to play tennis.\n(2) He is used to playing tennis.', a: '(1) 彼は以前はよくテニスをしていた。(2) 彼はテニスをすることに慣れている。', exp: 'used to do は過去の習慣(今はしていない)、be used to 〜ing は「〜に慣れている」です。to の後ろの形と be 動詞の有無で区別します。' }
    ]
  });

  add('e_h6', {
    pat: [
      { name: '逆接マーカーの後ろが主張', freq: 'とてもよく出る', when: '段落の中に however・but・yet・in fact・actually などがあり、筆者の主張や要旨を問われるときです。', how: ['段落の中の逆接マーカーに印をつけます。', 'マーカーの前は一般論・よくある考え(譲歩)、後ろが筆者の言いたいことであることが多いと考えます。', '選択肢は、マーカーの後ろの内容を言いかえたものを選びます。'], ex: { q: '筆者の主張を日本語でまとめよう。\nMany people think that talent is the key to success. However, research shows that steady practice matters more.', a: '成功には才能よりも、こつこつ練習を続けることが大切だ。', exp: '前半は「多くの人が考えること」という一般論で、However の後ろが筆者の主張です。Many people think 〜. However … は、一般論を示してから否定する典型的な型です。' } },
      { name: '具体例(for example)の前が主張', freq: 'よく出る', when: 'for example・for instance・such as などのマーカーがあり、その段落の要点や下線部の言いかえを問われるときです。', how: ['具体例のマーカーを見つけます。', 'その直前の文が、例で説明されている抽象的な主張(トピックセンテンス)であることが多いと考えます。', '要点を問われたら、例そのものではなく、例がまとめて示している内容を選びます。'], ex: { q: 'この段落の要点として最も適切なものを選ぼう。\nAnimals communicate in many ways. For example, bees dance to show where flowers are, and whales use songs.\n① ハチは花の場所をおどりで伝える。② クジラは歌を使う。③ 動物はさまざまな方法で意思を伝え合う。④ 動物は人間と話せる。', a: '③', exp: 'For example の前の Animals communicate in many ways. が主張で、ハチとクジラはその具体例です。①②は例の一部にすぎず、要点ではありません。④は本文に書かれていません。' } },
      { name: '言いかえの選択肢を見抜く(内容一致)', freq: 'とてもよく出る', when: '内容一致問題で、本文と同じ単語を使った選択肢と、別の語で言いかえた選択肢が並んでいるときです。', how: ['選択肢のキーワードをもとに、本文の該当箇所を探します。', '本文と同じ単語が多い選択肢は、細部(主語・否定・数量)がずれていないか特に注意して確かめます。', '正解は、本文の内容を別の語で言いかえたものであることが多いと考えます。'], ex: { q: '本文の内容に合うものを選ぼう。\nThe library is closed on Mondays, but students can use the study room every day.\n① 図書館は毎日開いている。② 学習室は月曜日も使える。③ 学習室は月曜日は使えない。④ 図書館は学生だけが使える。', a: '②', exp: '本文の students can use the study room every day(毎日)を、「月曜日も使える」と言いかえた②が正解です。①は closed on Mondays に反し、③は every day に反します。④は書かれていません。' } },
      { name: '事実と意見を区別する', freq: 'よく出る', when: '共通テストなどで「事実(fact)」か「意見(opinion)」かを選ばせる問題です。', how: ['確かめられる数字・出来事・記録かどうかを見ます(事実)。', 'I think・should・better・best・interesting・too 〜 など、評価や判断を表す語があれば意見と考えます。', '数字が入っていても、「高すぎる」のような評価をふくむ文は意見と判断します。'], ex: { q: '意見(opinion)を表す文を選ぼう。\n① The museum opened in 2010.\n② It has about 3,000 works.\n③ It is the most exciting museum in the city.\n④ It is closed on Tuesdays.', a: '③', exp: '③の the most exciting(いちばんわくわくする)は、人によって感じ方が異なる評価なので意見です。①②④は記録や数字で確かめられるので事実です。' } },
      { name: '段落の役割(問題提起・具体例・反論・結論)', freq: '難関大で出る', when: '「第2段落の役割として最も適切なものを選べ」のように、段落全体の働きを問う問題です。', how: ['各段落の最初の1文とマーカー(However・For example・In conclusion など)を確かめます。', 'その段落が前の段落に対して、具体化・反対・原因・結論のどの関係にあるかを考えます。', '段落の内容そのものではなく、文章全体の中での「働き」を表す選択肢を選びます。'], ex: { q: '次の段落の役割として最も適切なものを選ぼう。\n(前の段落でスマートフォンの便利さが述べられたあと)\nOn the other hand, using smartphones for too long can cause health problems.\n① 前の段落の具体例 ② 前の段落と反対の面の提示 ③ 文章全体の結論 ④ 用語の定義', a: '②', exp: 'On the other hand(一方で)は、前の内容と対立する面を示すマーカーです。前の段落の「便利さ」に対して「健康への悪影響」という反対の面を述べているので②です。' } }
    ],
    more: [
      { lv: 1, q: '( ) に入る最も適切なものを選ぼう。\nI was very tired. ( ), I finished my homework.', choices: ['Therefore', 'Nevertheless', 'For example', 'In addition'], a: 'B(Nevertheless)', exp: '「とても疲れていた」と「宿題を終えた」は予想に反する関係なので、逆接の Nevertheless(それでも)が合います。' },
      { lv: 1, q: '( ) に入る最も適切なものを選ぼう。\nIt rained heavily. ( ), the game was canceled.', choices: ['However', 'As a result', 'For instance', 'On the other hand'], a: 'B(As a result)', exp: '大雨が原因で、試合が中止になったという結果を述べているので、As a result(その結果)が入ります。' },
      { lv: 1, q: '次の文は事実か意見か答えよう。\nThis city has a population of about 500,000.', a: '事実', exp: '人口は統計で確かめられる数字です。評価や判断を表す語はふくまれていないので事実です。' },
      { lv: 1, q: '( ) に入る最も適切なものを選ぼう。\nThere are many ways to save energy. ( ), you can turn off lights when you leave a room.', choices: ['For example', 'However', 'In contrast', 'Otherwise'], a: 'A(For example)', exp: '前の文の「省エネの方法がたくさんある」の具体例として、部屋の明かりを消すことを挙げています。' },
      { lv: 1, q: '次の文は事実か意見か答えよう。\nSummer is the best season for traveling.', a: '意見', exp: 'the best(いちばんよい)は人によって感じ方が異なる評価です。確かめられる事実ではないので意見です。' },
      { lv: 1, q: '( ) に入る最も適切なものを選ぼう。\nShe speaks English well. ( ), she can speak Chinese.', choices: ['In addition', 'However', 'Therefore', 'Instead'], a: 'A(In addition)', exp: '英語が話せることに加えて、中国語も話せるという情報を追加しているので In addition(さらに)が入ります。' },
      { lv: 1, q: '次の英文で、筆者の主張が書かれている文はどれか番号で答えよう。\n(1) Some people say that homework is useless. (2) However, I believe homework helps students review. (3) For example, it helps us remember new words.', a: '(2)', exp: '(1) は「〜と言う人もいる」という他人の意見、(2) は However の後ろの筆者の考え、(3) はその具体例です。' },
      { lv: 2, q: '本文の内容に合うものを選ぼう。\nThe event was planned for Saturday, but it was moved to Sunday because of the typhoon.', choices: ['イベントは土曜日に開かれた。', '台風のため、イベントは日曜日に変更された。', 'イベントは中止された。', '台風は日曜日に来た。'], a: 'B(台風のため、イベントは日曜日に変更された。)', exp: 'was moved to Sunday(日曜に移された)を「変更された」と言いかえた選択肢が正解です。中止ではなく延期である点に注意します。' },
      { lv: 2, q: '( ) に入る最も適切なものを選ぼう。\nCities are convenient to live in. ( ), the countryside offers clean air and quiet surroundings.', choices: ['Similarly', 'On the other hand', 'As a result', 'For example'], a: 'B(On the other hand)', exp: '都市の利点と、いなかの利点という対照的な内容を並べているので、On the other hand(一方で)が入ります。' },
      { lv: 2, q: '意見を表す文を選ぼう。', choices: ['The bridge is 300 meters long.', 'The bridge was built in 1998.', 'The bridge is too narrow for today\'s traffic.', 'About 20,000 cars cross the bridge every day.'], a: 'C(The bridge is too narrow for today\'s traffic.)', exp: 'too narrow(せますぎる)は「今の交通には不十分だ」という評価をふくむので意見です。ほかは数字や年で確かめられる事実です。' },
      { lv: 2, q: 'この段落の要点を日本語で答えよう。\nReading books has many benefits. It improves our vocabulary, helps us understand other people\'s feelings, and reduces stress.', a: '読書には多くの利点がある。', exp: '最初の文がトピックセンテンスで、後ろの3つ(語彙・他人の気持ち・ストレス)はその具体的な内容です。要点はまとめの文になります。' },
      { lv: 2, q: '( ) に入る最も適切なものを選ぼう。\nMost birds can fly. Penguins, ( ), cannot.', choices: ['therefore', 'however', 'for example', 'in addition'], a: 'B(however)', exp: '「ほとんどの鳥は飛べる」と「ペンギンは飛べない」は対立する内容なので、逆接の however が入ります。文中にはさむ使い方にも慣れておきましょう。' },
      { lv: 2, q: '下線部の具体例が説明している内容を選ぼう。\nSmall changes can make a big difference. 【For instance, using your own bag instead of plastic bags can reduce waste.】', choices: ['レジ袋は便利だ。', '小さな変化が大きなちがいを生む。', 'ごみを減らすのは難しい。', '自分の袋は高い。'], a: 'B(小さな変化が大きなちがいを生む。)', exp: 'For instance の前の文が主張で、下線部はその具体例です。「自分の袋を使う」という小さな変化が、ごみを減らすという大きなちがいにつながる例です。' },
      { lv: 2, q: '( ) に入る最も適切なものを選ぼう。\nThe company lost a lot of money last year. ( ), it had to close two factories.', choices: ['Consequently', 'Nevertheless', 'In contrast', 'For example'], a: 'A(Consequently)', exp: '大きな損失が原因で、工場を閉めなければならなかったという結果なので、Consequently(その結果)が入ります。' },
      { lv: 2, q: '本文の内容に合わないものを選ぼう。\nTom usually walks to school, but when it rains, his father drives him there.', choices: ['トムはふだん歩いて通学する。', '雨の日は父親がトムを車で送る。', 'トムは毎日車で通学する。', 'トムの通学方法は天気によって変わる。'], a: 'C(トムは毎日車で通学する。)', exp: 'usually walks(ふだんは歩く)とあるので、「毎日車で」は本文に合いません。D は本文全体の内容を言いかえたものです。' },
      { lv: 3, q: '筆者の主張を日本語で答えよう。\nIt is often said that technology makes people lonely. It is true that some people spend too much time on their phones. Still, technology also allows us to keep in touch with friends far away.', a: '技術は人と人とのつながりを保つのにも役立つ。', exp: 'It is often said(よく言われる)と It is true that 〜(確かに〜だ)は譲歩で、Still(それでも)の後ろが筆者の主張です。「譲歩 → 逆接 → 主張」の型です。' },
      { lv: 3, q: '第2文の役割として最も適切なものを選ぼう。\nMany young people are moving to big cities. This is mainly because there are more jobs there.', choices: ['具体例', '原因の説明', '反論', '結論'], a: 'B(原因の説明)', exp: 'This is mainly because 〜(これは主に〜だからだ)は、前の文の現象が起きている理由を説明する表現です。' },
      { lv: 3, q: '( ) に入る最も適切なものを選ぼう。\nThe plan seemed perfect. ( ), it failed because no one had considered the cost.', choices: ['In fact', 'In the end', 'In short', 'In addition'], a: 'B(In the end)', exp: '「完ぺきに見えた」計画が「結局失敗した」という最終的な結果を述べています。In the end(結局)が合います。' },
      { lv: 3, q: '本文の内容に最も合うものを選ぼう。\nNot all the students agreed with the new rule. Some thought it was too strict, while others welcomed it.', choices: ['生徒は全員新しい規則に反対した。', '生徒の意見は分かれた。', '生徒は全員新しい規則に賛成した。', '新しい規則はゆるすぎた。'], a: 'B(生徒の意見は分かれた。)', exp: 'Not all(全員が〜わけではない)は部分否定で、Some 〜, while others …(〜な人もいれば、…な人もいる)と続くので、意見が分かれたことが分かります。' },
      { lv: 3, q: '文章全体の型として最も適切なものを選ぼう。\nFirst, the writer describes the problem of food waste. Next, the writer explains its causes. Finally, the writer suggests some solutions.', choices: ['比較・対照型', '問題・原因・解決型', '時系列型', '定義・分類型'], a: 'B(問題・原因・解決型)', exp: '問題(食品ロス)→ 原因 → 解決策の順に書かれているので、問題・原因・解決型です。説明文でよく使われる型です。' }
    ]
  });

  add('el_sound', {
    pat: [
      { name: '連結・脱落で「似た音の選択肢」から選ぶ', freq: 'とてもよく出る', when: '選択肢に、音だけ聞くとよく似た語句(can / can\'t、want to / wanted to)が並んでいる問題です。', how: ['選択肢どうしで、音のちがいがどこにあるか(語尾の t・d・ed、can の強弱)を先に確かめます。', 'can は弱く「クン」、can\'t ははっきり強く読まれることが多いなど、強弱のちがいを手がかりにします。', '音だけで決めきれないときは、前後の文脈(but・so など)で意味の合うほうを選びます。'], ex: { q: '放送で次の文が流れた。話し手は泳げるか。\nI can\'t swim very well, so I\'ll stay on the beach.\n(和訳:あまり上手に泳げないから、浜辺にいるよ。)', a: '泳げない(あまり上手に泳げない)。', exp: 'can\'t の t は聞こえにくいですが、can\'t は強くはっきり読まれる点が手がかりです。さらに so I\'ll stay on the beach(だから浜辺にいる)という後ろの内容からも「泳げない」と判断できます。' } },
      { name: '弱形の機能語を文法で補う', freq: 'よく出る', when: '書き取り(ディクテーション)や空所補充で、to・for・of・and・have などの短い語が聞き取れないときです。', how: ['内容語(名詞・動詞・形容詞)ははっきり読まれるので、まずそれを書き取ります。', '機能語(前置詞・冠詞・代名詞・助動詞)は弱く短くなるので、文法から補います。', '補った語で文法的に正しい文になっているか(動詞の数・時制)を確かめます。'], ex: { q: '放送で「カップ(ア)ティー」のように聞こえた。正しい英語を書こう。\n(和訳:お茶を1杯)', a: 'a cup of tea', exp: 'of は弱形で「ア」くらいにしか聞こえず、cup の p とつながります。「1杯の〜」は a cup of 〜 という文法の知識から of を補います。' } },
      { name: '同化:となりの音と混ざった語を見分ける', freq: 'よく出る', when: 'did you・would you・meet you・last year など、t・d の後ろに you・y が来る語句が放送に入るときです。', how: ['t + y は「チュ」、d + y は「ジュ」のように混ざることを知っておきます。', '「ディジュ」「ウッジュ」「ミーチュ」と聞こえたら、did you・would you・meet you と元の語に戻します。', '戻した語で文の意味が通るかを確かめます。'], ex: { q: '放送で「ウッジュー マインド」と聞こえた。元の英語を書こう。\n(和訳:〜していただけますか)', a: 'Would you mind', exp: 'would の d と you の y が混ざって「ジュ」に変わる同化です。Would you mind 〜ing? は「〜していただけますか」というていねいな依頼の決まり文句です。' } },
      { name: '強勢の位置で意味を判断する(対比・訂正)', freq: '難関大で出る', when: '同じ文でも、どの語が強く読まれるかで意味が変わる問題や、「話し手が言いたいこと」を問う問題です。', how: ['文の中で特に強く・高く読まれた語を聞き取ります。', 'ふつうは文末の内容語が強く読まれるので、それ以外の語が強いときは「対比・訂正」の意味があると考えます。', '強く読まれた語と対立する内容(〜ではなく…)を補って意味をとります。'], ex: { q: '次の文で、【I】が強く読まれた。話し手が伝えたいことは何か。\n【I】 didn\'t take your umbrella.\n(和訳:私はあなたのかさを取っていない。)', a: '(かさを取ったのは)自分ではなく、ほかのだれかだ。', exp: 'ふつうは umbrella が強く読まれますが、主語の I が強いので「ほかの人ではなく私が」という対比になります。「私は取っていない(取ったのは別の人だ)」という意味が伝わります。' } },
      { name: '数字の聞き分け(-teen と -ty)', freq: 'とてもよく出る', when: 'thirteen / thirty、fifteen / fifty のような数字が答えになる問題です。値段・時刻・人数に多く出ます。', how: ['-teen は後ろ(teen)に強勢があり、長くはっきり「ティーン」と聞こえます。', '-ty は前に強勢があり、ty は短く弱く(「ティ」「ディ」)聞こえます。', '強勢だけで迷うときは、値段や人数として常識的かどうか、ほかの数字との計算で確かめます。'], ex: { q: '放送で次の文が流れ、for- のほうが強く聞こえた。チケットは何ドルか。\nThe ticket costs forty dollars.\n(和訳:そのチケットは40ドルだ。)', a: '40ドル', exp: 'forty は前の for- に強勢があり、-ty は短く弱く聞こえます。fourteen なら後ろの -teen が強く長く聞こえます。強勢の位置が聞き分けのいちばんの手がかりです。' } }
    ],
    more: [
      { lv: 1, q: '次の文で、連結が起こりやすい箇所を答えよう。\nPick it up.\n(和訳:それを拾って。)', a: 'Pick it(ピキッ)と it up(イラップ・イタップ)', exp: '子音で終わる語の後ろに母音で始まる語が来るとつながります。全体で「ピキラップ」のように聞こえることもあります。' },
      { lv: 1, q: '次の文で、ふつう強く読まれる語を2つ答えよう。\nI bought a new bike.\n(和訳:新しい自転車を買った。)', a: 'bought と bike(new も強めに読まれる)', exp: '動詞・名詞・形容詞などの内容語は強く、代名詞 I や冠詞 a などの機能語は弱く読まれます。' },
      { lv: 1, q: '放送で「ゲラップ」と聞こえた。元の英語として最も適切なものを選ぼう。\n(和訳:起きなさい。)', choices: ['Get up.', 'Give up.', 'Get out.', 'Go up.'], a: 'A(Get up.)', exp: 'get の t が母音にはさまれてラ行のような音になり、up とつながって「ゲラップ」と聞こえます。' },
      { lv: 1, q: '次の語句で、脱落しやすい音を答えよう。\ngood night\n(和訳:おやすみ)', a: 'good の d', exp: 'd の後ろに n が続くと、d はほとんど発音されず「グッナイ」のように聞こえます。似た音が続くとき、前の音が落ちやすくなります。' },
      { lv: 1, q: '放送で「ミーチュ」と聞こえた。元の英語を書こう。\n(和訳:あなたに会う)', a: 'meet you', exp: 'meet の t と you の y が混ざって「チュ」となる同化です。Nice to meet you. でよく聞く音です。' },
      { lv: 1, q: 'fifteen と fifty で、強く読まれる部分のちがいを答えよう。', a: 'fifteen は後ろの -teen、fifty は前の fif- が強く読まれる。', exp: '-teen は強く長く、-ty は弱く短く発音されます。この強勢のちがいが聞き分けの手がかりです。' },
      { lv: 1, q: '次の文で、弱く読まれやすい語を2つ答えよう。\nI\'m going to the station.\n(和訳:駅に行くところです。)', a: 'to と the(I\'m も弱めに読まれる)', exp: '前置詞 to や冠詞 the は機能語で、弱く短く「タ」「ザ」のように読まれます。going と station が強く読まれます。' },
      { lv: 2, q: '放送で「ワナ」と聞こえた。元の英語として最も適切なものを選ぼう。\nI ( ) go shopping.\n(和訳:買い物に行きたい。)', choices: ['want to', 'wanted', 'won\'t', 'wonder'], a: 'A(want to)', exp: 'want to は t が2つ続いて脱落・変化し、くだけた発音では「ワナ(wanna)」のように聞こえます。後ろの go(原形)とも合います。' },
      { lv: 2, q: '放送で次の文が流れた。話し手は手伝えるか。\nI can help you after lunch.\n(和訳:お昼のあとなら手伝えるよ。)', a: '手伝える(お昼のあとに)。', exp: '肯定の can は弱く「クン」と短く読まれ、after lunch が強く読まれます。can\'t なら can\'t 自体が強くはっきり読まれます。' },
      { lv: 2, q: '次の文で、同化が起こりやすい箇所と変化を答えよう。\nDid you see the movie?\n(和訳:その映画見た?)', a: 'Did you → 「ディジュ」', exp: 'did の d と you の y が混ざって「ジュ」の音になります。疑問文の最初に多く、「ディジュ」と聞こえたら Did you と考えます。' },
      { lv: 2, q: '次の文で、had の聞こえ方として最も適切なものを選ぼう。\nShe\'d already left.\n(和訳:彼女はもう出発していた。)', choices: ['had がはっきり「ハッド」と聞こえる', 'had が短縮されて \'d(ド)になり、ほとんど聞こえない', 'had が would と同じ強さで聞こえる', 'had が2回聞こえる'], a: 'B(had が短縮されて \'d(ド)になり、ほとんど聞こえない)', exp: 'She\'d は She had の短縮形で、\'d は小さく聞こえます。後ろが過去分詞 left なので had だと文法で判断します。' },
      { lv: 2, q: '放送で「ラスチア」のように聞こえた。元の英語を書こう。\n(和訳:去年)', a: 'last year', exp: 'last の t と year の y が混ざって「チ」に近い音になる同化です。t も落ちやすく、「ラスチア」「ラスイヤ」のように聞こえます。' },
      { lv: 2, q: '次の対話で、B の発言で強く読まれる語を答え、理由を説明しよう。\nA: Do you want coffee?\nB: No, I want tea.\n(和訳:A:コーヒーがほしい? B:いいえ、紅茶がほしい。)', a: 'tea。コーヒーではなく紅茶だ、と対比しているから。', exp: 'A の coffee に対して B は tea と訂正しているので、新しい情報の tea が特に強く読まれます。' },
      { lv: 2, q: '放送で次の文が流れた。会議は何時からか。\nThe meeting starts at three thirty.\n(和訳:会議は3時30分に始まる。)', a: '3時30分', exp: 'three thirty は「3時30分」です。thirty は前の thir- が強く、ty が短く弱く聞こえるので、thirteen(13)と区別できます。' },
      { lv: 2, q: '次の文を自然な速さで読むとき、起こりやすい音の変化を2つ答えよう。\nTake it easy.\n(和訳:気楽にね。)', a: 'Take it の連結(テイキッ)と、it easy の連結・変化(イリーズィー)', exp: 'take の k と it の i、it の t と easy の e がつながり、t はラ行のように変わります。全体で「テイキリーズィー」と聞こえます。' },
      { lv: 3, q: '放送で次の文が流れた。\'d は had か would か。理由も答えよう。\nI\'d like to try that.\n(和訳:それをやってみたい。)', a: 'would。後ろが like(原形)だから。', exp: '\'d の後ろが過去分詞なら had、原形なら would です。I\'d like to 〜 は I would like to 〜 で「〜したい」のていねいな言い方です。' },
      { lv: 3, q: '次の文で、【you】が強く読まれた。話し手の気持ちを答えよう。\nWhy don\'t 【you】 do it?\n(和訳:あなたがやったら?)', a: '(私やほかの人ではなく)あなたがやったらどうか、と相手に強くすすめている(押しつけている)。', exp: 'ふつうは do it のあたりが読まれますが、you が強いので「ほかの人ではなくあなたが」という対比が生まれます。少し強い言い方になります。' },
      { lv: 3, q: '放送で次の文が流れた。\'s は is か has か。理由も答えよう。\nHe\'s finished his report.\n(和訳:彼はレポートを書き終えた。)', a: 'has。後ろが過去分詞 finished で、his report という O があるから。', exp: 'He is finished(終わった・おしまいだ)という形もありますが、後ろに O(his report)があるので現在完了の has です。' },
      { lv: 3, q: '放送で「アイル」と「アイ」のどちらか聞き取れなかった。文法から判断しよう。\nI ( ) call you tomorrow.\n(和訳:明日電話するよ。)', a: 'I\'ll(I will)', exp: 'tomorrow があり未来のことなので、I call ではなく I\'ll call が自然です。\'ll は弱く短く聞こえるので、時を表す語から補います。' },
      { lv: 3, q: '次の2つの数を、聞き分ける手がかりとともに答えよう。\n(1) 強勢が前で「フォーティ」と短く終わった。\n(2) 強勢が後ろで「フォーティーン」と長く聞こえた。', a: '(1) forty(40) (2) fourteen(14)', exp: '-ty は前に強勢があり語尾が短く、-teen は後ろに強勢があり語尾が長く聞こえます。英語の強勢の位置が数字の区別に役立ちます。' }
    ]
  });

  add('el_short', {
    pat: [
      { name: '最後の発言で答えが決まる(訂正・変更)', freq: 'とてもよく出る', when: '対話の中で、一度決めたことが Actually・Wait・On second thought などで変わる問題です。', how: ['設問(何を買うか・いつ会うか)を先に読み、聞くべき点を決めておきます。', '最初に出てきた答えにすぐ飛びつかず、Actually・But・Then などの合図の後ろに注意します。', '最後に決まった内容を答えにします。'], ex: { q: '次の対話で、2人は何時に会うか。\nA: Let\'s meet at the station at ten.\nB: Ten is a little early for me. How about eleven?\nA: OK, eleven it is.\n(和訳:A:10時に駅で会おう。B:10時は少し早いな。11時はどう? A:いいよ、11時にしよう。)', a: '11時', exp: '最初に出た10時は B の都合で変更され、最後に A が eleven it is(11時で決まり)と同意しています。最初の数字にひっかからず、最後の決定を答えます。' } },
      { name: '数の計算(人数・金額・時刻)', freq: 'とてもよく出る', when: '設問が How much・How many・What time で、対話の中に複数の数字が出てくる問題です。', how: ['出てくる数字をすべてメモします。', 'half price・discount・more・late など、数字を変える語句に注意します。', '最後に設問が求めている数(合計か差か、何人分か)を計算します。'], ex: { q: '次の対話で、A はいくら払うか。\nA: How much is this cake?\nB: It\'s four dollars. But if you buy three, you get one more for free.\nA: Great. I\'ll buy three.\n(和訳:A:このケーキはいくら? B:4ドルです。でも3つ買うと、もう1つ無料になりますよ。A:いいね。3つ買います。)', a: '12ドル', exp: '1個4ドルのケーキを3つ買うので 4 × 3 = 12 ドルです。もう1つは無料なので、もらえるケーキは4つでも払う金額は変わりません。' } },
      { name: '発言の意図(断る・すすめる)を読み取る', freq: 'とてもよく出る', when: 'Yes / No ではっきり答えず、理由や別の提案だけを言っている対話で、「B はどうするか」を問う問題です。', how: ['A の質問・依頼の内容を確かめます。', 'B の答えが、その依頼に対して「できる理由」か「できない理由」かを考えます。', '理由から、B の本当の答え(引き受ける・断る・代わりの提案)を判断します。'], ex: { q: '次の対話で、B は映画に行くか。\nA: Do you want to see a movie tonight?\nB: I have a test tomorrow morning.\n(和訳:A:今夜映画を見に行かない? B:明日の朝テストがあるんだ。)', a: '行かない(断っている)。', exp: 'B は No とは言っていませんが、「明日の朝テストがある」という理由を述べています。今夜は勉強が必要なので、遠回しに断っていると考えます。' } },
      { name: '「次に何をするか」「どこでの会話か」', freq: 'よく出る', when: '設問が What will the man do next? や Where are they talking? で、場所や行動を直接言わない対話の問題です。', how: ['場所や職業を連想させる語(check in・menu・prescription など)をメモします。', '次の行動は、対話の最後の I\'ll 〜・Let me 〜・Then I\'d better 〜 に注目します。', '選択肢は、本文の語をそのまま使ったものより、内容を言いかえたものを疑わずに確かめます。'], ex: { q: '次の対話はどこでの会話か。\nA: I\'d like to send this package to Canada.\nB: By airmail or by sea?\nA: Airmail, please.\n(和訳:A:この小包をカナダに送りたいのですが。B:航空便ですか、船便ですか。A:航空便でお願いします。)', a: '郵便局', exp: 'send this package(小包を送る)、airmail・by sea(航空便・船便)という語から、郵便局での会話だと分かります。場所の名前は出てきませんが、関連する語から判断します。' } },
      { name: '会話の決まり文句は文字どおりに訳さない', freq: '難関大で出る', when: 'Tell me about it.・I couldn\'t agree more.・You can say that again. など、直訳すると意味が逆になりやすい表現が出てくる問題です。', how: ['直訳で意味が通らない、または文脈に合わない表現に気づきます。', '決まり文句として覚えている意味に置きかえます(I couldn\'t agree more. = 大賛成だ)。', '前後の発言と合うかを確かめて、話し手の気持ちを判断します。'], ex: { q: '次の対話で、B は A の意見に賛成か反対か。\nA: This restaurant is too expensive.\nB: I couldn\'t agree more.\n(和訳:A:このレストランは高すぎるよ。B:まったく同感だ。)', a: '賛成(大賛成)', exp: 'I couldn\'t agree more. は「これ以上賛成できないほど賛成だ」=「まったく同感だ」という意味です。couldn\'t という否定の形につられて「反対」と考えないようにします。' } }
    ],
    more: [
      { lv: 1, q: '次の対話で、B は何を飲むか。\nA: Would you like coffee or tea?\nB: Tea, please.\n(和訳:A:コーヒーと紅茶、どちらがいいですか。B:紅茶をお願いします。)', a: '紅茶', exp: 'A or B の質問に対して、B は Tea, please. と答えています。選択疑問文の答えは、選んだほうの語をそのまま言うことが多いです。' },
      { lv: 1, q: '次の対話で、B はかさを持っているか。\nA: It\'s going to rain. Do you have an umbrella?\nB: Yes, I always carry one in my bag.\n(和訳:A:雨が降りそうだよ。かさ持ってる? B:うん、いつもかばんに入れているよ。)', a: '持っている。', exp: 'Yes に加えて、always carry one(いつも1本持ち歩いている)と答えています。one は an umbrella を指します。' },
      { lv: 1, q: '次の対話で、2人はいつ出かけるか。\nA: Shall we go on Saturday?\nB: I\'m busy on Saturday. How about Sunday?\nA: Sure.\n(和訳:A:土曜日に行かない? B:土曜日はいそがしいんだ。日曜日はどう? A:いいよ。)', a: '日曜日', exp: '最初の Saturday は B の都合で変更され、最後に A が Sure. と同意しています。最後に決まった日を答えます。' },
      { lv: 1, q: '次の対話で、A はいくら払うか。\nA: Two tickets, please.\nB: That\'s five dollars each.\n(和訳:A:チケットを2枚ください。B:1枚5ドルです。)', a: '10ドル', exp: 'each は「それぞれ・1枚につき」です。5ドル × 2枚 = 10ドルになります。' },
      { lv: 1, q: '次の対話はどこでの会話か。\nA: Are you ready to order?\nB: Yes. I\'ll have the pasta and a salad.\n(和訳:A:ご注文はお決まりですか。B:はい。パスタとサラダをください。)', a: 'レストラン', exp: 'ready to order(注文の準備ができた)、I\'ll have 〜(〜をください)という表現から、レストランでの会話だと分かります。' },
      { lv: 1, q: '次の対話で、B の気持ちとして最も適切なものを選ぼう。\nA: I passed the exam!\nB: That\'s wonderful!\n(和訳:A:試験に合格したよ! B:すばらしいね!)', choices: ['喜んでいる', '怒っている', '心配している', 'がっかりしている'], a: 'A(喜んでいる)', exp: '合格の知らせに That\'s wonderful! と答えているので、相手のことを喜んでいます。' },
      { lv: 1, q: '次の対話で、B は窓を開けるか。\nA: It\'s hot in here. Could you open the window?\nB: Sure.\n(和訳:A:ここは暑いね。窓を開けてくれる? B:いいよ。)', a: '開ける。', exp: 'Sure. は依頼を引き受けるときの返事です。No problem.・Of course. も同じ意味で使われます。' },
      { lv: 2, q: '次の対話で、B はパーティーに来るか。\nA: Are you coming to my party on Friday?\nB: I wish I could, but I have to work late.\n(和訳:A:金曜日のパーティーに来る? B:行けたらいいんだけど、遅くまで働かなきゃいけないんだ。)', a: '来ない(行けない)。', exp: 'I wish I could は「できればいいのに(実際はできない)」という仮定法です。but I have to work late も来られない理由です。' },
      { lv: 2, q: '次の対話で、会議に来る人は何人か。\nA: Ten people said they would come to the meeting.\nB: But Ken and Mari called to say they can\'t make it.\n(和訳:A:10人が会議に来ると言っていたよ。B:でもケンとマリが、来られないと電話してきたよ。)', a: '8人', exp: '10人のうち、ケンとマリの2人が来られなくなったので 10 − 2 = 8 人です。can\'t make it は「(都合がつかず)行けない」です。' },
      { lv: 2, q: '次の対話で、男性が次にすることとして最も適切なものを選ぼう。\nW: The printer is out of paper.\nM: Oh, I\'ll get some from the storage room.\n(和訳:W:プリンターの紙が切れているわ。M:ああ、倉庫から取ってくるよ。)', choices: ['プリンターを修理する', '倉庫に紙を取りに行く', '新しいプリンターを買う', '女性に紙をたのむ'], a: 'B(倉庫に紙を取りに行く)', exp: '最後の I\'ll get some from the storage room が次の行動です。some は paper を指しています。' },
      { lv: 2, q: '次の対話で、B は A の意見に賛成か。\nA: This movie is boring.\nB: Tell me about it. I almost fell asleep.\n(和訳:A:この映画、つまらないね。B:本当にそうだよ。もう少しで寝るところだった。)', a: '賛成', exp: 'Tell me about it. は「話して」ではなく「本当にそうだね」という強い同意の決まり文句です。寝そうになったという内容とも合います。' },
      { lv: 2, q: '次の対話で、店が閉まる時刻を答えよう。\nA: What time does the store close?\nB: Usually at eight, but today it closes an hour earlier.\n(和訳:A:お店は何時に閉まりますか。B:ふだんは8時ですが、今日は1時間早く閉まります。)', a: '7時', exp: 'ふだんの8時から an hour earlier(1時間早く)なので、今日は7時に閉まります。最初の数字だけで答えないようにします。' },
      { lv: 2, q: '次の対話で、女性が言いたいことを答えよう。\nM: Should I take the bus to the museum?\nW: It\'s only a five-minute walk from here.\n(和訳:M:博物館までバスに乗るべきかな。W:ここから歩いてたった5分よ。)', a: 'バスに乗らなくても歩いて行ける(歩いたほうがいい)。', exp: '女性は Yes / No で答えず、「歩いて5分」という情報を伝えています。近いのでバスは不要だ、という意図です。' },
      { lv: 2, q: '次の対話で、2人がいる場所として最も適切なものを選ぼう。\nA: I\'d like to borrow these three books.\nB: Sure. Please return them within two weeks.\n(和訳:A:この3冊を借りたいのですが。B:どうぞ。2週間以内に返してください。)', choices: ['書店', '図書館', '郵便局', '学校の教室'], a: 'B(図書館)', exp: 'borrow(借りる)と return within two weeks(2週間以内に返す)から、図書館での会話だと分かります。書店なら buy を使います。' },
      { lv: 2, q: '次の対話で、A が払う金額を答えよう。\nA: How much is this shirt?\nB: It\'s thirty dollars, but it\'s twenty percent off today.\n(和訳:A:このシャツはいくらですか。B:30ドルですが、今日は20パーセント引きです。)', a: '24ドル', exp: '30ドルの20パーセントは 30 × 0.2 = 6 ドルです。30 − 6 = 24 ドルになります。off は「値引き」を表します。' },
      { lv: 3, q: '次の対話で、2人は最終的に何で行くか。\nA: Let\'s take a taxi to the airport.\nB: It\'s rush hour. The train would be faster.\nA: Good point. But we have heavy bags.\nB: Then let\'s take the airport bus. It stops right in front of the hotel.\nA: Perfect.\n(和訳:A:空港までタクシーで行こう。B:ラッシュアワーだよ。電車のほうが速いよ。A:たしかに。でも荷物が重いよ。B:じゃあ空港バスにしよう。ホテルのすぐ前にとまるよ。A:ばっちりだね。)', a: '空港バス', exp: 'タクシー → 電車 → 空港バスと案が変わり、最後に A が Perfect. と同意しています。条件(渋滞・重い荷物)を両方満たすのがバスです。' },
      { lv: 3, q: '次の対話で、B が来られる時刻を答えよう。\nA: Can you come to the office at two?\nB: I have a meeting until two thirty, and it takes fifteen minutes to get there.\n(和訳:A:2時に事務所に来られる? B:2時30分まで会議があって、そこまで行くのに15分かかるんだ。)', a: '2時45分(以降)', exp: '会議が終わる2時30分に、移動の15分を足すと2時45分です。B は2時には来られないことを、時刻と理由で伝えています。' },
      { lv: 3, q: '次の対話で、B の発言の意図として最も適切なものを選ぼう。\nA: Can I borrow your bike this afternoon?\nB: Ken already asked me, but he said he would be back by noon.\n(和訳:A:今日の午後、自転車を借りてもいい? B:ケンにもうたのまれているんだけど、正午までには戻ると言っていたよ。)', choices: ['自転車は貸せない', '午後なら貸せる', 'ケンに借りてほしい', '正午までなら貸せる'], a: 'B(午後なら貸せる)', exp: '先にケンが借りますが、正午までに戻るので、A が使いたい午後には空いています。遠回しに「貸せる」と伝えています。' },
      { lv: 3, q: '次の対話で、女性が次にすることを答えよう。\nM: Did you send the e-mail to the client?\nW: Not yet. I was going to, but I need to check the price list first.\nM: It\'s on my desk.\nW: Thanks. I\'ll take a look at it.\n(和訳:M:お客さんにメールを送った? W:まだよ。送るつもりだったけど、まず価格表を確認しないと。M:ぼくの机の上にあるよ。W:ありがとう。見てみるわ。)', a: '(男性の机の上にある)価格表を確認する。', exp: '最後の I\'ll take a look at it の it は価格表を指します。メールを送るのはその後なので、「次にすること」は価格表の確認です。' },
      { lv: 3, q: '次の対話で、B の気持ちとして最も適切なものを選ぼう。\nA: I\'m sorry I broke your cup.\nB: Don\'t worry about it. It was an old one anyway.\n(和訳:A:あなたのカップを割ってしまってごめんなさい。B:気にしないで。どうせ古いものだったから。)', choices: ['怒っている', '気にしていない', '悲しんでいる', 'おどろいている'], a: 'B(気にしていない)', exp: 'Don\'t worry about it. と言い、さらに「どうせ古いものだった」と相手を安心させる理由を加えているので、気にしていないことが分かります。' }
    ]
  });

  add('el_long', {
    pat: [
      { name: '講義のワークシート(表・空所)を埋める', freq: 'とてもよく出る', when: '共通テストの講義型の問題で、表やまとめの空所に入る語句・数字を選ぶときです。', how: ['放送前にワークシートの見出し・空所の位置を読み、何が話される順番かを予測します。', 'First・Second・Another・Finally などの合図ごとに、表のどの欄の話かを切りかえます。', '空所に入る語は放送では言いかえられていることが多いので、意味で照らし合わせます。'], ex: { q: '講義の一部を聞いて、ワークシートの空所に入る語句を答えよう。\n放送:There are two main causes of food waste at home. First, people buy more than they need. Second, they forget about food in the refrigerator.\n(和訳:家庭の食品ロスには主に2つの原因があります。第1に、人は必要以上に買ってしまいます。第2に、冷蔵庫の中の食べ物を忘れてしまいます。)\nワークシート:原因1 必要以上に( ① )/原因2 冷蔵庫の食品を( ② )', a: '① 買う ② 忘れる', exp: 'First・Second の合図で、原因が2つ順に述べられています。それぞれの合図の後ろの動詞(buy・forget)がワークシートの空所に対応しています。' } },
      { name: '数値と変化(増減・割合)の聞き取り', freq: 'とてもよく出る', when: 'グラフや数値を選ぶ問題で、increase・decrease・double・half・percent などの語が出てくるときです。', how: ['最初の数値(基準)をメモします。', 'rose by・fell to・doubled など、変化の語と数値を組み合わせてメモします(by は差、to は結果)。', '設問が「変化後の値」か「変化の量」かを確かめて計算します。'], ex: { q: '放送を聞いて、今年の参加者数を答えよう。\n放送:Last year, 400 people joined the event. This year, the number rose by 25 percent.\n(和訳:昨年は400人がイベントに参加しました。今年はその数が25パーセント増えました。)', a: '500人', exp: '400人の25パーセントは 400 × 0.25 = 100 人です。rose by は「〜だけ増えた」という差を表すので、400 + 100 = 500 人になります。' } },
      { name: '談話標識で話の流れと要点をつかむ', freq: 'よく出る', when: '講義やスピーチの要点・話し手の主張を問う問題で、放送が長く細部をすべて覚えられないときです。', how: ['The main point is・What I want to say is・In short などの「まとめ・強調」の合図を待ちます。', 'However・But の後ろは話し手の考えが出やすいので、特に注意して聞きます。', '具体例(For example の後ろ)は要点そのものではないことを意識して、要点の選択肢を選びます。'], ex: { q: '放送を聞いて、話し手の主張を答えよう。\n放送:Some people think online classes are not effective. However, online classes allow students in remote areas to learn from good teachers.\n(和訳:オンライン授業は効果的ではないと考える人もいます。しかし、オンライン授業によって、遠くの地域の生徒もよい先生から学ぶことができます。)', a: 'オンライン授業には、遠くの地域の生徒がよい先生から学べるという利点がある。', exp: '前半の Some people think は他人の意見で、However の後ろが話し手の主張です。逆接の合図の後ろを要点として聞き取ります。' } },
      { name: '複数の人の議論:だれがどの立場か', freq: '難関大で出る', when: '3〜4人が意見を言い合う放送で、「賛成している人を選べ」「〇〇さんの意見に合う図表を選べ」と問われるときです。', how: ['放送前に、人物の名前と議題(賛成・反対の対象)を確かめます。', '人物ごとに「賛成・反対・条件つき」と短くメモします(I agree・I\'m not sure・That\'s true, but)。', '最後に意見を変える人もいるので、議論の終わりの発言で立場を確定させます。'], ex: { q: '放送を聞いて、制服に賛成している人を答えよう。\n放送:Ken: I think school uniforms are a good idea. They save time in the morning. / Mari: I don\'t agree. Students should be free to choose. / Ann: At first I agreed with Mari, but Ken\'s point about saving time convinced me.\n(和訳:ケン:制服はよい考えだと思う。朝の時間の節約になる。/マリ:賛成できないわ。生徒は自由に選べるべきよ。/アン:最初はマリと同じ意見だったけど、時間の節約というケンの指摘に納得したわ。)', a: 'ケンとアン', exp: 'ケンは最初から賛成です。アンは最初マリと同じ反対でしたが、convinced me(納得させられた)と最後に賛成に変わりました。途中の立場ではなく最後の立場で判断します。' } },
      { name: '定義と強調の合図を聞きのがさない', freq: 'よく出る', when: '講義で専門用語が出てきて、その意味を問う問題です。is called・is known as・refers to・In other words などの合図があります。', how: ['is called 〜・is known as 〜・refers to 〜 が聞こえたら、その前後が定義だと考えます。', 'In other words・That is の後ろは、難しい内容をやさしく言いかえた部分なので、特に注意して聞きます。', '定義の内容を日本語で短くメモし、用語と結びつけます。'], ex: { q: '放送を聞いて、「フードマイレージ」とは何か日本語で答えよう。\n放送:The distance that food travels from where it is produced to where it is eaten is called “food mileage.”\n(和訳:食べ物が生産された場所から食べられる場所まで運ばれる距離は、「フードマイレージ」と呼ばれます。)', a: '食べ物が生産地から消費地まで運ばれる距離。', exp: 'is called 〜 の前の主語(The distance that 〜)が定義の内容です。主語が長いので、is called が聞こえるまでの部分をしっかり覚えておく必要があります。' } }
    ],
    more: [
      { lv: 1, q: '放送を聞いて、話し手がすすめていることを答えよう。\n放送:If you want to sleep well, you should turn off your phone an hour before bed.\n(和訳:よく眠りたいなら、寝る1時間前にスマートフォンの電源を切るべきです。)', a: '寝る1時間前にスマートフォンの電源を切ること。', exp: 'you should 〜 は助言・すすめを表します。If you want to sleep well は目的で、すすめている内容は should の後ろです。' },
      { lv: 1, q: '放送を聞いて、方法がいくつ紹介されるか答えよう。\n放送:Today I\'ll tell you three ways to stay healthy.\n(和訳:今日は健康でいるための3つの方法をお話しします。)', a: '3つ', exp: '講義の最初に three ways と数が予告されています。メモに①②③と番号を書いておくと、First・Second などの合図で整理できます。' },
      { lv: 1, q: '放送を聞いて、( ) に入る数を答えよう。\n放送:The museum has about 2,000 visitors a day.\n(和訳:その博物館には1日に約2,000人の来館者がある。)\n博物館の来館者:1日約( )人', a: '2,000', exp: 'two thousand は「2,000」です。about は「約」で、a day は「1日につき」の意味です。' },
      { lv: 1, q: '放送の For example の後ろで述べられているものは何か。\n放送:Many animals sleep during the day. For example, owls are active at night.\n(和訳:多くの動物は昼間に眠ります。たとえば、フクロウは夜に活動します。)', a: 'フクロウ(昼間眠る動物の具体例)', exp: 'For example の後ろは、前の「昼間に眠る動物」という説明の具体例です。要点は前の文です。' },
      { lv: 1, q: '放送を聞いて、話し手の意見を答えよう。\n放送:I think reading books is better than watching videos, because it helps us use our imagination.\n(和訳:想像力を使うのに役立つので、本を読むほうが動画を見るよりよいと思います。)', a: '本を読むほうが動画を見るよりよい。', exp: 'I think の後ろが意見、because の後ろがその理由(想像力を使うのに役立つ)です。意見と理由を分けてメモします。' },
      { lv: 1, q: '次の談話標識のうち、まとめ(結論)を表すものを選ぼう。', choices: ['For example', 'In conclusion', 'First', 'On the other hand'], a: 'B(In conclusion)', exp: 'In conclusion は「結論として」で、話のまとめを示す合図です。For example は具体例、First は順序、On the other hand は対比です。' },
      { lv: 1, q: '放送を聞いて、値段が上がったか下がったかを答えよう。\n放送:The price of vegetables went up last month.\n(和訳:先月、野菜の値段が上がった。)', a: '上がった。', exp: 'go up は「上がる」、go down は「下がる」です。グラフ問題では、変化の向きをまず聞き取ることが大切です。' },
      { lv: 2, q: '放送を聞いて、今年の会員数を答えよう。\n放送:Our club had 60 members last year. This year the number has doubled.\n(和訳:私たちのクラブには昨年60人の会員がいました。今年はその数が2倍になりました。)', a: '120人', exp: 'double は「2倍になる」です。60 × 2 = 120 人になります。half(半分)・triple(3倍)も覚えておきましょう。' },
      { lv: 2, q: '放送を聞いて、( ) に入る語句を答えよう。\n放送:Plants need three things to grow: sunlight, water, and air.\n(和訳:植物が育つには3つのものが必要です。日光、水、空気です。)\nワークシート:植物の成長に必要なもの ① 日光 ② 水 ③( )', a: '空気', exp: 'three things と予告され、コロンの後ろに3つが並べられています。並べられたものの最後(and の後ろ)が③にあたります。' },
      { lv: 2, q: '放送を聞いて、昨年と比べて今年の観光客がどう変わったか答えよう。\n放送:Last year, 8,000 tourists visited the town. This year, the number fell to 6,000.\n(和訳:昨年は8,000人の観光客がその町を訪れました。今年はその数が6,000人に減りました。)', a: '2,000人減った(8,000人から6,000人になった)。', exp: 'fell to 〜 は「〜まで減った」で、to の後ろは変化後の数です。8,000 − 6,000 = 2,000 人の減少です。fell by なら減った量になります。' },
      { lv: 2, q: '放送を聞いて、「リサイクル」と「リユース」のちがいを日本語で答えよう。\n放送:Recycling means turning used things into new materials. Reusing, on the other hand, means using the same things again.\n(和訳:リサイクルとは使ったものを新しい材料に変えることです。一方、リユースとは同じものを再び使うことです。)', a: 'リサイクルは使ったものを新しい材料に変えること、リユースは同じものをもう一度使うこと。', exp: 'means 〜 が定義の合図で、on the other hand が2つを対比する合図です。2つの用語を対にしてメモします。' },
      { lv: 2, q: '放送を聞いて、話し手のいちばん言いたいことを選ぼう。\n放送:Some people say that video games are a waste of time. But some games can actually help children learn problem-solving skills.\n(和訳:テレビゲームは時間のむだだと言う人もいます。しかし、ゲームの中には、子どもが問題解決の力を身につけるのに役立つものもあります。)', choices: ['ゲームは時間のむだだ。', 'ゲームの中には学びに役立つものもある。', '子どもはゲームをすべきではない。', 'ゲームはとても高い。'], a: 'B(ゲームの中には学びに役立つものもある。)', exp: 'Some people say は他人の意見で、But の後ろが話し手の主張です。actually(実は)も主張を強める語です。' },
      { lv: 2, q: '放送を聞いて、2位の国と割合を答えよう。\n放送:Most students chose Australia, at 40 percent. Canada was next with 30 percent, followed by the UK at 20 percent.\n(和訳:最も多くの生徒がオーストラリアを選び、40パーセントでした。次がカナダで30パーセント、そのあとにイギリスが20パーセントで続きました。)', a: 'カナダ、30パーセント', exp: 'was next(次だった)は2位を表します。followed by 〜(その後に〜が続く)は3位のイギリスです。順位の表現に注意します。' },
      { lv: 2, q: '講義で次の英文が聞こえた。In other words の後ろは何をしているか答えよう。\n放送:This plant is drought-resistant. In other words, it can live with very little water.\n(和訳:この植物は干ばつに強いです。言いかえると、とても少ない水でも生きられます。)', a: '前の難しい語(drought-resistant)をやさしく言いかえている。', exp: 'In other words は「言いかえると」で、難しい語や内容を分かりやすく説明し直す合図です。用語の意味はここで聞き取れます。' },
      { lv: 2, q: '放送を聞いて、イベントの開始時刻を答えよう。\n放送:The event was planned to start at one, but it will start thirty minutes later because of the rain.\n(和訳:イベントは1時に始まる予定でしたが、雨のため30分遅れて始まります。)', a: '1時30分', exp: '予定の1時から thirty minutes later(30分後)なので、1時30分です。was planned(予定だった)は変更の前ぶれになることが多い表現です。' },
      { lv: 3, q: '放送を聞いて、( ) に入る数を答えよう。\n放送:In 2010, 50 percent of the students walked to school. By 2020, this number had fallen by 10 percentage points, and another 5 points were lost by 2025.\n(和訳:2010年には生徒の50パーセントが歩いて通学していました。2020年までにその数は10ポイント下がり、2025年までにさらに5ポイント下がりました。)\n2025年の徒歩通学の割合:( )パーセント', a: '35', exp: '50 − 10 = 40(2020年)、さらに 40 − 5 = 35(2025年)です。percentage points は割合の「ポイント」の差を表すので、そのまま引き算します。' },
      { lv: 3, q: '放送を聞いて、最後に計画に賛成している人をすべて答えよう。\n放送:Tom: I support the plan to plant more trees in the park. / Lisa: It costs too much. I\'m against it. / Ben: I agree with Tom. / Lisa: Well, if the city pays half, I could support it. / Tom: The city has already agreed to that.\n(和訳:トム:公園にもっと木を植える計画を支持するよ。/リサ:お金がかかりすぎるわ。反対よ。/ベン:トムに賛成だ。/リサ:まあ、市が半分払うなら支持できるかも。/トム:市はもうそれに同意しているよ。)', a: 'トム・ベン・リサ(3人全員)', exp: 'リサは最初反対でしたが、「市が半分払うなら」という条件つきで賛成に変わり、トムがその条件はすでに満たされていると伝えています。最後の立場で判断します。' },
      { lv: 3, q: '放送を聞いて、講義の要点として最も適切なものを選ぼう。\n放送:Many people believe that bees are important only because they make honey. In fact, their greatest role is carrying pollen between flowers, which helps many crops grow.\n(和訳:多くの人は、ハチははちみつを作るから大切なのだと思っています。実は、ハチの最も大きな役割は花から花へ花粉を運ぶことで、それが多くの作物の成長を助けています。)', choices: ['ハチははちみつを作る。', 'ハチの最大の役割は花粉を運び、作物の成長を助けることだ。', '多くの人はハチがこわい。', '作物は花粉がなくても育つ。'], a: 'B(ハチの最大の役割は花粉を運び、作物の成長を助けることだ。)', exp: 'Many people believe は一般の考えで、In fact(実は)の後ろが要点です。A は一般の考えの一部で、要点ではありません。' },
      { lv: 3, q: '放送を聞いて、ワークシートの空所に入る語句を答えよう。\n放送:The heat island effect has two main causes. One is that buildings and roads absorb heat. The other is that there are fewer trees in cities.\n(和訳:ヒートアイランド現象には主な原因が2つあります。1つは建物や道路が熱を吸収することです。もう1つは、都市には木が少ないことです。)\nワークシート:原因① 建物や道路が熱を( )/原因② 都市の( )が少ない', a: '吸収する/木', exp: 'One is 〜. The other is 〜. で2つの原因が順に述べられています。absorb は「吸収する」です。2つしかないとき、2つ目は the other で示されます。' },
      { lv: 3, q: '放送を聞いて、来月のバスの料金を答えよう。\n放送:The bus fare is currently 200 yen. Next month, it will increase by 10 percent, but students will get a 50-yen discount.\n(和訳:現在バスの料金は200円です。来月10パーセント値上がりしますが、学生は50円の割引を受けられます。)\n(1) 一般の料金 (2) 学生の料金', a: '(1) 220円 (2) 170円', exp: '200円の10パーセントは20円なので、一般は 200 + 20 = 220 円です。学生はそこから50円引きなので 220 − 50 = 170 円になります。' }
    ]
  });

  add('el_strategy', {
    pat: [
      { name: '設問の先読みで「聞くべき点」をしぼる', freq: 'とてもよく出る', when: '放送が始まる前に設問と選択肢を読む時間があるすべての問題です。特に選択肢が数字・場所・人物のときに効果があります。', how: ['設問の疑問詞(What・When・Why・How much)に印をつけ、何を聞きとるかを決めます。', '選択肢どうしのちがい(数字・曜日・人物)を確かめ、そこだけに集中できるようにします。', '放送の場面(学校・店・駅)を予測し、出てきそうな語を頭に入れておきます。'], ex: { q: '設問「Why is the man late?」を先読みしたとき、放送で特に何に注意して聞けばよいか。', a: '男性が遅れた「理由」(because・since・so の前後や、電車の遅れ・寝坊など)。', exp: '疑問詞が Why なので、理由を聞き取ることが目標です。because のような接続詞だけでなく、The train was delayed. のように理由だけを述べる文にも注意します。' } },
      { name: '1回読みの即決と切りかえ', freq: 'とてもよく出る', when: '放送が1回しか流れない問題(共通テストの後半など)で、聞きのがした設問があるときです。', how: ['放送中に、選択肢の横に○×や数字を書きこみながら聞きます。', '放送が終わったらすぐに答えを決め、迷った問題にこだわらないようにします。', '次の問題の先読みに時間を使い、1問の失敗を次に持ちこまないようにします。'], ex: { q: '1回読みの問題で、1問目の答えに迷っているうちに、2問目の放送が始まってしまった。どうするべきか。', a: '1問目は直感で(書きこみを見て)すぐに答えを決め、2問目の放送に集中する。', exp: '1回読みでは聞き直しができないので、迷い続けると次の問題まで聞きのがします。1問の失点で止めて、次の問題で得点することを優先します。' } },
      { name: '言いかえ(パラフレーズ)された正解を選ぶ', freq: 'とてもよく出る', when: '放送の語と同じ語が選択肢にほとんどなく、正解が別の表現で書かれている問題です。', how: ['放送の内容を、細かい語ではなく「意味」で覚えます。', '選択肢の中から、その意味を別の語で表したものを探します(sold out → no more left)。', '放送と同じ語が多い選択肢は、意味の一部がずれたひっかけではないかを確かめます。'], ex: { q: '放送:The concert was canceled because the singer got sick.\n(和訳:歌手が病気になったので、コンサートは中止された。)\n放送の内容に合うものを選ぼう。\n① The singer canceled her trip. ② The concert did not take place. ③ The concert was held later. ④ The singer was healthy.', a: '②(The concert did not take place.)', exp: 'was canceled(中止された)を did not take place(開かれなかった)と言いかえています。①は放送と同じ canceled を使っていますが、中止されたのは旅行ではないのでひっかけです。' } },
      { name: 'ひっかけの選択肢の型を見分ける', freq: 'よく出る', when: '放送に出てきた語や数字をそのまま使った選択肢が複数あり、どれも正しく見える問題です。', how: ['「言いすぎ」(Most → All、often → always)になっていないかを確かめます。', '「主語・時のすりかえ」(男性がしたことを女性にする、過去を未来にする)になっていないかを確かめます。', '「途中の情報」(最初の予定・訂正前の数字)を答えにしていないかを確かめます。'], ex: { q: '放送:Many of my classmates walk to school.\n(和訳:私のクラスメートの多くは歩いて通学している。)\n選択肢:All of the speaker\'s classmates walk to school.\nこの選択肢が誤りである理由を答えよう。', a: '放送は Many(多く)なのに、選択肢は All(全員)と言いすぎているから。', exp: '数量の語を強めた「言いすぎ」のひっかけです。walk to school などの語は放送と同じなので正解に見えますが、Many と All のちがいで意味がずれています。' } },
      { name: '案内放送の「変更」をとらえる', freq: 'よく出る', when: '駅・空港・学校行事などの案内放送で、時刻・場所・番線の変更が述べられる問題です。', how: ['has been changed・instead・due to・will now などの変更の合図を待ちます。', '変更前と変更後の情報を矢印でメモします(Gate 5 → Gate 8)。', '設問が変更後の情報を求めていることが多いので、最後の情報を答えにします。'], ex: { q: '放送を聞いて、乗客が向かうべきゲートを答えよう。\n放送:Attention, please. Flight 302 to Sydney will now depart from Gate 12 instead of Gate 7.\n(和訳:お知らせします。シドニー行き302便は、7番ゲートではなく12番ゲートからの出発になります。)', a: '12番ゲート', exp: 'will now(これからは)と instead of(〜の代わりに)が変更の合図です。instead of の後ろの Gate 7 は変更前の情報なので、答えは12番ゲートです。' } }
    ],
    more: [
      { lv: 1, q: '設問「Where will they meet?」を先読みしたとき、放送で何を聞き取ればよいか。', a: '2人が会う「場所」', exp: '疑問詞 Where は場所をたずねています。in front of 〜・at 〜 など、場所を表す前置詞の後ろに注意して聞きます。' },
      { lv: 1, q: '放送で次の英文が流れた。同じ意味を表すものを選ぼう。\n放送:The shop is closed today.\n(和訳:その店は今日は閉まっている。)', choices: ['The shop is not open today.', 'The shop is near here.', 'The shop opened today.', 'The shop is very large.'], a: 'A(The shop is not open today.)', exp: 'closed(閉まっている)を not open(開いていない)と言いかえています。反対の意味の語を否定する言いかえはよく使われます。' },
      { lv: 1, q: '2回読みの問題で、1回目の放送で最もすべきことを選ぼう。', choices: ['すべての語を書き取る', '全体の流れと答えの見当をつける', '何もせずに聞く', '次の問題を読む'], a: 'B(全体の流れと答えの見当をつける)', exp: '1回目で全体をつかみ答えの候補をしぼり、2回目で細部を確かめるのが2回読みの基本です。' },
      { lv: 1, q: '設問「How many people will come?」を先読みした。放送で特に注意すべきものを答えよう。', a: '人数を表す数字と、人数が増えたり減ったりする情報。', exp: 'How many は数をたずねています。数字そのものだけでなく、can\'t come・more people などの変化にも注意します。' },
      { lv: 1, q: '放送で次の英文が流れた。同じ意味を表す英文を選ぼう。\n放送:I\'m going to take the train.\n(和訳:電車で行くつもりだ。)', choices: ['I\'ll go by train.', 'I\'ll go by car.', 'I missed the train.', 'I\'m on the train now.'], a: 'A(I\'ll go by train.)', exp: 'take the train(電車に乗る)を go by train(電車で行く)と言いかえています。by + 乗り物は「〜で」の意味です。' },
      { lv: 1, q: '1回読みの問題で、聞きのがした部分があったときの正しい対応を選ぼう。', choices: ['放送が終わるまで同じ問題を考え続ける', '聞き取れた部分から答えを決め、次の問題に移る', '解答を空らんにして帰る', '前の問題にもどる'], a: 'B(聞き取れた部分から答えを決め、次の問題に移る)', exp: '1回読みでは聞き直しができません。聞き取れた情報で判断して答えを決め、次の問題の先読みに切りかえることが大切です。' },
      { lv: 1, q: '放送で次の英文が流れた。同じ意味を表すものを選ぼう。\n放送:I forgot my homework.\n(和訳:宿題を忘れた。)', choices: ['I didn\'t bring my homework.', 'I finished my homework.', 'I like homework.', 'I gave my homework to the teacher.'], a: 'A(I didn\'t bring my homework.)', exp: 'forgot my homework(宿題を忘れた)を didn\'t bring(持ってこなかった)と言いかえています。' },
      { lv: 2, q: '放送の内容に合わない選択肢と、そのひっかけの型を答えよう。\n放送:I sometimes eat breakfast at a cafe.\n(和訳:私はときどきカフェで朝食を食べる。)\n選択肢:The speaker always eats breakfast at a cafe.', a: '合わない。sometimes(ときどき)を always(いつも)にした「言いすぎ」の型。', exp: '頻度を表す副詞を強めたひっかけです。eat breakfast at a cafe という語句は放送と同じなので、頻度の語を必ず確かめます。' },
      { lv: 2, q: '放送を聞いて、会議の場所を答えよう。\n放送:Today\'s meeting will be held in Room 3, not in Room 5 as planned.\n(和訳:本日の会議は、予定されていた5号室ではなく、3号室で開かれます。)', a: '3号室', exp: 'not in Room 5 as planned は「予定されていた5号室ではなく」という変更前の情報です。会議は Room 3 で開かれます。' },
      { lv: 2, q: '放送で次の英文が流れた。正解の選択肢ではどの部分がどう言いかえられているか答えよう。\n放送:Tickets are free for children under six.\n(和訳:6歳未満の子どもはチケットが無料です。)\n正解:Young children don\'t have to pay.', a: 'free → don\'t have to pay、children under six → young children', exp: 'free(無料の)を「払う必要がない」と、under six(6歳未満)を「幼い子ども」と言いかえています。複数の部分が同時に言いかえられることもあります。' },
      { lv: 2, q: '放送の内容に合わない選択肢と、そのひっかけの型を答えよう。\n放送:My sister wanted to study abroad, but she decided to stay in Japan.\n(和訳:姉は留学したかったが、日本に残ることにした。)\n選択肢:The speaker\'s sister will study abroad.', a: '合わない。最初の希望(留学)を答えにした「途中の情報」の型。', exp: 'wanted to study abroad は希望で、but の後ろの decided to stay in Japan が最終的な決定です。途中の情報にひっかからないようにします。' },
      { lv: 2, q: '設問と選択肢を先読みしたとき、選択肢が次のようになっていた。放送で何に注意して聞けばよいか。\n設問:What time will the train leave?\n① 7:15 ② 7:30 ③ 7:45 ④ 8:00', a: '出発時刻(特に分の部分)と、遅れ・変更の情報。', exp: '選択肢のちがいは「分」なので、fifteen・thirty・forty-five などを聞き分けます。delayed・changed などの変更の語にも注意します。' },
      { lv: 2, q: '放送を聞いて、話し手が買ったものを選ぼう。\n放送:I was going to buy a red sweater, but they only had it in small. So I got a blue one instead.\n(和訳:赤いセーターを買うつもりだったが、Sサイズしかなかった。だから代わりに青いのを買った。)', choices: ['赤いセーター(S)', '赤いセーター(M)', '青いセーター', '何も買わなかった'], a: 'C(青いセーター)', exp: 'was going to(〜するつもりだった)は実現しなかった予定で、instead(代わりに)の前の a blue one が実際に買ったものです。' },
      { lv: 2, q: '前から意味をとりながら読み、問いに答えよう。\nThe boy / who is talking / with the teacher / is my cousin.\n問:私のいとこはだれか。', a: '先生と話している少年', exp: 'The boy の後ろの who is talking with the teacher が説明のかたまりで、文の動詞は is です。かたまりごとに前から意味をとると、返り読みせずに理解できます。' },
      { lv: 2, q: '放送で次の英文が流れた。同じ意味を表すものを選ぼう。\n放送:The museum is within walking distance of the station.\n(和訳:博物館は駅から歩いて行ける距離にある。)', choices: ['You can walk to the museum from the station.', 'The museum is far from the station.', 'You need a bus to get to the museum.', 'The museum is inside the station.'], a: 'A(You can walk to the museum from the station.)', exp: 'within walking distance(歩いて行ける距離に)を You can walk to 〜 と言いかえています。' },
      { lv: 3, q: '放送を聞いて、乗客がすべきことを答えよう。\n放送:Due to heavy snow, the 9:10 express train has been canceled. Passengers should take the 9:30 local train from Platform 4 instead.\n(和訳:大雪のため、9時10分発の急行は運休となりました。乗客の皆様は、代わりに4番線から9時30分発の普通列車にお乗りください。)', a: '4番線から9時30分発の普通列車に乗る。', exp: 'Due to(〜のため)と has been canceled で変更が告げられ、instead(代わりに)の前が新しい情報です。時刻・番線・列車の種類をセットで聞き取ります。' },
      { lv: 3, q: '放送の内容に合わない選択肢と、そのひっかけの型を答えよう。\n放送:Ken lent Mari his dictionary yesterday.\n(和訳:ケンは昨日マリに辞書を貸した。)\n選択肢:Mari lent Ken her dictionary.', a: '合わない。貸した人と借りた人を入れかえた「主語のすりかえ」の型。', exp: 'lent・dictionary など同じ語を使っていますが、だれがだれに貸したかが逆になっています。人物が2人出てくる問題では、主語と目的語の関係を確かめます。' },
      { lv: 3, q: '放送を聞いて、正しいものを選ぼう。\n放送:The festival, which usually takes place in July, will be held in August this year because of the stadium repairs.\n(和訳:ふだんは7月に開かれる祭りが、今年はスタジアムの修理のため8月に開かれます。)', choices: ['祭りは今年も7月に開かれる。', '今年は修理のため8月に開かれる。', '祭りは中止になった。', 'スタジアムは修理が終わった。'], a: 'B(今年は修理のため8月に開かれる。)', exp: 'which usually takes place in July はふだんの情報で、this year の内容が変更後の情報です。because of 〜 は変更の理由です。' },
      { lv: 3, q: '放送を聞いて、話し手の考えに最も近いものを選ぼう。\n放送:It\'s true that living in a big city is expensive. Still, I\'d rather live there, because there are more chances to meet new people.\n(和訳:たしかに大都市に住むのはお金がかかる。それでも、新しい人と出会う機会が多いので、私はそこに住みたい。)', choices: ['大都市は高すぎるので住みたくない。', '費用はかかるが、出会いが多いので大都市に住みたい。', 'いなかのほうが出会いが多い。', 'どこに住んでも同じだ。'], a: 'B(費用はかかるが、出会いが多いので大都市に住みたい。)', exp: 'It\'s true that 〜 は譲歩で、Still(それでも)の後ろが話し手の考えです。I\'d rather は「むしろ〜したい」です。' },
      { lv: 3, q: '前から意味をとりながら読み、問いに答えよう。\nThe report / the students wrote / about the river / won / a prize / at the city contest.\n問:賞をとったのは何か。また、どこで賞をとったか。', a: '生徒たちが川について書いたレポート。市のコンテストで。', exp: 'The report の後ろの the students wrote about the river が関係詞の省略された説明部分で、文の動詞は won です。名詞の後ろに S V が続いたら説明のかたまりと考えます。' }
    ]
  });

  add('ek_eiken', {
    pat: [
      { name: 'CEFR の段階から必要な英検の級を判断する', freq: 'とてもよく出る', when: '要項(例)に「CEFR B1 以上」「A2 以上」のように段階だけが書かれていて、英検ならどの級が目安かを問われるときです。', how: ['英検の級と CEFR の対応(目安)を思い出します:3級 A1、準2級 A2、2級 B1、準1級 B2、1級 C1。', '要項の段階に対応する級を選びます(B1 以上 → 2級程度以上)。', '実際の判定は CSE スコアで示される段階によることがあるので、最後は要項で確かめると考えます。'], ex: { q: '要項(例)に「CEFR B2 以上の英語力を有する者」とある。英検の級では、どの級が目安になるか。', a: '準1級(以上)', exp: '目安の対応では、2級が B1、準1級が B2 です。B2 以上なので準1級程度以上が目安になります。ただし同じ級でも CSE スコアで段階が変わることがあるので、要項の書き方を確かめます。' } },
      { name: '活用方式の判別(出願資格・得点換算・加点)', freq: 'よく出る', when: '要項(例)の文から、資格・検定試験がどの方法で使われているかを答える問題です。', how: ['「〜を有する者」「出願できる」なら出願資格と考えます。', '「〜点とみなす」「満点として扱う」なら得点換算(みなし満点)と考えます。', '「〜点を加える」なら加点と考えます。英語の試験の点数を置きかえるのか、足すのかで区別します。'], ex: { q: '次の要項(例)は、どの活用方式にあたるか。\n「英検2級合格者は、本学の英語の試験を80点とみなす。」', a: '得点換算', exp: '英検2級という結果を、英語の試験の80点に置きかえています。点数を足すのではなく置きかえているので、加点ではなく得点換算です。満点にするなら「みなし満点」と呼ばれます。' } },
      { name: '有効期限の計算', freq: 'とてもよく出る', when: '要項(例)に「出願年度の2年前の4月1日以降に受験したもの」のような期限があり、ある受験結果が使えるかを判断する問題です。', how: ['出願する月から「出願年度」を決めます(4月〜翌年3月が1つの年度)。', '条件の基準日(〜年前の4月1日)を計算します。', '受験した日が基準日以降かどうかを比べます。'], ex: { q: '要項(例):「出願年度の2年前の4月1日以降に受験した結果を有効とする。」\nC さんは2028年1月に出願する。英検2級に合格したのは2025年11月である。結果は使えるか。', a: '使える。', exp: '2028年1月は2027年度(2027年4月〜2028年3月)です。その2年前は2025年度なので、基準日は2025年4月1日です。2025年11月の受験は基準日以降なので有効です。' } },
      { name: 'どの方式が有利かを比べる', freq: '難関大で出る', when: '1つの大学に複数の入試方式(例)があり、ある受験生の英検の結果や得意不得意から、有利な方式を選ぶ問題です。', how: ['受験生の持っている級・スコアと、英語の試験の予想得点を整理します。', '方式ごとに、英語の点数がいくらになるか(換算・加点の結果)を計算します。', '合計点・出願資格の有無を比べて、有利な方式を選びます。'], ex: { q: '方式A:英検2級合格者は英語を70点とみなす(100点満点)。方式B:英語の試験を受け、英検2級合格者には5点を加える。\nD さんは英検2級に合格しており、英語の試験では60点くらいとれる見こみである。英語の点数が高くなるのはどちらの方式か。', a: '方式A(70点。方式Bは 60 + 5 = 65点)', exp: '方式Aでは英検2級で英語が70点に置きかえられます。方式Bでは試験の60点に5点を加えて65点です。70 > 65 なので、英語の点数は方式Aのほうが高くなります。' } },
      { name: '一次・二次試験と CSE スコアのしくみ', freq: 'よく出る', when: '英検の試験の流れ(一次・二次)や、合否と CSE スコアの関係、技能ごとの課題を問われるときです。', how: ['従来型の3級以上は、一次(リーディング・リスニング・ライティング)と二次(面接によるスピーキング)に分かれることを確かめます。', '合否は4技能の CSE スコアをもとに判定されることを思い出します。', '技能ごとのスコアを見て、伸ばすべき技能を決めると考えます。'], ex: { q: '英検の CSE スコアについて正しいものを選ぼう。\n① 合格・不合格だけを表す。② 級をまたいで比べられるように作られている。③ リーディングだけを測る。④ 二次試験の結果だけで決まる。', a: '②', exp: 'CSE スコアは4技能の力を共通のものさしで表したもので、級をまたいで比べられるように作られています。合否もこのスコアをもとに判定されます。①③④はいずれも誤りです。' } }
    ],
    more: [
      { lv: 1, q: '英検の級を、レベルの目安が低い順に並べよう。\n2級・3級・準1級・準2級', a: '3級 → 準2級 → 2級 → 準1級', exp: '3級は中学卒業程度、準2級は高校中級程度、2級は高校卒業程度、準1級は大学中級程度が目安です。' },
      { lv: 1, q: 'CEFR の段階を、低い順に並べよう。\nB2・A1・C1・B1・A2・C2', a: 'A1 → A2 → B1 → B2 → C1 → C2', exp: 'CEFR は6段階で、A は基礎段階、B は自立した使い手、C は熟達した使い手です。A1 がいちばん基礎、C2 がいちばん上です。' },
      { lv: 1, q: '英検で「高校卒業程度」とされる級を選ぼう。', choices: ['3級', '準2級', '2級', '準1級'], a: 'C(2級)', exp: '2級は高校卒業程度が目安で、大学入試でもよく基準として使われる級です。準2級は高校中級程度です。' },
      { lv: 1, q: '英検の二次試験で測られる技能を答えよう。', a: 'スピーキング(面接)', exp: '従来型の3級以上では、一次試験の合格者が二次試験を受け、面接によるスピーキングを測ります。' },
      { lv: 1, q: '目安として、CEFR の A2 に対応する英検の級を選ぼう。', choices: ['3級', '準2級', '2級', '準1級'], a: 'B(準2級)', exp: '目安の対応は、3級 A1、準2級 A2、2級 B1、準1級 B2、1級 C1 です。' },
      { lv: 1, q: 'CEFR は、英語の力を主に何によって説明しているか。', a: 'そのことばを使って「何ができるか」(can-do)', exp: 'CEFR は点数ではなく、身近な話題について話せる・要点を理解できる、のような「できること」で段階を説明しています。' },
      { lv: 1, q: '要項(例)「英検準2級以上を取得している者に限り出願できる」は、どの活用方式にあたるか。', a: '出願資格', exp: '級がなければそもそも出願できないので、出願資格です。得点の置きかえや加点ではありません。' },
      { lv: 2, q: '要項(例)「英検の級に応じて、合計点に最大20点を加える」は、どの活用方式にあたるか。', a: '加点', exp: '英語の試験の点数はそのままで、級に応じて合計点に点数を足しているので加点です。置きかえる得点換算とは区別します。' },
      { lv: 2, q: '要項(例)に「CEFR B1 以上」とある。英検2級に合格している E さんについて、最も適切な考え方を選ぼう。', choices: ['2級は B1 が目安なので、条件を満たす可能性が高いが、要項の判定方法を確かめる', '2級は A1 なので満たさない', 'CEFR と英検は関係がないので判断できない', '必ず準1級が必要である'], a: 'A(2級は B1 が目安なので、条件を満たす可能性が高いが、要項の判定方法を確かめる)', exp: '2級は B1 が目安です。ただし CSE スコアで段階が示されることもあるので、最後は要項の判定方法を確かめます。' },
      { lv: 2, q: '要項(例):「出願年度の2年前の4月1日以降に受験した結果を有効とする。」\nF さんは2027年10月に出願する。2025年3月に受けた英検の結果は使えるか。', a: '使えない。', exp: '2027年10月は2027年度で、2年前は2025年度、基準日は2025年4月1日です。2025年3月はその前なので有効期限外です。' },
      { lv: 2, q: '2025年度から設けられた、準2級と2級の間の級の名前を答えよう。', a: '準2級プラス', exp: '準2級(高校中級程度)と2級(高校卒業程度)の差が大きかったため、その間に準2級プラスが設けられました。' },
      { lv: 2, q: '英検の CSE スコアを見て、リーディングは高いがライティングが低いと分かった。次の学習で優先すべきことを選ぼう。', choices: ['単語帳だけをくり返す', '英作文を書いて添削を受ける', 'リーディングの問題だけを解く', '何もしない'], a: 'B(英作文を書いて添削を受ける)', exp: 'CSE スコアは技能ごとに出るので、低い技能を重点的に伸ばせます。ライティングは自分で書き、他人に見てもらうことで伸びます。' },
      { lv: 2, q: 'コンピューターを使って4技能を1日で受ける英検の方式の名前を答えよう。', a: '英検S-CBT', exp: '英検S-CBT は、リーディング・リスニング・ライティング・スピーキングを1日で受ける方式です。受験方式の指定がある要項もあるので確かめます。' },
      { lv: 2, q: '要項で必ず確かめるべき点として、適切でないものを選ぼう。', choices: ['使える試験の種類', '必要な級やスコア', '有効期限', 'その試験の会場の広さ'], a: 'D(その試験の会場の広さ)', exp: '要項では、使える試験の種類・必要なレベル・有効期限・提出方法と締め切りを確かめます。会場の広さは関係ありません。' },
      { lv: 2, q: '出願の締め切りが12月10日で、英検の結果が出るまでに約1か月かかるとする。受験の計画として最も適切な考え方を答えよう。', a: '締め切りから逆算し、結果が締め切りに間に合うよう、遅くとも11月上旬までには受験を終えておく(余裕をもって、さらに前の回を受ける)。', exp: '結果が出るまで時間がかかるので、締め切りの直前に受けると間に合いません。締め切りから結果が出るまでの期間を引いて、受験日を決めます。' },
      { lv: 3, q: '方式A:英検準1級で英語を満点(100点)とみなす。英検2級なら80点とみなす。\n方式B:英語の試験を受け、英検の級に応じて準1級なら15点、2級なら10点を加える(英語は100点満点、加点後の上限も100点とする)。\nG さんは英検2級で、英語の試験では75点くらいとれる。英語の点数が高くなる方式を答えよう。', a: '方式B(75 + 10 = 85点。方式Aは80点)', exp: '方式Aでは2級なので80点に置きかえられます。方式Bは 75 + 10 = 85 点で上限100点以内です。85 > 80 なので方式Bです。' },
      { lv: 3, q: '前の問題と同じ方式で、H さんは英検準1級を持ち、英語の試験では90点くらいとれる。英語の点数が高くなる方式を答えよう。', a: 'どちらも100点で同じ(方式Aなら試験の出来に関係なく100点が確定する)。', exp: '方式Aは準1級で100点、方式Bは 90 + 15 = 105 点ですが上限が100点です。同点ですが、方式Bは試験で失敗すると下がるので、方式Aのほうが確実です。' },
      { lv: 3, q: '「英検2級に合格した人は、全員 CEFR B1 と判定される」という考えは正しいか。理由も答えよう。', a: '正しいとは限らない。CEFR の段階は CSE スコアで示されるので、同じ級の合格者でもスコアによって段階がちがうことがあるから。', exp: '級と CEFR の対応はあくまで目安です。要項が CEFR の段階を基準にしているときは、自分の CSE スコアで示される段階を確かめます。' },
      { lv: 3, q: '要項(例):「出願年度の2年前の4月1日以降に受験し、CEFR B1 以上の結果を有するもの。」\nI さんは2027年12月に出願する。英検は2025年5月に2級(B1 と判定)、2024年7月に準1級(B2 と判定)を受けた。使える結果をすべて答えよう。', a: '2025年5月の2級の結果だけ。', exp: '2027年12月は2027年度で、基準日は2025年4月1日です。2024年7月の準1級は期限より前なので使えません。2025年5月の2級(B1)は期限内で、レベルの条件も満たしています。' },
      { lv: 3, q: '同じ大学の「経済学部では英検2級以上で出願可、文学部では英検の級に応じて加点」という要項(例)を読んだ J さんが、「この大学では英検は加点に使われる」とまとめた。このまとめの問題点を答えよう。', a: '学部によって活用方式がちがうのに、一つの方式だと一般化している点。', exp: '同じ大学でも学部や入試方式ごとに扱いがちがうことがよくあります。志望する学部・方式ごとに要項で確かめることが大切です。' }
    ]
  });

  add('ek_writing', {
    pat: [
      { name: '意見論述:I → B → C の型で書く', freq: 'とてもよく出る', when: '「〜に賛成か反対か」「〜についてあなたの意見を書け」という自由英作文で、語数の指定(80〜100語など)があるときです。', how: ['Introduction:問いにはっきり答える1文(I think 〜. / I agree that 〜.)を書きます。', 'Body:理由を2つ、それぞれ具体例や説明をつけて書きます(First, 〜. Second, 〜.)。', 'Conclusion:最初の意見を別の言い方でくり返して締めくくります(For these reasons, 〜.)。'], ex: { q: '次のテーマについて、Introduction の1文を英語で書こう。\nテーマ:Should students wear school uniforms?(制服に賛成の立場で)', a: 'I think students should wear school uniforms.', exp: '最初の1文で、問いの表現(should wear school uniforms)を使って立場をはっきり示します。I think のあとに問いをそのまま肯定の文で書くと、採点者にも立場がすぐ伝わります。' } },
      { name: '理由を具体例で支える', freq: 'とてもよく出る', when: 'Body の理由が「便利だから」「よいから」のように抽象的で、説得力が足りないときです。', how: ['理由を1文で書きます(First, uniforms save time.)。', 'その理由が成り立つ具体的な場面や例を1〜2文加えます(For example, 〜.)。', '抽象的な形容詞(good・bad)だけで終わらず、だれにとって・どのように、を書きます。'], ex: { q: '次の理由に、具体例を1文加えよう。\nFirst, reading books helps us learn new words.', a: 'For example, when I read a novel, I often find words that I have never seen before.', exp: '「新しい単語を学べる」という理由を、小説を読むと見たことのない単語に出会う、という具体的な場面で支えています。For example で始めると、理由と例の関係がはっきりします。' } },
      { name: '要約:具体例を省き、言いかえてまとめる', freq: 'よく出る', when: '英文を読んで、指定の語数で内容をまとめる要約問題です。', how: ['各段落の要点(トピックセンテンス)を1つずつ見つけます。', '具体例・数字・くり返しは省き、要点だけを残します。', '本文の文をそのまま写さず、自分のことばで言いかえ、つなぎの語(However・As a result)で論理の流れを示します。'], ex: { q: '次の英文を、1文で要約しよう。\nMany schools now use tablets. Students can search for information quickly. Teachers can share materials easily. For example, a teacher can send a video to all students at once.', a: 'Tablets help both students and teachers in school.(などのように、利点を一般化してまとめる)', exp: '生徒は情報をすばやく調べられ、先生は教材を共有しやすい、という2つの利点を「生徒と先生の両方に役立つ」とまとめます。For example 以下の具体例は要約では省きます。' } },
      { name: '和文英訳:日本語を英語にしやすい形に直す', freq: 'とてもよく出る', when: '「〜とは限らない」「〜するようになった」「〜するのに…かかる」など、直訳しにくい日本語をふくむ和文英訳です。', how: ['日本語の文の主語と述語を確かめ、英語で書ける形に言いかえます(「〜するようになった」→ come to do / start to do)。', '決まった英語の型を当てはめます(〜とは限らない → not always / not necessarily)。', '書いたあと、時制・主語と動詞の一致・冠詞を見直します。'], ex: { q: '英訳しよう。\n「高い物が良い物だとは限らない。」', a: 'Expensive things are not always good.(Expensive things are not necessarily good.)', exp: '「〜とは限らない」は部分否定の not always・not necessarily で表します。Expensive things are not good. とすると「高い物は良くない」という全体否定になってしまいます。' } },
      { name: '言いすぎを避ける表現(ヘッジ)', freq: '難関大で出る', when: '意見論述で all・always・never などの強い語を使いがちで、主張が言いすぎになっているときです。', how: ['自分の文の中の all・everyone・always・never に印をつけます。', '例外がありうる内容なら、many・most・often・tend to・can などに言いかえます。', '主張の強さを調整しても、立場そのものはぶれないように確かめます。'], ex: { q: '言いすぎにならないように書き直そう。\nAll young people use social media too much.', a: 'Many young people tend to use social media too much.(などのように、many・tend to で弱める)', exp: 'All(すべての)は例外を認めないので、採点者に反論されやすい主張です。many と tend to(〜する傾向がある)を使うと、言いたいことを保ったまま説得力が上がります。' } }
    ],
    more: [
      { lv: 1, q: '意見論述の Conclusion で使う書き出しとして最も適切なものを選ぼう。', choices: ['For example,', 'For these reasons,', 'First,', 'However,'], a: 'B(For these reasons,)', exp: 'For these reasons(これらの理由から)は、Body の理由をまとめて最初の意見をくり返すときの書き出しです。' },
      { lv: 1, q: '英訳しよう。\n「私はこの意見に賛成です。」', a: 'I agree with this opinion.', exp: 'agree with + 意見・人 で「〜に賛成する」。立場を示す Introduction でよく使う1文です。反対なら I disagree with this opinion. です。' },
      { lv: 1, q: '誤りを直そう。\nMy brother like soccer very much.', a: 'like → likes', exp: '主語が3人称単数(My brother)で現在の文なので、動詞に s をつけます。英作文の減点でとても多いミスです。' },
      { lv: 1, q: '理由を2つ挙げるときの書き出しの組み合わせとして適切なものを選ぼう。', choices: ['First, / Second,', 'However, / Therefore,', 'For example, / In short,', 'Finally, / First,'], a: 'A(First, / Second,)', exp: 'First, Second, で理由を順に示すと、読み手は理由がいくつあるかすぐに分かります。Also, や In addition, も2つ目の理由に使えます。' },
      { lv: 1, q: '英訳しよう。\n「私は昨日図書館で勉強した。」', a: 'I studied at the library yesterday.', exp: 'yesterday があるので過去形 studied です。場所の at the library、時の yesterday の順に置くのが自然です。' },
      { lv: 1, q: '誤りを直そう。\nI want to be a engineer in the future.', a: 'a → an', exp: 'engineer は母音の音で始まるので、冠詞は an にします。つづりではなく音で a / an を決めます。' },
      { lv: 1, q: '英訳しよう。\n「私は英語を話すことが好きだ。」', a: 'I like speaking English.(I like to speak English.)', exp: 'like は動名詞も to 不定詞もとれます。「〜すること」を表す形を使うことがポイントです。' },
      { lv: 2, q: '英訳しよう。\n「私はコーヒーが好きになった。」', a: 'I have come to like coffee.(I came to like coffee.)', exp: '「〜するようになる」は come to do で表し、like・know・understand など状態を表す動詞と使います。become to do とは言わないので注意します。' },
      { lv: 2, q: '英訳しよう。\n「宿題を終えるのに2時間かかった。」', a: 'It took me two hours to finish my homework.', exp: 'It takes (人) 時間 to do で「(人が)〜するのに…かかる」。過去の文なので took にします。' },
      { lv: 2, q: '次の理由に、具体例を1文加えよう。\nSecond, living in the countryside is good for our health.', a: 'For example, we can breathe clean air and enjoy walking in nature.', exp: '「健康によい」という抽象的な理由を、きれいな空気・自然の中の散歩という具体的な内容で支えています。' },
      { lv: 2, q: '誤りを直そう。\nThere is many reasons for this.', a: 'is → are', exp: 'There 構文では be 動詞の後ろの名詞が主語です。many reasons は複数なので are にします。' },
      { lv: 2, q: '言いすぎにならないように書き直そう。\nStudying abroad is always a good experience.', a: 'Studying abroad is often a good experience.(Studying abroad can be a good experience.)', exp: 'always は例外を認めない強い語です。often や can を使うと、例外があることを認めつつ主張を保てます。' },
      { lv: 2, q: '次の英文の論理の問題点を答えよう。\nI think smartphones are useful. For example, I don\'t like smartphones.', a: '具体例が意見と矛盾している(便利だという意見を支えていない)。', exp: 'For example の後ろは、前の意見を支える具体例でなければなりません。「好きではない」は「便利だ」を支えず、論理が通りません。' },
      { lv: 2, q: '英訳しよう。\n「その本は思っていたより面白かった。」', a: 'The book was more interesting than I (had) expected.', exp: '「思っていたより」は than I expected / than I had expected で表します。interesting は長い形容詞なので more interesting です。' },
      { lv: 2, q: 'Eメールへの返信問題で、相手の質問に答えたあとに書く内容として最も適切なものを選ぼう。\n(相手:What do you usually do on weekends?)', choices: ['質問に関係のない話', '週末の過ごし方の具体例や理由', '相手への悪口', '質問をくり返すだけの文'], a: 'B(週末の過ごし方の具体例や理由)', exp: '質問に答えたら、その答えを具体例や理由でふくらませます。たとえば I usually play tennis. のあとに、だれと・なぜ楽しいかを加えます。' },
      { lv: 3, q: '英訳しよう。\n「人は失って初めてその物の大切さに気づく。」', a: 'People do not realize the importance of something until they lose it.(It is not until people lose something that they realize its importance.)', exp: '「〜して初めて…する」は not … until 〜 で表します。強調構文 It is not until 〜 that … も使えます。' },
      { lv: 3, q: '次のテーマについて、反対の立場で理由を1つ、具体例つきで書こう。\nテーマ:Students should study only subjects they like.', a: '例:I disagree because students can find new interests in other subjects. For example, a student who did not like science may become interested in it after doing an experiment.', exp: '反対の理由(他の教科で新しい興味が見つかる)を述べ、For example で具体的な場面を示します。理由と例が論理的につながっているかを確かめます。' },
      { lv: 3, q: '次の要約の問題点を答え、直そう。\n本文の要点:Online shopping is convenient, but it can increase packaging waste.\n要約:Online shopping is convenient.', a: '問題点:後半の「包装ごみが増える」という欠点を落としている。直し方:Online shopping is convenient but may create more packaging waste.', exp: 'but の後ろには筆者の大事な指摘が来ることが多いです。利点と欠点の両方をふくめて、つなぎの語で関係を示します。' },
      { lv: 3, q: '英訳しよう。\n「インターネットのおかげで、世界中の人と簡単に連絡をとれるようになった。」', a: 'The internet has made it easy for us to communicate with people all over the world.(Thanks to the internet, we can easily communicate with people all over the world.)', exp: '無生物主語 + make it easy for 人 to do、または Thanks to 〜 で表します。「〜ようになった」という今への変化は現在完了が合います。' },
      { lv: 3, q: '意見論述で、反対意見にふれてから自分の主張を述べる1文を書こう。\n(テーマ:制服に賛成の立場で)', a: '例:Some people say that uniforms take away students\' freedom, but I believe they help students focus on studying.', exp: 'Some people say 〜, but I believe … のように反対意見を先に認めると、主張がかたよらず説得力が増します。but の後ろに自分の立場をはっきり書きます。' }
    ]
  });

  add('ek_speaking', {
    pat: [
      { name: '音読:意味のまとまりで区切る', freq: 'よく出る', when: '面接の最初の音読で、長い文をどこで区切り、どの語を強く読むかを判断するときです。', how: ['黙読の時間に、主語のかたまり・前置詞句・接続詞の前で区切りの印を入れます。', '名詞・動詞・形容詞などの内容語を強く、冠詞・前置詞を弱く読みます。', 'タイトルもふくめて読み、知らない語は止まらずに、つづりから推測して読み進めます。'], ex: { q: '次の文を音読するとき、区切るのに適した箇所を2つ答えよう。\nMany people in Japan / enjoy visiting hot springs / during the winter.', a: 'people in Japan の後ろ と hot springs の後ろ', exp: '主語のかたまり(Many people in Japan)、動詞のかたまり(enjoy visiting hot springs)、時を表す前置詞句(during the winter)で区切ると、意味が伝わりやすくなります。' } },
      { name: 'パッセージについての質問に答える', freq: 'とてもよく出る', when: '面接で、音読した文章の内容について Why・How などで質問されるときです。', how: ['質問の疑問詞と主語を聞き取り、本文のどの文が答えにあたるかを探します。', '答えの文の主語を代名詞(They・It)に置きかえます。', 'Why の質問には because 〜 で答えるか、By doing so など本文の表現を自分の文に直して答えます。'], ex: { q: '本文:Some towns hold events for tourists. By doing so, they try to make their towns more popular.\n質問:How do some towns try to make their towns more popular?', a: 'By holding events for tourists.', exp: 'By doing so の doing so は、前の文の hold events for tourists を指しています。How の質問なので、By holding 〜(〜することによって)と、指している内容を具体的にして答えます。' } },
      { name: 'イラストの人物の動作を説明する', freq: 'とてもよく出る', when: '面接で、イラストの中の人物が何をしているかを説明する問題です。', how: ['人物ごとに、何をしているかを日本語で短く確かめます。', '動作は現在進行形 A man is 〜ing で表します。', '知らない単語は別の言い方に置きかえます(「水やり」→ give water to the flowers)。'], ex: { q: 'イラスト:女の子が花に水をやっている。\nこの動作を英語で説明しよう。', a: 'A girl is watering the flowers.(A girl is giving water to the flowers.)', exp: '動作を表すので現在進行形にします。water は動詞で「水をやる」の意味があります。思い出せなければ give water to 〜 と言いかえれば十分伝わります。' } },
      { name: '意見を言う型:立場 + 理由', freq: 'とてもよく出る', when: 'Do you think 〜? や Some people say 〜. What do you think? のように、自分の意見を聞かれる質問です。', how: ['最初に Yes. / No. や I think so. / I don\'t think so. で立場をはっきり言います。', '理由を1〜2文で続けます(Because 〜. / For example, 〜.)。', 'Why not? と聞き返されたら、No の理由を具体的に言います。'], ex: { q: '質問:Do you think students should do volunteer work?\n賛成の立場で、理由を1文つけて答えよう。', a: 'Yes. Volunteer work helps students learn how to work with other people.', exp: '最初に Yes. で立場をはっきり示し、理由を1文で続けています。「他の人と協力する方法を学べる」という具体的な利点があるので、説得力があります。' } },
      { name: '聞き返し・つなぎのことば', freq: 'よく出る', when: '面接で質問が聞き取れなかったときや、答えを考えるのに少し時間がほしいときです。', how: ['聞き取れなかったら、だまらずに I\'m sorry. Could you say that again, please? と聞き返します。', '考える時間がほしいときは Let me see. / Well, … などのつなぎのことばを使います。', '長い沈黙を避け、聞き返したあとは落ち着いて答えます。'], ex: { q: '面接官の質問が聞き取れなかった。聞き返すときの英語として最も適切なものを選ぼう。\n① What? ② Again. ③ I\'m sorry. Could you repeat the question, please? ④ I don\'t know.', a: '③', exp: '③はていねいに質問をくり返してもらう表現です。① What? は失礼に聞こえることがあり、② は命令のようです。④ では答えをあきらめたことになります。' } }
    ],
    more: [
      { lv: 1, q: 'イラスト:男の人が自転車に乗っている。この動作を英語で説明しよう。', a: 'A man is riding a bike.', exp: '人物の動作は現在進行形 is 〜ing で表します。「自転車に乗る」は ride a bike です。' },
      { lv: 1, q: '質問:Do you like cooking?\nNo で答え、理由を1文つけよう。', a: 'No. I\'m not good at cooking.(などのように、理由を加える)', exp: 'No. だけで終わらず、理由を加えると評価が上がります。be good at 〜 は「〜が得意だ」です。' },
      { lv: 1, q: '考える時間がほしいときに使うつなぎのことばを選ぼう。', choices: ['Let me see.', 'Goodbye.', 'Thank you.', 'Excuse me, I\'m leaving.'], a: 'A(Let me see.)', exp: 'Let me see.(ええと)は、答えを考える間を自然につなぐ表現です。Well, … も同じように使えます。' },
      { lv: 1, q: 'イラスト:女の人が窓をそうじしている。この動作を英語で説明しよう。', a: 'A woman is cleaning the window.', exp: '現在進行形 is cleaning を使います。clean は動詞で「そうじする」です。' },
      { lv: 1, q: '面接室に入ったときの最初のあいさつとして適切なものを選ぼう。', choices: ['Hello.', 'See you.', 'Bye.', 'Sorry.'], a: 'A(Hello.)', exp: '入室したら Hello. や Good morning. とあいさつします。面接では態度も評価されるので、はっきりした声で言いましょう。' },
      { lv: 1, q: 'イラスト:男の子が犬を散歩させている。この動作を英語で説明しよう。', a: 'A boy is walking a dog.', exp: 'walk には「(犬を)散歩させる」という他動詞の意味があります。A boy is taking a dog for a walk. とも言えます。' },
      { lv: 1, q: '質問:What do you like to do in your free time?\n答えの1文を英語で書こう。', a: 'I like to play the guitar.(などのように、具体的な活動を答える)', exp: 'I like to 〜 / I like 〜ing で答えます。質問の表現(like to do)をそのまま使うと答えやすくなります。' },
      { lv: 2, q: '本文:Many people use online maps. By doing so, they can find places easily.\n質問:How can many people find places easily?', a: 'By using online maps.', exp: 'By doing so の doing so は use online maps を指しています。How の質問なので、By using 〜 と具体的に答えます。' },
      { lv: 2, q: '質問:Do you think it is good for students to have part-time jobs?\n反対の立場で、理由を1文つけて答えよう。', a: 'No. Students may not have enough time to study.(などのように、理由を加える)', exp: '最初に No. で立場を示し、勉強の時間が足りなくなるかもしれない、という理由を続けています。may を使うと言いすぎにならずにすみます。' },
      { lv: 2, q: 'イラスト:女の人が箱を運ぼうとしている(まだ持ち上げていない)。この様子を英語で説明しよう。', a: 'A woman is going to carry a box.(A woman is trying to lift a box.)', exp: 'まだ運び始めていないので、is carrying ではなく is going to carry(これから運ぼうとしている)で表します。動作の前後を区別します。' },
      { lv: 2, q: 'Why not? と聞き返されたときの答え方として最も適切なものを選ぼう。\n(質問:Do you think people should use cars less? → 答え:No. → Why not?)', choices: ['もう一度 No. と言う', 'No と考える理由を具体的に言う', 'Yes. に答えを変える', 'だまる'], a: 'B(No と考える理由を具体的に言う)', exp: 'Why not? は「なぜそう思わないのか」という理由の質問です。たとえば Cars are necessary for people who live in the countryside. と具体的に答えます。' },
      { lv: 2, q: '英語で言いかえよう。\n「(イラストで)男の人が電話をかけている。」ただし call を使わないこと。', a: 'A man is talking on the phone.(A man is making a phone call. は call を使うので不可)', exp: '知らない語や使えない語があっても、talk on the phone(電話で話す)のように別の言い方で伝えられます。' },
      { lv: 2, q: '音読で、タイトルの扱いとして最も適切なものを選ぼう。', choices: ['タイトルは読まない', 'タイトルも本文と同じように読む', 'タイトルだけ大きな声でさけぶ', 'タイトルは最後に読む'], a: 'B(タイトルも本文と同じように読む)', exp: '音読ではタイトルから読み始めます。タイトルを読むと、文章のテーマを面接官にも自分にも示すことができます。' },
      { lv: 2, q: '質問:Some people say that people should read newspapers every day. What do you think about that?\n賛成の立場で答えよう。', a: 'I agree. Reading newspapers helps us understand what is happening in the world.', exp: 'What do you think 〜? には I agree. / I disagree. で立場を示します。そのあと、世の中の出来事が分かるという理由を続けます。' },
      { lv: 2, q: '答えの途中で単語が出てこなくなった。最も適切な対応を選ぼう。', choices: ['その場でだまりこむ', '日本語で言う', '知っている語で言いかえる', '面接を終わりにしてもらう'], a: 'C(知っている語で言いかえる)', exp: '知らない語は、知っている語の組み合わせで説明すれば伝わります。たとえば「消防士」が出てこなければ a person who puts out fires と言えます。' },
      { lv: 3, q: '質問:Do you think Japan should accept more tourists from abroad?\n賛成の立場で、理由と具体例を合わせて2文で答えよう。', a: 'Yes. Tourists can help local economies. For example, they spend money at shops and hotels in small towns.', exp: '立場(Yes)→ 理由(地域の経済を助ける)→ 具体例(店やホテルでお金を使う)の順に答えると、短くても筋の通った答えになります。' },
      { lv: 3, q: '抽象的な質問に、身近な具体例を使って答えよう。\n質問:Do you think technology makes our lives better?', a: 'Yes. For example, my grandmother lives far away, but we can talk on video calls every week.', exp: '「技術が生活をよくするか」という大きな質問も、家族とビデオ通話で話せるという身近な例に引き寄せると、答えやすく説得力も増します。' },
      { lv: 3, q: '質問:Do you think students should study abroad?\n答え:Yes. It is good.\nこの答えを、評価が上がるように直そう。', a: 'Yes. Students can improve their language skills and learn about different cultures.', exp: 'It is good. だけでは理由として抽象的すぎます。「語学力が伸びる」「ちがう文化を学べる」のように、何がよいのかを具体的に言います。' },
      { lv: 3, q: '本文:Some supermarkets sell food at lower prices near closing time. In this way, they try to reduce food waste.\n質問:How do some supermarkets try to reduce food waste?', a: 'By selling food at lower prices near closing time.', exp: 'In this way(このようにして)は前の文の内容を指しています。How の質問には By + 動名詞で、方法を具体的に答えます。' },
      { lv: 3, q: '面接で、意見を述べたあと少し時間が残った。話を広げる表現として最も適切なものを選ぼう。', choices: ['That\'s all.', 'Also, I think …', 'I don\'t know.', 'Sorry.'], a: 'B(Also, I think …)', exp: 'Also, I think … や In addition, … を使うと、2つ目の理由や具体例を加えて話を広げられます。ただし最初の意見とずれないように注意します。' }
    ]
  });
})(WPS.LESSONS);
